            .eq("user_id", user.id)
            .single();

        if (!candidate) {
            return { success: false, error: "Candidate profile not found" };
        }

        // Validate data
        const validated = experienceSchema.parse(data);

        // Insert new experience
        const { error } = await supabase
            .from("work_experiences")
            .insert({
                candidate_id: candidate.id,
                ...validated,
