                const path = err.path.join(".");
                if (!fieldErrors[path]) fieldErrors[path] = [];
                fieldErrors[path].push(err.message);
            });
            return {
                success: false,
                message: "Validation failed. Please check your inputs.",
                errors: fieldErrors,
            };
        }

        const data = validation.data;

        // 1. Generate Candidate ID (UUID)
