"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { logAuth, logError, getRequestInfo } from "@/lib/logger";

export interface ActionState {
    success: boolean;
    message: string;
    redirectTo?: string;
    errors?: Record<string, string[]>;
}

/**
 * Universal Login for Candidates and Employers
 * Automatically detects user role and redirects appropriately
 * MIS login remains separate
 * OPTIMIZED: Minimal database queries for faster login
 */
export async function universalLogin(
    _prevState: ActionState | null,
    formData: FormData
): Promise<ActionState> {
    const email = formData.get("email") as string;
    const password = formData.get("password") as string;
    const returnUrl = formData.get("returnUrl") as string | null;

    // Basic validation
    if (!email || !password) {
        return {
            success: false,
            message: "Email and password are required.",
        };
    }

    try {
        const supabase = await createClient();
        const adminClient = createAdminClient();

        const { ipAddress } = await getRequestInfo();

        // OPTIMIZATION 1: Authenticate first (this is the slowest operation)
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
            email,
            password,
        });

        if (authError || !authData.session) {
            console.error("Supabase auth error:", authError);
            await logAuth("universal_login_failed", undefined, undefined, { email, reason: "invalid_credentials" }, ipAddress || undefined);
            return {
                success: false,
                message: "Invalid email or password.",
            };
        }

        // OPTIMIZATION 2: Fetch user data with role in single query AFTER auth
        const { data: userData, error: userError } = await adminClient
            .from("users")
            .select("role, status, email_verified")
            .eq("id", authData.user.id)
            .single();

        if (userError || !userData) {
            return {
                success: false,
                message: "User data not found.",
            };
        }

        // Reject MIS users - they should use /mis/login
        if (userData.role === "mis") {
            return {
                success: false,
                message: "Please use the MIS admin login page.",
            };
        }

        // Only allow candidate and employer roles
        if (userData.role !== "candidate" && userData.role !== "employer") {
            return {
                success: false,
                message: "Invalid user role.",
            };
        }

        // Check email verification
        if (!userData.email_verified) {
            const verifyPath = userData.role === "candidate"
                ? "/candidate/verify-email"
                : "/employer/verify-email";

            return {
                success: false,
                message: "Please verify your email before logging in.",
                redirectTo: `${verifyPath}?email=${encodeURIComponent(email)}`,
            };
        }

        // Check account status
        if (userData.status !== "active") {
            return {
                success: false,
                message: "Your account is not active. Please contact support.",
            };
        }

        // OPTIMIZATION 3: Role-specific queries only when needed
        if (userData.role === "candidate") {
            // Single query for candidate profile completion
            const { data: candidateData } = await adminClient
                .from("candidates")
                .select("profile_completed")
                .eq("user_id", authData.user.id)
                .single();

            // Use returnUrl if provided, otherwise use default redirect
            const defaultRedirect = candidateData?.profile_completed
                ? "/candidate/dashboard"
                : "/candidate/create-profile";

            await logAuth("universal_login_success", authData.user.id, "candidate", { email }, ipAddress || undefined);
            return {
                success: true,
                message: "Login successful!",
                redirectTo: returnUrl || defaultRedirect,
            };
        }

        if (userData.role === "employer") {
            // Single query with join for employer + company data
            const { data: employerData } = await adminClient
                .from("employers")
                .select("profile_completed, companies!inner(profile_completed)")
                .eq("user_id", authData.user.id)
                .single();

            if (!employerData) {
                return {
                    success: true,
                    message: "Login successful!",
                    redirectTo: "/employer/complete-profile",
                };
            }

            const companyData = (employerData as any).companies;
            const isProfileIncomplete =
                !employerData.profile_completed || !companyData?.profile_completed;

            // Use returnUrl if provided, otherwise use default redirect
            const defaultRedirect = isProfileIncomplete ? "/employer/complete-profile" : "/employer/dashboard";

            await logAuth("universal_login_success", authData.user.id, "employer", { email }, ipAddress || undefined);
            return {
                success: true,
                message: "Login successful!",
                redirectTo: returnUrl || defaultRedirect,
            };
        }

        // Fallback
        return {
            success: false,
            message: "An unexpected error occurred. Please try again.",
        };
    } catch (error) {
        console.error("Universal login error:", error);
        await logError({ source: "universal-auth.ts:universalLogin", errorType: "UniversalLoginError", message: error instanceof Error ? error.message : String(error) });
        return {
            success: false,
            message: "An unexpected error occurred. Please try again.",
        };
    }
}

"use server";

import { GoogleGenAI } from "@google/genai";
import { brVerificationResultSchema, type BRVerificationResult } from "@/lib/validations/employer-schema";
import { logError } from "@/lib/logger";

const genAI = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || "" });

export type BRVerificationState = {
    success: boolean;
    message: string;
    data?: BRVerificationResult;
    error?: string;
};

const VERIFICATION_PROMPT = `You are an expert document verification system analyzing a Business Registration (BR) certificate. 

Extract the following information from the provided Business Registration certificate and return it as a JSON object:

IMPORTANT:
- Return ONLY valid JSON, no markdown formatting or code blocks
- Extract the company/business name EXACTLY as shown on the certificate
- Extract the registration number/BR number EXACTLY as shown (including prefix like PV, PB, GR, HP and numbers)
- The BR number format should be: PREFIX + SPACE + NUMBERS (e.g., "PV 12345678" or "PB 12345678")
- Common prefixes: PV (Private Limited Company), PB (Public Limited Company), GR (Guarantee Company), HP (Hybrid/Other types)
- If information is not clearly visible or found, use null for that field
- Preserve the spacing and format of the registration number as it appears on the certificate

Extract this structure:
{
    "companyName": "string (exact company name from certificate)",
    "registrationNumber": "string (exact BR/registration number from certificate with prefix)",
    "extractedText": "string (any other relevant text found on the document for context)"
}

Certificate image/document is provided below. Analyze it carefully and extract the required information.
`;

export async function verifyBRCertificate(
    fileBase64: string,
    mimeType: string,
    userProvidedCompanyName: string,
    userProvidedRegNumber: string
): Promise<BRVerificationState> {
    try {
        if (!process.env.GEMINI_API_KEY) {
            return {
                success: false,
                message: "AI verification service not configured",
                error: "GEMINI_API_KEY not found in environment variables",
            };
        }

        // Prepare the content for Gemini
        const parts = [];

        if (mimeType === "application/pdf" || mimeType.includes("image")) {
            // For PDF and images, use inline data
            parts.push({
                inlineData: {
                    mimeType: mimeType,
                    data: fileBase64,
                },
            });
            parts.push({ text: VERIFICATION_PROMPT });
        } else {
            return {
                success: false,
                message: "Invalid file format. Please upload a PDF or image file.",
                error: "Unsupported file type",
            };
        }

        // Call Gemini AI to extract data from certificate
        const result = await genAI.models.generateContent({
            model: "gemini-2.5-flash",
            contents: [{ role: "user", parts: parts as any[] }],
        });
        const text = result.text || "";

        // Clean the response (remove markdown code blocks if present)
        let cleanedText = text
            .replace(/```json\n?/g, "")
            .replace(/```\n?/g, "")
            .trim();

        // Parse JSON
        let parsedData: unknown;
        try {
            parsedData = JSON.parse(cleanedText);
        } catch (parseError) {
            console.error("JSON parse error:", parseError);
            console.error("Raw text:", cleanedText);
            return {
                success: false,
                message: "Failed to analyze certificate. The document may be unclear or in an unsupported format.",
                error: "Invalid JSON response from AI",
            };
        }

        // Extract the data
        const extractedData = parsedData as { companyName?: string; registrationNumber?: string; extractedText?: string };

        // Normalize strings for comparison (trim, lowercase, remove extra spaces)
        const normalize = (str: string) => str.trim().toLowerCase().replace(/\s+/g, " ");

        // Normalize BR number for comparison (remove spaces, convert to uppercase)
        const normalizeBRNumber = (str: string) => str.trim().toUpperCase().replace(/\s+/g, "");

        const extractedCompanyName = extractedData.companyName || "";
        const extractedRegNumber = extractedData.registrationNumber || "";

        const companyNameMatch =
            extractedCompanyName &&
            normalize(extractedCompanyName) === normalize(userProvidedCompanyName);

        const regNumberMatch =
            extractedRegNumber &&
            normalizeBRNumber(extractedRegNumber) === normalizeBRNumber(userProvidedRegNumber);

        // Determine match status and confidence
        let matchesInput = false;
        let confidence: "high" | "medium" | "low" = "low";

        if (companyNameMatch && regNumberMatch) {
            matchesInput = true;
            confidence = "high";
        } else if (companyNameMatch || regNumberMatch) {
            matchesInput = false;
            confidence = "medium";
        } else {
            matchesInput = false;
            confidence = "low";
        }

        const verificationResult: BRVerificationResult = {
            companyName: extractedData.companyName,
            registrationNumber: extractedData.registrationNumber,
            matchesInput,
            confidence,
            extractedText: extractedData.extractedText,
        };

        // Validate with Zod schema
        const validationResult = brVerificationResultSchema.safeParse(verificationResult);

        if (!validationResult.success) {
            console.error("Validation errors:", validationResult.error);
            return {
                success: false,
                message: "Failed to validate extracted data",
                error: "Schema validation failed",
            };
        }

        if (matchesInput) {
            return {
                success: true,
                message: "Certificate verified successfully! Company details match the provided information.",
                data: validationResult.data,
            };
        } else {
            // Build specific error messages for each mismatch
            const errors: string[] = [];
            
            if (!companyNameMatch) {
                errors.push(`❌ Company Name Mismatch:\n   • You entered: "${userProvidedCompanyName}"\n   • Certificate shows: "${extractedCompanyName || 'Not found'}"`);
            }
            
            if (!regNumberMatch) {
                errors.push(`❌ Business Registration Number Mismatch:\n   • You entered: "${userProvidedRegNumber}"\n   • Certificate shows: "${extractedRegNumber || 'Not found'}"`);
            }

            const errorMessage = `Certificate verification failed:\n\n${errors.join('\n\n')}\n\nPlease check your inputs and ensure they exactly match the information on your BR certificate.`;

            return {
                success: false,
                message: errorMessage,
                data: validationResult.data,
            };
        }
    } catch (error) {
        console.error("BR verification error:", error);
        await logError({ source: "verify-br-certificate.ts:verifyBRCertificate", errorType: "BRVerificationError", message: error instanceof Error ? error.message : String(error) });
        return {
            success: false,
            message: "Failed to verify certificate. Please try again or contact support.",
            error: error instanceof Error ? error.message : "Unknown error",
        };
    }
}

import { createClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { NextResponse } from 'next/server';
import { sendCandidateRoundCancellationEmail } from '@/lib/interview-emails';
import { logBusiness, logError } from '@/lib/logger';
import { getUserTimezoneByEmail } from '@/lib/user-timezone';

// POST /api/candidate/interview-rounds/[roundId]/cancel-round
export async function POST(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { cancellation_reason } = await request.json();

        if (!cancellation_reason || cancellation_reason.trim() === '') {
            return NextResponse.json(
                { success: false, error: 'Cancellation reason is required' },
                { status: 400 }
            );
        }

        const { data: { user } } = await authClient.auth.getUser();

        if (!user) {
            return NextResponse.json(
                { success: false, error: 'Unauthorized' },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        const { data: candidate, error: candidateError } = await supabase
            .from('candidates')
            .select('id')
            .eq('user_id', user.id)
            .single();

        if (candidateError || !candidate) {
            return NextResponse.json(
                { success: false, error: 'Candidate profile not found' },
                { status: 404 }
            );
        }

        const { roundId } = await params;

        // Fetch round and verify ownership via invitation -> candidate
        const { data: round, error: roundError } = await supabase
            .from('interview_rounds')
            .select(`
                id,
                status,
                interview_confirmed,
                round_canceled,
                invitation_id,
                invitation:job_invitations(candidate_id)
            `)
            .eq('id', roundId)
            .single();

        if (roundError || !round) {
            return NextResponse.json(
                { success: false, error: 'Interview round not found' },
                { status: 404 }
            );
        }

        const invitation = round.invitation as any;
        if (!invitation || invitation.candidate_id !== candidate.id) {
            return NextResponse.json(
                { success: false, error: 'Interview round not found or unauthorized' },
                { status: 404 }
            );
        }

        if (!round.interview_confirmed) {
            return NextResponse.json(
                { success: false, error: 'Interview round is not confirmed yet' },
                { status: 400 }
            );
        }

        if (round.round_canceled) {
            return NextResponse.json(
                { success: false, error: 'Interview round is already canceled' },
                { status: 400 }
            );
        }

        const { error: updateError } = await supabase
            .from('interview_rounds')
            .update({
                round_canceled: true,
                canceled_by: 'candidate',
                cancellation_reason: cancellation_reason.trim(),
                canceled_at: new Date().toISOString(),
                status: 'canceled',
            })
            .eq('id', roundId);

        if (updateError) {
            console.error('Error canceling interview round:', updateError);
            return NextResponse.json(
                { success: false, error: 'Failed to cancel interview round' },
                { status: 500 }
            );
        }

        // Send cancellation email to employer (async - non-blocking)
        const { data: fullRound } = await supabase
            .from('interview_rounds')
            .select(`
                round_label,
                round_number,
                selected_time_slot,
                confirmed_time,
                invitation:job_invitations(
                    job_designation,
                    candidate:candidates(first_name),
                    employer:employers(first_name, email)
                )
            `)
            .eq('id', roundId)
            .single();

        if (fullRound) {
            const inv = fullRound.invitation as any;
            const employer = inv?.employer as any;
            const candidateInfo = inv?.candidate as any;
            const timeSlot = fullRound.selected_time_slot as any;
            const roundLabel = fullRound.round_label || `Round ${fullRound.round_number}`;

            const finalTime = timeSlot?.is_alternative && fullRound.confirmed_time
                ? fullRound.confirmed_time
                : timeSlot?.time || '';

            if (employer?.email) {
                getUserTimezoneByEmail(employer.email).then(recipientTz =>
                    sendCandidateRoundCancellationEmail(
                        employer.email,
                        employer.first_name,
                        candidateInfo?.first_name || '',
                        inv?.job_designation || '',
                        roundLabel,
                        timeSlot?.date || '',
                        finalTime,
                        cancellation_reason,
                        recipientTz
                    )
                ).catch(err => console.error('Email send error:', err));
            }
        }

        await logBusiness("round_canceled_by_candidate", user.id, "candidate", "interview_round", roundId, { reason: cancellation_reason });

        return NextResponse.json({
            success: true,
            message: 'Interview round canceled successfully'
        });
    } catch (error) {
        console.error('API error:', error);
        await logError({
            source: "api/candidate/interview-rounds/cancel-round:POST",
            errorType: "APIError",
            message: error instanceof Error ? error.message : String(error)
        });
        return NextResponse.json(
            { success: false, error: 'Internal server error' },
            { status: 500 }
        );
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";
import { logBusiness, logError } from "@/lib/logger";

// POST /api/candidate/interview-rounds/:roundId/respond
// Candidate responds to an interview round invitation
export async function POST(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { roundId } = await params;
        const body = await request.json();
        const { action, selected_time_slot, interview_mode } = body;

        // Validate action
        if (!['accept', 'decline'].includes(action)) {
            return NextResponse.json(
                { success: false, error: "Invalid action. Must be 'accept' or 'decline'" },
                { status: 400 }
            );
        }

        // For accept action, validate required fields
        if (action === 'accept') {
            if (!selected_time_slot) {
                return NextResponse.json(
                    { success: false, error: "Selected time slot is required when accepting" },
                    { status: 400 }
                );
            }
            // interview_mode is pre-set by employer; accept if provided, skip validation if absent
        }

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();
        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Get candidate record
        const { data: candidate, error: candidateError } = await supabase
            .from('candidates')
            .select('id')
            .eq('user_id', user.id)
            .single();

        if (candidateError || !candidate) {
            return NextResponse.json(
                { success: false, error: "Candidate profile not found" },
                { status: 404 }
            );
        }

        // Get the interview round and verify it belongs to this candidate
        const { data: round, error: roundError } = await supabase
            .from('interview_rounds')
            .select(`
                id,
                round_number,
                status,
                invitation_id,
                invitation:job_invitations!inner(
                    id,
                    candidate_id,
                    company_id,
                    job_designation
                )
            `)
            .eq('id', roundId)
            .single();

        if (roundError || !round) {
            return NextResponse.json(
                { success: false, error: "Interview round not found" },
                { status: 404 }
            );
        }

        const invitation = round.invitation as any;

        // Verify the round belongs to this candidate
        if (invitation.candidate_id !== candidate.id) {
            return NextResponse.json(
                { success: false, error: "Unauthorized access to this interview round" },
                { status: 403 }
            );
        }

        // Check if round can be responded to
        if (round.status !== 'pending' && round.status !== 'viewed') {
            return NextResponse.json(
                { success: false, error: "This round has already been responded to" },
                { status: 400 }
            );
        }

        // Update the round based on action
        const updateData: any = {
            status: action === 'accept' ? 'accepted' : 'declined',
            responded_at: new Date().toISOString()
        };

        if (action === 'accept') {
            updateData.selected_time_slot = selected_time_slot;
            updateData.interview_mode = interview_mode;
