import { createClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import { NextResponse } from 'next/server';
import { sendEmployerRoundCancellationEmail } from '@/lib/interview-emails';
import { logBusiness, logError } from '@/lib/logger';
import { getUserTimezoneByEmail } from '@/lib/user-timezone';

// POST /api/employer/interview-rounds/[roundId]/cancel-round
export async function POST(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { cancellation_reason } = await request.json();

        if (!cancellation_reason || cancellation_reason.trim() === '') {
            return NextResponse.json(
                { success: false, error: 'Cancellation reason is required' },
                { status: 400 }
            );
        }

        const { data: { user } } = await authClient.auth.getUser();

        if (!user) {
            return NextResponse.json(
                { success: false, error: 'Unauthorized' },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: 'Employer profile not found' },
                { status: 404 }
            );
        }

        const { roundId } = await params;

        // Fetch round and verify ownership via invitation -> company
        const { data: round, error: roundError } = await supabase
            .from('interview_rounds')
            .select(`
                id,
                status,
                interview_confirmed,
                round_canceled,
                invitation_id,
                invitation:job_invitations(company_id)
            `)
            .eq('id', roundId)
            .single();

        if (roundError || !round) {
            return NextResponse.json(
                { success: false, error: 'Interview round not found' },
                { status: 404 }
            );
        }

        const invitation = round.invitation as any;
        if (!invitation || invitation.company_id !== employer.company_id) {
            return NextResponse.json(
                { success: false, error: 'Interview round not found or unauthorized' },
                { status: 404 }
            );
        }

        if (round.round_canceled) {
            return NextResponse.json(
                { success: false, error: 'Interview round is already canceled' },
                { status: 400 }
            );
        }

        const { error: updateError } = await supabase
            .from('interview_rounds')
            .update({
                round_canceled: true,
                canceled_by: 'employer',
                cancellation_reason: cancellation_reason.trim(),
                canceled_at: new Date().toISOString(),
                status: 'canceled',
            })
            .eq('id', roundId);

        if (updateError) {
            console.error('Error canceling interview round:', updateError);
            return NextResponse.json(
                { success: false, error: 'Failed to cancel interview round' },
                { status: 500 }
            );
        }

        // Send cancellation email to candidate (async - non-blocking)
        const { data: fullRound } = await supabase
            .from('interview_rounds')
            .select(`
                round_label,
                round_number,
                selected_time_slot,
                confirmed_time,
                invitation:job_invitations(
                    job_designation,
                    candidate:candidates(first_name, email),
                    company:companies(company_name)
                )
            `)
            .eq('id', roundId)
            .single();

        if (fullRound) {
            const inv = fullRound.invitation as any;
            const candidateInfo = inv?.candidate as any;
            const company = inv?.company as any;
            const timeSlot = fullRound.selected_time_slot as any;
            const roundLabel = fullRound.round_label || `Round ${fullRound.round_number}`;

            const finalTime = timeSlot?.is_alternative && fullRound.confirmed_time
                ? fullRound.confirmed_time
                : timeSlot?.time || '';

            if (candidateInfo?.email) {
                getUserTimezoneByEmail(candidateInfo.email).then(recipientTz =>
                    sendEmployerRoundCancellationEmail(
                        candidateInfo.email,
                        candidateInfo.first_name,
                        company?.company_name || '',
                        inv?.job_designation || '',
                        roundLabel,
                        timeSlot?.date || '',
                        finalTime,
                        cancellation_reason,
                        recipientTz
                    )
                ).catch(err => console.error('Email send error:', err));
            }
        }

        await logBusiness("round_canceled_by_employer", user.id, "employer", "interview_round", roundId, { reason: cancellation_reason });

        return NextResponse.json({
            success: true,
            message: 'Interview round canceled successfully'
        });
    } catch (error) {
        console.error('API error:', error);
        await logError({
            source: "api/employer/interview-rounds/cancel-round:POST",
            errorType: "APIError",
            message: error instanceof Error ? error.message : String(error)
        });
        return NextResponse.json(
            { success: false, error: 'Internal server error' },
            { status: 500 }
        );
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";
import { logBusiness, logError } from "@/lib/logger";
import { sendInterviewConfirmedEmail } from "@/lib/interview-emails";
import { getUserTimezoneByEmail } from "@/lib/user-timezone";

// POST /api/employer/interview-rounds/:roundId/confirm
// Employer confirms an interview round after candidate acceptance
export async function POST(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { roundId } = await params;
        const body = await request.json();
        const { confirmed_time, meeting_link } = body;

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();
        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Get employer record
        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id, first_name, last_name')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        // Get the interview round and verify permissions
        const { data: round, error: roundError } = await supabase
            .from('interview_rounds')
            .select(`
                id,
                round_number,
                round_label,
                status,
                selected_time_slot,
                interview_mode,
                interview_address,
                invitation:job_invitations!inner(
                    id,
                    company_id,
                    candidate_id,
                    job_designation,
                    candidate:candidates(
                        first_name,
                        last_name,
                        email
                    )
                )
            `)
            .eq('id', roundId)
            .single();

        if (roundError || !round) {
            return NextResponse.json(
                { success: false, error: "Interview round not found" },
                { status: 404 }
            );
        }

        const invitation = round.invitation as any;

        // Verify the round belongs to this company
        if (invitation.company_id !== employer.company_id) {
            return NextResponse.json(
                { success: false, error: "Unauthorized access to this interview round" },
                { status: 403 }
            );
        }

        // Check if round is in accepted status
        if (round.status !== 'accepted') {
            return NextResponse.json(
                { success: false, error: "Can only confirm rounds that have been accepted by the candidate" },
                { status: 400 }
            );
        }

        // Validate required fields based on interview mode
        const selectedSlot = round.selected_time_slot as any;
        const isAlternative = selectedSlot?.is_alternative;

        if (isAlternative && !confirmed_time) {
            return NextResponse.json(
                { success: false, error: "Confirmed time is required for alternative dates" },
                { status: 400 }
            );
        }

        if (round.interview_mode === 'online' && !meeting_link) {
            return NextResponse.json(
                { success: false, error: "Meeting link is required for online interviews" },
                { status: 400 }
            );
        }
        // Physical: address was already provided when the round was created — no re-entry needed

        // Update the round with confirmation details
        const updateData: any = {
            interview_confirmed: true,
            status: 'confirmed',
            confirmed_at: new Date().toISOString()
        };

        if (confirmed_time) {
            updateData.confirmed_time = confirmed_time;
        }
        if (meeting_link) {
            updateData.meeting_link = meeting_link;
        }

        const { error: updateError } = await supabase
            .from('interview_rounds')
            .update(updateData)
            .eq('id', roundId);

        if (updateError) {
            console.error('Error confirming interview round:', updateError);
            return NextResponse.json(
                { success: false, error: "Failed to confirm interview round" },
                { status: 500 }
            );
        }

        // Get company info for email
        const { data: company } = await supabase
            .from('companies')
            .select('company_name')
            .eq('id', employer.company_id)
            .single();

        // Send confirmation email to candidate
        const candidate = invitation.candidate;
        if (candidate && company) {
            const recipientTz = await getUserTimezoneByEmail(candidate.email);
            const interviewDate = selectedSlot?.date;
            const interviewTime = confirmed_time || selectedSlot?.time;
            
            // For online use the newly provided meeting link; for physical use address already on the round
            const meetingLinkOrAddress = round.interview_mode === 'online'
                ? meeting_link
                : (round.interview_address ?? '');
            
            sendInterviewConfirmedEmail(
                candidate.email,
                candidate.first_name,
                company.company_name,
                invitation.job_designation,
                interviewDate,
                interviewTime,
                round.interview_mode,
                meetingLinkOrAddress,
                invitation.id,
                recipientTz
            ).catch(err => console.error('Email send error:', err));
        }

        await logBusiness(
            "interview_round_confirmed",
            user.id,
            "employer",
            "interview_round",
            roundId,
            { 
                round_number: round.round_number,
                invitation_id: invitation.id,
                interview_mode: round.interview_mode
            }
        );

        return NextResponse.json({
            success: true,
            message: "Interview round confirmed successfully",
            data: {
                round_id: roundId,
                round_number: round.round_number,
                status: 'confirmed'
            }
        });

    } catch (error) {
        console.error('API error:', error);
        await logError({
            source: "api/employer/interview-rounds/confirm:POST",
            errorType: "APIError",
            message: error instanceof Error ? error.message : String(error)
        });
        return NextResponse.json(
            { success: false, error: "Internal server error" },
            { status: 500 }
        );
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";

// PATCH /api/employer/interview-rounds/[roundId]/edit
// Allows employer to update time slots before candidate accepts
export async function PATCH(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { roundId } = await params;

        const { data: { user } } = await authClient.auth.getUser();
        if (!user) return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });

        const supabase = createAdminClient();

        const { data: round, error: roundError } = await supabase
            .from("interview_rounds")
            .select("id, status, round_canceled, invitation:job_invitations!inner(company_id, employers!inner(user_id))")
            .eq("id", roundId)
            .single();

        if (roundError || !round) return NextResponse.json({ success: false, error: "Round not found" }, { status: 404 });

        const inv = (round as any).invitation;
        const emp = inv?.employers;
        if (emp?.user_id !== user.id) return NextResponse.json({ success: false, error: "Forbidden" }, { status: 403 });

        const editableStatuses = ["pending", "viewed", "accepted"];
        if (!editableStatuses.includes(round.status)) {
            return NextResponse.json({ success: false, error: "Cannot edit after round is confirmed" }, { status: 409 });
        }
        if (round.round_canceled) {
            return NextResponse.json({ success: false, error: "Cannot edit a cancelled round" }, { status: 409 });
        }

        const body = await request.json();
        const { timeSlots, interviewMode, meetingLink, interviewAddress, mapLink } = body;

        if (!timeSlots || !Array.isArray(timeSlots) || timeSlots.length === 0 || timeSlots.length > 3) {
            return NextResponse.json({ success: false, error: "Invalid time slots (must be 1-3)" }, { status: 400 });
        }
        for (const slot of timeSlots) {
            if (!slot.date || !slot.time) return NextResponse.json({ success: false, error: "Incomplete time slot data" }, { status: 400 });
        }
        if (!interviewMode) return NextResponse.json({ success: false, error: "Interview mode is required" }, { status: 400 });
        if (interviewMode === "physical" && !interviewAddress) {
            return NextResponse.json({ success: false, error: "Interview address is required for physical interviews" }, { status: 400 });
        }

        const { error: updateError } = await supabase
            .from("interview_rounds")
            .update({
                given_time_slots: timeSlots,
                interview_mode: interviewMode,
                meeting_link: interviewMode === "online" ? (meetingLink || null) : null,
                interview_address: interviewMode === "physical" ? (interviewAddress || null) : null,
                map_link: interviewMode === "physical" ? (mapLink || null) : null,
            })
            .eq("id", roundId);

        if (updateError) {
            console.error("edit-round error:", updateError);
            return NextResponse.json({ success: false, error: "Failed to update round" }, { status: 500 });
        }

        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("edit-round error:", error);
        return NextResponse.json({ success: false, error: "Internal server error" }, { status: 500 });
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";
import { logBusiness, logError } from "@/lib/logger";

// POST /api/employer/interview-rounds/[roundId]/feedback
// Add interview feedback and outcome for a specific round
export async function POST(
    request: Request,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const authClient = await createClient();
        const { roundId } = await params;
        const body = await request.json();
        const { outcome, outcome_notes } = body;

        // Validate outcome
        const validOutcomes = ['advance', 'reject', 'offer', 'no_decision'];
        if (!outcome || !validOutcomes.includes(outcome)) {
            return NextResponse.json(
                { success: false, error: "Invalid outcome. Must be one of: advance, reject, offer, no_decision" },
                { status: 400 }
            );
        }

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();
        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Get employer record
        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id, user_id')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        // Get the interview round and verify it belongs to this company
        const { data: round, error: roundError } = await supabase
            .from('interview_rounds')
            .select(`
                id,
                invitation_id,
                round_number,
                status,
                outcome,
                invitation:job_invitations!inner(
                    id,
                    company_id,
                    candidate_id,
                    pipeline_status
                )
            `)
            .eq('id', roundId)
            .single();

        if (roundError || !round) {
            return NextResponse.json(
                { success: false, error: "Interview round not found" },
                { status: 404 }
            );
        }

        // Type assertion for nested invitation
        const invitation = round.invitation as any;

        // Verify the round belongs to this company
        if (invitation.company_id !== employer.company_id) {
            return NextResponse.json(
                { success: false, error: "Unauthorized access to this interview round" },
                { status: 403 }
            );
        }

        // Check if round is in a state that allows feedback
        if (round.status !== 'confirmed' && round.status !== 'completed') {
            return NextResponse.json(
                { success: false, error: "Can only add feedback to confirmed or completed interviews" },
                { status: 400 }
            );
        }

        // Check if feedback already exists
        if (round.outcome && round.outcome !== 'no_decision') {
            return NextResponse.json(
                { success: false, error: "Feedback has already been provided for this round" },
                { status: 400 }
            );
        }

        // Update the round with outcome and feedback
        const { error: updateError } = await supabase
            .from('interview_rounds')
            .update({
                outcome: outcome,
                outcome_notes: outcome_notes || null,
                outcome_at: new Date().toISOString(),
                outcome_by: employer.user_id,
                status: outcome === 'advance' ? 'completed' : round.status
            })
            .eq('id', roundId);

        if (updateError) {
            console.error('Error updating interview round:', updateError);
            return NextResponse.json(
                { success: false, error: "Failed to save feedback" },
                { status: 500 }
            );
        }

        await logBusiness(
            "interview_feedback_added",
