export async function POST(
    request: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const authClient = await createClient();
        const { confirmed_time, meeting_link, interview_address, map_link } = await request.json();

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();

        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Get employer record
        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        const { id } = await params;

        // Verify the invitation belongs to this company and is accepted
        const { data: invitation, error: invitationError } = await supabase
            .from('job_invitations')
            .select('id, status, interview_mode, selected_time_slot, interview_confirmed')
            .eq('id', id)
            .eq('company_id', employer.company_id)
            .eq('status', 'accepted')
            .single();

        if (invitationError || !invitation) {
            return NextResponse.json(
                { success: false, error: "Accepted invitation not found" },
                { status: 404 }
            );
        }

        // Check if already confirmed
        if (invitation.interview_confirmed) {
            return NextResponse.json(
                { success: false, error: "Interview already confirmed" },
                { status: 400 }
            );
        }

        // Validate based on interview mode
        if (invitation.interview_mode === 'online') {
            if (!meeting_link || meeting_link.trim() === '') {
                return NextResponse.json(
                    { success: false, error: "Meeting link is required for online interviews" },
                    { status: 400 }
                );
            }
        } else if (invitation.interview_mode === 'physical') {
            if (!interview_address || interview_address.trim() === '') {
                return NextResponse.json(
                    { success: false, error: "Interview address is required for physical interviews" },
                    { status: 400 }
                );
            }
        }

        // Check if it's an alternative date
        const selectedSlot = invitation.selected_time_slot as any;
        if (selectedSlot?.is_alternative && (!confirmed_time || confirmed_time.trim() === '')) {
            return NextResponse.json(
                { success: false, error: "Time slot is required for alternative dates" },
                { status: 400 }
            );
        }

        // Update invitation with confirmation details
        const updateData: any = {
            interview_confirmed: true,
            confirmed_at: new Date().toISOString()
        };

        if (selectedSlot?.is_alternative && confirmed_time) {
            updateData.confirmed_time = confirmed_time;
        }

        if (invitation.interview_mode === 'online') {
            updateData.meeting_link = meeting_link;
        } else if (invitation.interview_mode === 'physical') {
            updateData.interview_address = interview_address;
            if (map_link && map_link.trim() !== '') {
                updateData.map_link = map_link;
            }
        }

        const { error: updateError } = await supabase
            .from('job_invitations')
            .update(updateData)
            .eq('id', id);

        if (updateError) {
            console.error('Error confirming interview:', updateError);
            return NextResponse.json(
                { success: false, error: "Failed to confirm interview" },
                { status: 500 }
            );
        }

        // Send confirmation email to candidate (async - non-blocking)
        const { data: fullInvitation } = await supabase
            .from('job_invitations')
            .select(`
                id,
                job_designation,
                interview_mode,
                selected_time_slot,
                confirmed_time,
                meeting_link,
                interview_address,
                candidate:candidates(first_name, email),
                company:companies(company_name)
            `)
            .eq('id', id)
            .single();

        if (fullInvitation) {
            const candidate = fullInvitation.candidate as any;
            const company = fullInvitation.company as any;
            const timeSlot = fullInvitation.selected_time_slot as any;

            const finalTime = (timeSlot?.is_alternative && confirmed_time)
                ? confirmed_time
                : timeSlot?.time || '';

            const locationInfo = fullInvitation.interview_mode === 'online'
                ? meeting_link
                : interview_address;

            getUserTimezoneByEmail(candidate.email).then(recipientTz =>
                sendInterviewConfirmedEmail(
                    candidate.email,
                    candidate.first_name,
                    company.company_name,
                    fullInvitation.job_designation,
                    timeSlot?.date || '',
                    finalTime,
                    fullInvitation.interview_mode,
                    locationInfo,
                    id,
                    recipientTz
                )
            ).catch(err => console.error('Email send error:', err));
        }

        await logBusiness("interview_confirmed", user.id, "employer", "job_invitation", id, { interview_mode: invitation.interview_mode });
        return NextResponse.json({
            success: true,
            message: "Interview confirmed successfully"
        });

    } catch (error) {
        console.error('API error:', error);
        await logError({ source: "api/employer/invitations/confirm:POST", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { success: false, error: "Internal server error" },
            { status: 500 }
        );
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";

// PATCH /api/employer/invitations/[id]/edit
// Allows employer to edit time slots / mode before candidate accepts
export async function PATCH(
    request: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const authClient = await createClient();
        const { id: invitationId } = await params;

        const { data: { user } } = await authClient.auth.getUser();
        if (!user) {
            return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
        }

        const supabase = createAdminClient();

        // Fetch invitation and verify ownership
        const { data: invitation, error: invError } = await supabase
            .from("job_invitations")
            .select("id, status, interview_confirmed, invitation_canceled, employer_id, employers!inner(user_id)")
            .eq("id", invitationId)
            .single();

        if (invError || !invitation) {
            return NextResponse.json({ success: false, error: "Invitation not found" }, { status: 404 });
        }

        const emp = (invitation as any).employers;
        if (emp?.user_id !== user.id) {
            return NextResponse.json({ success: false, error: "Forbidden" }, { status: 403 });
        }

        // Only editable before candidate accepts (pending or viewed)
        const editableStatuses = ["pending", "viewed"];
        if (!editableStatuses.includes(invitation.status)) {
            return NextResponse.json(
                { success: false, error: "Cannot edit after candidate has responded" },
                { status: 409 }
            );
        }

        if (invitation.invitation_canceled) {
            return NextResponse.json({ success: false, error: "Cannot edit a cancelled invitation" }, { status: 409 });
        }

        const body = await request.json();
        const { timeSlots, interviewMode, meetingLink, interviewAddress, mapLink } = body;

        if (!timeSlots || !Array.isArray(timeSlots) || timeSlots.length === 0 || timeSlots.length > 3) {
            return NextResponse.json({ success: false, error: "Invalid time slots (must be 1-3)" }, { status: 400 });
        }

        for (const slot of timeSlots) {
            if (!slot.date || !slot.time) {
                return NextResponse.json({ success: false, error: "Incomplete time slot data" }, { status: 400 });
            }
        }

        if (!interviewMode) {
            return NextResponse.json({ success: false, error: "Interview mode is required" }, { status: 400 });
        }

        if (interviewMode === "physical" && !interviewAddress) {
            return NextResponse.json({ success: false, error: "Interview address is required for physical interviews" }, { status: 400 });
        }

        const { error: updateError } = await supabase
            .from("job_invitations")
            .update({
                given_time_slots: timeSlots,
                interview_mode: interviewMode,
                meeting_link: interviewMode === "online" ? (meetingLink || null) : null,
                interview_address: interviewMode === "physical" ? (interviewAddress || null) : null,
                map_link: interviewMode === "physical" ? (mapLink || null) : null,
            })
            .eq("id", invitationId);

        if (updateError) {
            console.error("Edit invitation error:", updateError);
            return NextResponse.json({ success: false, error: "Failed to update invitation" }, { status: 500 });
        }

        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("edit invitation error:", error);
        return NextResponse.json({ success: false, error: "Internal server error" }, { status: 500 });
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextResponse } from "next/server";

// POST /api/employer/invitations/[id]/seed-round
// Creates round 1 for invitations that were confirmed before auto-creation was in place.
export async function POST(
    request: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const authClient = await createClient();
        const { id: invitationId } = await params;

        const { data: { user } } = await authClient.auth.getUser();
        if (!user) {
            return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
        }

        const supabase = createAdminClient();

        // Verify employer owns this invitation
        const { data: invitation, error: invError } = await supabase
            .from("job_invitations")
            .select(`
                id, company_id, interview_confirmed, mis_rescheduled,
                selected_time_slot, interview_mode, confirmed_time,
                meeting_link, interview_address, map_link, confirmed_at,
                mis_reschedule_data,
                employer:employers!inner(user_id)
            `)
            .eq("id", invitationId)
            .single();

        if (invError || !invitation) {
            return NextResponse.json({ success: false, error: "Invitation not found" }, { status: 404 });
        }

        const emp = (invitation as any).employer;
        if (emp?.user_id !== user.id) {
            return NextResponse.json({ success: false, error: "Forbidden" }, { status: 403 });
        }

        // Check round 1 doesn't already exist
        const { data: existing } = await supabase
            .from("interview_rounds")
            .select("id")
            .eq("invitation_id", invitationId)
            .eq("round_number", 1)
            .maybeSingle();

        if (existing) {
            return NextResponse.json({ success: false, error: "Round 1 already exists" }, { status: 409 });
        }

        // Build round data from the invitation's confirmation details
        const reschedule = (invitation as any).mis_reschedule_data;
        const isRescheduled = (invitation as any).mis_rescheduled && reschedule;

        const roundData: Record<string, unknown> = {
            invitation_id: invitationId,
            round_number: 1,
            round_label: "Initial Interview",
            status: isRescheduled ? "confirmed" : "confirmed",
            given_time_slots: isRescheduled
                ? [{ date: reschedule.date, time: reschedule.time, order: 1 }]
                : (invitation as any).selected_time_slot
                    ? [(invitation as any).selected_time_slot]
                    : [],
            interview_mode: isRescheduled ? reschedule.interview_mode : (invitation as any).interview_mode,
            interview_confirmed: true,
            confirmed_time: isRescheduled ? reschedule.time : (invitation as any).confirmed_time,
            meeting_link: isRescheduled ? (reschedule.meeting_link ?? null) : (invitation as any).meeting_link,
            interview_address: isRescheduled ? (reschedule.interview_address ?? null) : (invitation as any).interview_address,
            map_link: isRescheduled ? (reschedule.map_link ?? null) : (invitation as any).map_link,
            confirmed_at: (invitation as any).confirmed_at ?? new Date().toISOString(),
            mis_rescheduled: isRescheduled ? true : false,
            mis_reschedule_data: isRescheduled ? reschedule : null,
        };

        const { data: newRound, error: createError } = await supabase
            .from("interview_rounds")
            .insert(roundData)
            .select("id, round_number")
            .single();

        if (createError || !newRound) {
            console.error("seed-round insert error:", createError);
            return NextResponse.json({ success: false, error: "Failed to create round" }, { status: 500 });
        }

        // Ensure invitation current_round_number is 1
        await supabase
            .from("job_invitations")
            .update({ current_round_number: 1 })
            .eq("id", invitationId)
            .eq("current_round_number", 0);

        return NextResponse.json({ success: true, data: newRound });
    } catch (error) {
        console.error("seed-round error:", error);
        return NextResponse.json({ success: false, error: "Internal server error" }, { status: 500 });
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
