// GET /api/employer/invitations - Fetch all invitations for the company
export async function GET(request: Request) {
    try {
        const authClient = await createClient();

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();

        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Get employer record
        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        // Fetch all invitations for this company
        const { data: invitations, error: invitationsError } = await supabase
            .from('job_invitations')
            .select(`
                id,
                industry,
                job_designation,
                message,
                given_time_slots,
                alternative_dates,
                selected_time_slot,
                interview_mode,
                status,
                invitation_canceled,
                sent_at,
                viewed_at,
                responded_at,
                interview_confirmed,
                confirmed_time,
                meeting_link,
                interview_address,
                map_link,
                confirmed_at,
                canceled_by,
                cancellation_reason,
                canceled_at,
                mis_rescheduled,
                mis_rescheduled_at,
                mis_reschedule_data,
                pipeline_status,
                current_round_number,
                job_offers(id, status),
                interview_rounds(round_number, round_label, status, outcome, mis_rescheduled, round_canceled, given_time_slots, selected_time_slot, interview_mode, meeting_link, interview_address, map_link),
                candidate:candidates(id, first_name, last_name, email, phone, current_position, profile_image_url),
                employer:employers(id, first_name, last_name)
            `)
            .eq('company_id', employer.company_id)
            .order('sent_at', { ascending: false });

        if (invitationsError) {
            console.error('Error fetching invitations:', invitationsError);
            return NextResponse.json(
                { success: false, error: "Failed to fetch invitations" },
                { status: 500 }
            );
        }

        return NextResponse.json({
            success: true,
            data: invitations || []
        });

    } catch (error) {
        console.error('API error:', error);
        await logError({ source: "api/employer/invitations:GET", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { success: false, error: "Internal server error" },
            { status: 500 }
        );
    }
}

export async function POST(request: Request) {
    try {
        const authClient = await createClient();

        // Get the current user
        const { data: { user } } = await authClient.auth.getUser();

        if (!user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        const supabase = createAdminClient();

        // Parse request body
        const body = await request.json();
        const { candidateId, industry, jobDesignation, message, timeSlots, interviewMode, interviewAddress, mapLink } = body;

        if (!candidateId || !industry || !jobDesignation || !interviewMode) {
            return NextResponse.json(
                { success: false, error: "Missing required fields" },
                { status: 400 }
            );
        }

        if (interviewMode === 'physical' && !interviewAddress) {
            return NextResponse.json(
                { success: false, error: "Interview address is required for physical interviews" },
                { status: 400 }
            );
        }

        if (!timeSlots || !Array.isArray(timeSlots) || timeSlots.length === 0 || timeSlots.length > 3) {
            return NextResponse.json(
                { success: false, error: "Invalid time slots (must be 1-3)" },
                { status: 400 }
            );
        }

        // Validate time slots
        for (const slot of timeSlots) {
            if (!slot.date || !slot.time || !slot.order) {
                return NextResponse.json(
                    { success: false, error: "Incomplete time slot data" },
                    { status: 400 }
                );
            }
        }

        // Get employer record
        const { data: employer, error: employerError } = await supabase
            .from('employers')
            .select('id, company_id')
            .eq('user_id', user.id)
            .single();

        if (employerError || !employer) {
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        // Verify candidate exists and is approved
        const { data: candidate, error: candidateError } = await supabase
            .from('candidates')
            .select('id, approval_status')
            .eq('id', candidateId)
            .eq('approval_status', 'approved')
            .single();

        if (candidateError || !candidate) {
            return NextResponse.json(
                { success: false, error: "Candidate not found or not approved" },
                { status: 404 }
            );
        }

        // Block if this candidate has been hired by ANY company
        const { data: hiredInvitation } = await supabase
            .from('job_invitations')
            .select('id, company_id')
            .eq('candidate_id', candidateId)
            .eq('pipeline_status', 'hired')
            .neq('invitation_canceled', true)
            .maybeSingle();

        if (hiredInvitation) {
            const isSameCompany = hiredInvitation.company_id === employer.company_id;
            return NextResponse.json(
                {
                    success: false,
                    error: isSameCompany
                        ? "You have already hired this candidate."
                        : "This candidate has already accepted a job offer from another company."
                },
                { status: 409 }
            );
        }

        // Block if this company already has an active or in-progress invitation with this candidate
        const { data: existingInvitation } = await supabase
            .from('job_invitations')
            .select('id, status, pipeline_status, interview_confirmed, invitation_canceled')
            .eq('candidate_id', candidateId)
            .eq('company_id', employer.company_id)
            .neq('invitation_canceled', true)
            .not('status', 'in', '(declined,expired)')
            .not('pipeline_status', 'in', '(rejected,withdrawn,expired)')
            .maybeSingle();

        if (existingInvitation) {
            const isInterviewOngoing = existingInvitation.interview_confirmed ||
                ['offered', 'active'].includes(existingInvitation.pipeline_status ?? '');
            return NextResponse.json(
                {
                    success: false,
                    error: isInterviewOngoing
                        ? "An interview or offer process with this candidate is already in progress."
                        : "You have already sent an active invitation to this candidate. Wait for their response or cancel the existing invitation first."
                },
                { status: 409 }
            );
        }

        // Create invitation record (no job_id needed)
        const sentNow = new Date().toISOString();
        const { data: invitation, error: invitationError } = await supabase
            .from('job_invitations')
            .insert({
                candidate_id: candidateId,
                employer_id: employer.id,
                company_id: employer.company_id,
                industry: industry,
                job_designation: jobDesignation,
                message: message || null,
                status: 'pending',
                given_time_slots: timeSlots,  // Store as JSON array
                alternative_dates: null,  // Removed alternative dates logic
                employer_last_seen_at: sentNow,
                interview_mode: interviewMode,
                interview_address: interviewAddress || null,
                map_link: mapLink || null,
            })
            .select()
            .single();

        if (invitationError) {
            console.error('Error creating invitation:', invitationError);
            return NextResponse.json(
                { success: false, error: "Failed to send invitation" },
                { status: 500 }
            );
        }

        // Send email notification to candidate (async - non-blocking)
        const { data: candidateData } = await supabase
            .from('candidates')
            .select('first_name, email')
            .eq('id', candidateId)
            .single();

        const { data: companyData } = await supabase
            .from('companies')
            .select('company_name')
            .eq('id', employer.company_id)
            .single();

        if (candidateData && companyData) {
            const recipientTz = await getUserTimezoneByEmail(candidateData.email);
            sendInterviewInvitationEmail(
                candidateData.email,
                candidateData.first_name,
                companyData.company_name,
                jobDesignation,
                timeSlots,
                invitation.id,
                recipientTz
            ).catch(err => console.error('Email send error:', err));
        }

        await logBusiness("invitation_sent", user.id, "employer", "job_invitation", invitation.id, { candidateId, industry, jobDesignation });
        return NextResponse.json({
            success: true,
            message: "Invitation sent successfully",
            data: {
                ...invitation,
                time_slots_count: timeSlots.length
            }
        });

    } catch (error) {
        console.error('API error:', error);
        await logError({ source: "api/employer/invitations:POST", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { success: false, error: "Internal server error" },
            { status: 500 }
        );
    }
}

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextRequest, NextResponse } from "next/server";
import { logBusiness, logError } from "@/lib/logger";
import { notifyMisPaymentProofSubmitted } from "@/lib/payments";

// POST /api/employer/payments/[id]/upload-proof
// Body: multipart/form-data — file, bank_transfer_reference (optional)
export async function POST(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const supabase = await createClient();
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const admin = createAdminClient();

        const { data: employer } = await admin
            .from("employers")
            .select("id, company_id")
            .eq("user_id", user.id)
            .single();

        if (!employer) return NextResponse.json({ error: "Employer profile not found" }, { status: 404 });

        const { id } = await params;

        // Verify payment request belongs to employer's company and is actionable
        const { data: paymentRequest } = await admin
            .from("payment_requests")
            .select("id, status, amount, currency, company_id, companies(company_name)")
            .eq("id", id)
            .eq("company_id", employer.company_id)
            .single();

        if (!paymentRequest) return NextResponse.json({ error: "Payment request not found" }, { status: 404 });

        if (!["pending_payment", "rejected"].includes(paymentRequest.status as string)) {
            return NextResponse.json({ error: "Cannot upload proof for a payment in this status" }, { status: 400 });
        }

        const formData = await request.formData();
        const file = formData.get("file") as File | null;
        const bankTransferReference = (formData.get("bank_transfer_reference") as string | null) ?? null;

        if (!file) return NextResponse.json({ error: "No file provided" }, { status: 400 });

        const allowedTypes = ["application/pdf", "image/jpeg", "image/jpg", "image/png", "image/webp"];
        if (!allowedTypes.includes(file.type)) {
            return NextResponse.json({ error: "Only PDF, JPG, PNG, or WEBP files are allowed" }, { status: 400 });
        }
        if (file.size > 10 * 1024 * 1024) {
            return NextResponse.json({ error: "File size must be less than 10MB" }, { status: 400 });
        }

        // Upload to payment-proofs bucket via existing upload API
        const uploadFormData = new FormData();
        uploadFormData.append("file", file);
        uploadFormData.append("bucket", "payment-proofs");
        uploadFormData.append("folder", `${employer.company_id}/${id}`);

        // Call internal upload API
        const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";
        const uploadRes = await fetch(`${baseUrl}/api/upload`, {
            method: "POST",
            body: uploadFormData,
            headers: { Cookie: request.headers.get("Cookie") ?? "" },
        });

        if (!uploadRes.ok) {
            const errBody = await uploadRes.json().catch(() => ({}));
            return NextResponse.json({ error: errBody.error ?? "File upload failed" }, { status: 500 });
        }

        const { url: fileUrl, fileName: filePath } = await uploadRes.json();

        const now = new Date().toISOString();

        // Create proof record
        const { data: proof, error: proofErr } = await admin
            .from("payment_proofs")
            .insert({
                payment_request_id: id,
                uploaded_by_employer_id: employer.id,
                file_url: fileUrl,
                file_path: filePath,
                file_name: file.name,
                file_type: file.type,
                uploaded_at: now,
                status: "pending_review",
            })
            .select()
            .single();

        if (proofErr || !proof) throw proofErr ?? new Error("Failed to create proof record");

        // Update payment request status to under_review and optionally store bank ref
        await admin
            .from("payment_requests")
            .update({
                status: "under_review",
                updated_at: now,
                ...(bankTransferReference ? { bank_transfer_reference: bankTransferReference } : {}),
            })
            .eq("id", id);

        // Notify MIS
        const companyData = paymentRequest.companies as any;
        await notifyMisPaymentProofSubmitted({
            payment_request_id: id,
            company_name: companyData?.company_name ?? "Unknown Company",
            amount: Number(paymentRequest.amount),
            currency: paymentRequest.currency as string,
        });

        await logBusiness("payment_proof_uploaded", user.id, "employer", "payment_request", id, { proof_id: proof.id });

        return NextResponse.json({ success: true, data: proof }, { status: 201 });
    } catch (error) {
        await logError({ source: "api/employer/payments/[id]/upload-proof:POST", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

