"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { NextRequest, NextResponse } from "next/server";
import { logError } from "@/lib/logger";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_FILE_TYPES = ["image/jpeg", "image/jpg", "image/png", "image/gif", "image/webp"];

export async function POST(request: NextRequest) {
    try {
        // Use regular client for authentication
        const supabase = await createClient();

        // Check authentication
        const { data: { user }, error: authError } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json(
                { success: false, error: "Unauthorized" },
                { status: 401 }
            );
        }

        // Get the form data
        const formData = await request.formData();
        const file = formData.get("file") as File;

        if (!file) {
            return NextResponse.json(
                { success: false, error: "No file provided" },
                { status: 400 }
            );
        }

        // Validate file type
        if (!ALLOWED_FILE_TYPES.includes(file.type)) {
            return NextResponse.json(
                { success: false, error: "Invalid file type. Only images are allowed." },
                { status: 400 }
            );
        }

        // Validate file size
        if (file.size > MAX_FILE_SIZE) {
            return NextResponse.json(
                { success: false, error: "File size exceeds 5MB limit" },
                { status: 400 }
            );
        }

        // Use admin client for database and storage operations
        const adminClient = createAdminClient();

        // Get employer and company info
        const { data: employer, error: employerError } = await adminClient
            .from("employers")
            .select("company_id, companies!inner(logo_url)")
            .eq("user_id", user.id)
            .single();

        if (employerError || !employer) {
            console.error("Employer fetch error:", employerError);
            return NextResponse.json(
                { success: false, error: "Employer profile not found" },
                { status: 404 }
            );
        }

        const company = (employer as any).companies;
        const oldLogoUrl = company?.logo_url;

        // Create unique filename
        const fileExt = file.name.split(".").pop();
        const fileName = `${employer.company_id}-${Date.now()}.${fileExt}`;
        const filePath = `${fileName}`; // Just the filename

        // Convert file to buffer
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Delete old logo if exists (using admin client)
        if (oldLogoUrl) {
            try {
                // Extract filename from URL
                const urlParts = oldLogoUrl.split('/');
                const oldFileName = urlParts[urlParts.length - 1];

                console.log("Attempting to delete old logo:", oldFileName);
                const { error: deleteError } = await adminClient.storage
                    .from("company-logos")
                    .remove([oldFileName]);

                if (deleteError) {
                    console.error("Error deleting old logo:", deleteError);
                }
            } catch (error) {
                console.error("Error in delete operation:", error);
                // Continue with upload even if deletion fails
            }
        }

        // Ensure the company-logos bucket exists before uploading
        const bucketName = "company-logos";
        const { data: buckets, error: listError } = await adminClient.storage.listBuckets();
        if (listError) {
            console.error("Error listing storage buckets:", listError);
        }

        const bucketExists = buckets?.find((b) => b.name === bucketName);
        if (!bucketExists) {
            const { error: createError } = await adminClient.storage.createBucket(bucketName, {
                public: true,
                fileSizeLimit: MAX_FILE_SIZE,
                allowedMimeTypes: ALLOWED_FILE_TYPES,
            });

            if (createError) {
                console.error(`Failed to create bucket '${bucketName}':`, createError);
                return NextResponse.json(
                    { success: false, error: `Failed to create storage bucket '${bucketName}'` },
                    { status: 500 }
                );
            }
            console.log(`Created storage bucket: ${bucketName}`);
        }

        // Upload to Supabase Storage using admin client (bypasses RLS)
        console.log("Uploading new logo:", filePath);
        const { data: uploadData, error: uploadError } = await adminClient.storage
            .from(bucketName)
            .upload(filePath, buffer, {
                contentType: file.type,
                upsert: true,
            });

        if (uploadError) {
            console.error("Upload error:", uploadError);
            return NextResponse.json(
                { success: false, error: `Failed to upload logo: ${uploadError.message}` },
                { status: 500 }
            );
        }

        console.log("Upload successful:", uploadData);

        // Get public URL
        const { data: urlData } = adminClient.storage
            .from("company-logos")
            .getPublicUrl(filePath);

        if (!urlData?.publicUrl) {
            return NextResponse.json(
                { success: false, error: "Failed to get logo URL" },
                { status: 500 }
            );
        }

        console.log("Public URL generated:", urlData.publicUrl);

        return NextResponse.json({
            success: true,
            data: {
                url: urlData.publicUrl,
                path: filePath,
            },
        });
    } catch (error) {
        console.error("Error in company logo upload:", error);
        await logError({ source: "api/employer/upload-company-logo:POST", errorType: "UploadError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { success: false, error: "An unexpected error occurred" },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { logError } from "@/lib/logger";

export async function GET(request: NextRequest) {
    try {
        const supabase = await createClient();
        const { data: { user }, error: authError } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const adminClient = createAdminClient();
        const { data: misUser, error: misUserError } = await adminClient
            .from("mis_user")
            .select("user_id")
            .eq("user_id", user.id)
            .single();

        if (misUserError || !misUser) {
            return NextResponse.json({ error: "Forbidden" }, { status: 403 });
        }

        // Core counts
        const [
            candidatesResult,
            employersResult,
            jobsResult,
            interviewsResult,
            pendingCandidatesResult,
            pendingEmployersResult,
            activeJobsResult,
            confirmedInterviewsResult,
            approvedCandidatesResult,
            rejectedCandidatesResult,
            approvedEmployersResult,
            rejectedEmployersResult,
        ] = await Promise.all([
            adminClient.from("candidates").select("*", { count: "exact", head: true }),
            adminClient.from("companies").select("*", { count: "exact", head: true }),
            adminClient.from("jobs").select("*", { count: "exact", head: true }),
            adminClient.from("job_invitations").select("*", { count: "exact", head: true }),
            adminClient.from("candidates").select("*", { count: "exact", head: true }).eq("approval_status", "pending"),
            adminClient.from("companies").select("*", { count: "exact", head: true }).eq("approval_status", "pending"),
            adminClient.from("jobs").select("*", { count: "exact", head: true }).eq("status", "published"),
            adminClient.from("job_invitations").select("*", { count: "exact", head: true }).eq("interview_confirmed", true),
            adminClient.from("candidates").select("*", { count: "exact", head: true }).eq("approval_status", "approved"),
            adminClient.from("candidates").select("*", { count: "exact", head: true }).eq("approval_status", "rejected"),
            adminClient.from("companies").select("*", { count: "exact", head: true }).eq("approval_status", "approved"),
            adminClient.from("companies").select("*", { count: "exact", head: true }).eq("approval_status", "rejected"),
        ]);

        // Recent activity
        const { data: recentActivity } = await adminClient
            .from("event_logs")
            .select("*")
            .order("created_at", { ascending: false })
            .limit(20);

        // Last 30 days approval data
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

        const [approvedCandidates, approvedEmployers] = await Promise.all([
            adminClient
                .from("candidates")
                .select("approved_at")
                .eq("approval_status", "approved")
                .gte("approved_at", thirtyDaysAgo.toISOString()),
            adminClient
                .from("companies")
                .select("approved_at")
                .eq("approval_status", "approved")
                .gte("approved_at", thirtyDaysAgo.toISOString()),
        ]);

        // Build daily approval trend for last 30 days
        const dayMap: Record<string, { date: string; candidates: number; employers: number }> = {};
        for (let i = 29; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const key = d.toISOString().slice(0, 10);
            dayMap[key] = { date: key, candidates: 0, employers: 0 };
        }
        for (const c of approvedCandidates.data || []) {
            if (c.approved_at) {
                const key = c.approved_at.slice(0, 10);
                if (dayMap[key]) dayMap[key].candidates++;
            }
        }
        for (const e of approvedEmployers.data || []) {
            if (e.approved_at) {
                const key = e.approved_at.slice(0, 10);
                if (dayMap[key]) dayMap[key].employers++;
            }
        }

        // Activity category breakdown (last 30 days)
        const { data: activityLogs } = await adminClient
            .from("event_logs")
            .select("category, action")
            .gte("created_at", thirtyDaysAgo.toISOString());

        const categoryMap: Record<string, number> = {};
        for (const log of activityLogs || []) {
            const cat = log.category || "other";
            categoryMap[cat] = (categoryMap[cat] || 0) + 1;
        }
        const activityByCategory = Object.entries(categoryMap).map(([name, value]) => ({ name, value }));

        return NextResponse.json({
            success: true,
            stats: {
                totalCandidates: candidatesResult.count || 0,
                totalEmployers: employersResult.count || 0,
                totalJobs: jobsResult.count || 0,
                totalInterviews: interviewsResult.count || 0,
                pendingCandidates: pendingCandidatesResult.count || 0,
                pendingEmployers: pendingEmployersResult.count || 0,
                activeJobs: activeJobsResult.count || 0,
                confirmedInterviews: confirmedInterviewsResult.count || 0,
                approvedCandidates: approvedCandidatesResult.count || 0,
                rejectedCandidates: rejectedCandidatesResult.count || 0,
                approvedEmployers: approvedEmployersResult.count || 0,
                rejectedEmployers: rejectedEmployersResult.count || 0,
                recentApprovals: {
                    candidates: approvedCandidates.data?.length || 0,
                    employers: approvedEmployers.data?.length || 0,
                },
            },
            recentActivity: recentActivity || [],
            approvalTrend: Object.values(dayMap),
            activityByCategory,
        });
    } catch (error) {
        console.error("Error in GET /api/mis/analytics/stats:", error);
        await logError({
            source: "api/mis/analytics/stats:GET",
            errorType: "APIError",
            message: error instanceof Error ? error.message : String(error),
        });
        return NextResponse.json({ error: "Failed to fetch stats" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { logError } from "@/lib/logger";

export async function GET(request: NextRequest) {
    try {
        const supabase = await createClient();
        const { data: { user }, error: authError } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const adminClient = createAdminClient();
        const { data: misUser, error: misUserError } = await adminClient
            .from("mis_user")
            .select("user_id")
            .eq("user_id", user.id)
            .single();

        if (misUserError || !misUser) {
            return NextResponse.json({ error: "Forbidden" }, { status: 403 });
        }

        const { searchParams } = new URL(request.url);
        const resolved = searchParams.get("resolved");
        const errorType = searchParams.get("errorType");
        const dateFrom = searchParams.get("dateFrom");
        const dateTo = searchParams.get("dateTo");
        const limit = parseInt(searchParams.get("limit") || "50");
        const offset = parseInt(searchParams.get("offset") || "0");

        let query = adminClient
            .from("error_logs")
            .select("*", { count: "exact" })
            .order("created_at", { ascending: false })
            .range(offset, offset + limit - 1);

        if (resolved !== null) query = query.eq("resolved", resolved === "true");
        if (errorType) query = query.eq("error_type", errorType);
        if (dateFrom) query = query.gte("created_at", dateFrom);
        if (dateTo) query = query.lte("created_at", dateTo);

        const { data: errors, error: errorsError, count } = await query;

        if (errorsError) {
            console.error("Error fetching errors:", errorsError);
            return NextResponse.json({ error: "Failed to fetch errors" }, { status: 500 });
        }

        return NextResponse.json({
            success: true,
            errors: errors || [],
            total: count || 0,
            limit,
            offset,
        });
    } catch (error) {
        console.error("Error in GET /api/mis/audit/errors:", error);
        return NextResponse.json({ error: "Failed to fetch errors" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
    sendMISRoundRescheduleNotificationToCandidate,
    sendMISRoundRescheduleNotificationToEmployer
} from "@/lib/interview-emails";
import { logAudit, logError } from "@/lib/logger";
import { getUserTimezone, getUserTimezoneByEmail } from "@/lib/user-timezone";
import { formatInTimeZone } from "date-fns-tz";

export async function POST(
    request: NextRequest,
    { params }: { params: Promise<{ roundId: string }> }
) {
    try {
        const supabase = await createClient();
        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json(
                { error: "Unauthorized - Please log in" },
                { status: 401 }
            );
        }

        const adminClient = createAdminClient();
        const { data: userRecord, error: userError } = await adminClient
            .from("users")
            .select("role")
            .eq("id", user.id)
            .single();

        if (userError || !userRecord || userRecord.role !== "mis") {
            return NextResponse.json(
                { error: "Forbidden - MIS access required" },
                { status: 403 }
            );
        }

        const { roundId } = await params;
        const body = await request.json();

        const { date, time, interview_mode, meeting_link, interview_address, map_link, notes } = body;

        if (!date || !time || !interview_mode) {
            return NextResponse.json(
                { error: "Missing required fields: date, time, interview_mode" },
                { status: 400 }
            );
        }

        if (interview_mode === "online" && !meeting_link) {
            return NextResponse.json(
                { error: "Meeting link is required for online interviews" },
                { status: 400 }
            );
        }

        if (interview_mode === "physical" && !interview_address) {
            return NextResponse.json(
                { error: "Interview address is required for physical interviews" },
                { status: 400 }
            );
        }

        const misUserTz = await getUserTimezone(user.id);
        const todayInUserTz = formatInTimeZone(new Date(), misUserTz, "yyyy-MM-dd");
        if (date < todayInUserTz) {
            return NextResponse.json(
                { error: "Interview date must be in the future" },
                { status: 400 }
            );
        }

        const timeRegex = /^(0?[9]|1[0-2]|0?[1-4]):(00|30) (AM|PM)$/;
        if (!timeRegex.test(time)) {
            return NextResponse.json(
                { error: "Invalid time format. Use 30-minute intervals between 9:00 AM and 5:00 PM" },
                { status: 400 }
            );
        }

        // Fetch round to verify eligibility
        const { data: round, error: fetchError } = await adminClient
            .from("interview_rounds")
            .select("id, interview_confirmed, round_canceled, mis_rescheduled, invitation_id, round_label, round_number")
            .eq("id", roundId)
            .single();

        if (fetchError || !round) {
            return NextResponse.json(
                { error: "Interview round not found" },
                { status: 404 }
            );
        }

        if (!round.interview_confirmed) {
            return NextResponse.json(
                { error: "Only confirmed rounds can be rescheduled" },
                { status: 400 }
            );
        }

        if (!round.round_canceled) {
            return NextResponse.json(
                { error: "Only cancelled rounds can be rescheduled by MIS" },
                { status: 400 }
            );
        }

        if (round.mis_rescheduled) {
            return NextResponse.json(
                { error: "This round has already been rescheduled by MIS" },
                { status: 400 }
            );
        }

        const rescheduleData = {
            date,
            time,
            interview_mode,
            ...(interview_mode === "online" && { meeting_link }),
            ...(interview_mode === "physical" && {
                interview_address,
                ...(map_link && { map_link })
            }),
            ...(notes && { notes })
        };

        const { error: updateError } = await adminClient
            .from("interview_rounds")
            .update({
                mis_rescheduled: true,
                mis_rescheduled_at: new Date().toISOString(),
                mis_rescheduled_by: user.id,
                mis_reschedule_data: rescheduleData
            })
            .eq("id", roundId);

        if (updateError) {
            console.error("Error updating round:", updateError);
            return NextResponse.json(
                { error: "Failed to reschedule round" },
                { status: 500 }
            );
        }

        // Fetch invitation details for email notifications
        const { data: invitation } = await adminClient
            .from("job_invitations")
            .select(`
                id,
                job_designation,
                candidate:candidates!inner(id, first_name, last_name, email),
                employer:employers!inner(id, first_name, last_name, email),
                company:companies!inner(id, company_name)
            `)
            .eq("id", round.invitation_id)
            .single();

        // Delete stale reminders for the parent invitation
        await adminClient
            .from("interview_reminder_sent")
            .delete()
            .eq("job_invitation_id", round.invitation_id);

        if (invitation) {
            const candidateData = invitation.candidate as any;
            const employerData = invitation.employer as any;
            const companyData = invitation.company as any;
            const roundLabel = round.round_label || `Round ${round.round_number}`;
            const meetingLinkOrAddress = interview_mode === 'online' ? meeting_link : interview_address;

            const [candidateTz, employerTz] = await Promise.all([
                getUserTimezoneByEmail(candidateData.email),
                getUserTimezoneByEmail(employerData.email),
            ]);

            await sendMISRoundRescheduleNotificationToCandidate(
                candidateData.email,
                candidateData.first_name,
                companyData.company_name,
                invitation.job_designation,
                roundLabel,
                date,
                time,
                interview_mode,
                meetingLinkOrAddress || '',
                round.invitation_id,
                notes || '',
                candidateTz
            );

            await sendMISRoundRescheduleNotificationToEmployer(
                employerData.email,
                employerData.first_name,
                `${candidateData.first_name} ${candidateData.last_name}`,
                invitation.job_designation,
                roundLabel,
                date,
                time,
                interview_mode,
                meetingLinkOrAddress || '',
                round.invitation_id,
                notes || '',
                employerTz
            );
        }

        await logAudit("round_rescheduled_by_mis", user.id, "mis", "interview_round", roundId, { date, time, interview_mode });

        return NextResponse.json({
            success: true,
            message: "Interview round rescheduled successfully and notifications sent"
        });

    } catch (error) {
        console.error("Error rescheduling interview round:", error);
        await logError({ source: "api/mis/interview-rounds/reschedule:POST", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { error: "Failed to reschedule interview round" },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
    sendMISRescheduleNotificationToCandidate,
    sendMISRescheduleNotificationToEmployer
} from "@/lib/interview-emails";
import { logAudit, logError } from "@/lib/logger";
import { getUserTimezone, getUserTimezoneByEmail } from "@/lib/user-timezone";
import { formatInTimeZone } from "date-fns-tz";

export async function POST(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        // Authenticate user
        const supabase = await createClient();
        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json(
                { error: "Unauthorized - Please log in" },
                { status: 401 }
            );
        }

        // Verify user is MIS user
        const adminClient = createAdminClient();
        const { data: userRecord, error: userError } = await adminClient
            .from("users")
            .select("role")
            .eq("id", user.id)
            .single();

        if (userError || !userRecord || userRecord.role !== "mis") {
            return NextResponse.json(
                { error: "Forbidden - MIS access required" },
                { status: 403 }
            );
        }

        const { id } = await params;
        const body = await request.json();

        // Validate request body
        const { date, time, interview_mode, meeting_link, interview_address, map_link, notes } = body;

        if (!date || !time || !interview_mode) {
            return NextResponse.json(
                { error: "Missing required fields: date, time, interview_mode" },
                { status: 400 }
            );
        }

        // Validate interview mode specific requirements
        if (interview_mode === "online" && !meeting_link) {
            return NextResponse.json(
                { error: "Meeting link is required for online interviews" },
                { status: 400 }
            );
        }

        if (interview_mode === "physical" && !interview_address) {
            return NextResponse.json(
                { error: "Interview address is required for physical interviews" },
                { status: 400 }
            );
        }

        // Validate date is in the future. Compare calendar dates in the MIS
        // user's timezone so a user picking "today" locally is never rejected
        // because the UTC server has already rolled over to tomorrow (or vice versa).
        const misUserTz = await getUserTimezone(user.id);
        const todayInUserTz = formatInTimeZone(new Date(), misUserTz, "yyyy-MM-dd");
        if (date < todayInUserTz) {
            return NextResponse.json(
                { error: "Interview date must be in the future" },
                { status: 400 }
            );
        }

        // Validate time slot format (should be like "9:00 AM", "2:30 PM")
        const timeRegex = /^(0?[9]|1[0-2]|0?[1-4]):(00|30) (AM|PM)$/;
        if (!timeRegex.test(time)) {
            return NextResponse.json(
                { error: "Invalid time format. Use 30-minute intervals between 9:00 AM and 5:00 PM" },
                { status: 400 }
            );
        }

        // Fetch interview to verify eligibility
        const { data: interview, error: fetchError } = await adminClient
            .from("job_invitations")
            .select("id, interview_confirmed, invitation_canceled, mis_rescheduled")
            .eq("id", id)
            .single();

        if (fetchError || !interview) {
            return NextResponse.json(
                { error: "Interview not found" },
                { status: 404 }
            );
        }

        // Verify interview is eligible for reschedule
        if (!interview.invitation_canceled) {
            return NextResponse.json(
                { error: "Only cancelled interviews can be rescheduled by MIS" },
                { status: 400 }
            );
        }

        if (interview.mis_rescheduled) {
            return NextResponse.json(
                { error: "This interview has already been rescheduled by MIS" },
                { status: 400 }
            );
        }

        // Prepare reschedule data
        const rescheduleData = {
            date,
            time,
            interview_mode,
            ...(interview_mode === "online" && { meeting_link }),
            ...(interview_mode === "physical" && {
                interview_address,
                ...(map_link && { map_link })
            }),
            ...(notes && { notes })
        };

        // Update interview with MIS reschedule data
        const { data: updatedInterview, error: updateError } = await adminClient
            .from("job_invitations")
            .update({
                mis_rescheduled: true,
                mis_rescheduled_at: new Date().toISOString(),
                mis_rescheduled_by: user.id,
                mis_reschedule_data: rescheduleData
            })
            .eq("id", id)
            .select(`
                *,
                candidate:candidates!inner(
                    id,
                    user_id,
                    first_name,
                    last_name,
                    email
                ),
                employer:employers!inner(
                    id,
                    user_id,
                    first_name,
                    last_name,
                    email
                ),
                company:companies!inner(
                    id,
                    company_name
                )
            `)
            .single();

        if (updateError) {
            console.error("Error updating interview:", updateError);
            return NextResponse.json(
                { error: "Failed to reschedule interview" },
                { status: 500 }
            );
        }

        await adminClient.from("interview_reminder_sent").delete().eq("job_invitation_id", id);

        // Send email notifications to both candidate and employer
        const candidateData = updatedInterview.candidate as any;
        const employerData = updatedInterview.employer as any;
        const companyData = updatedInterview.company as any;
        const meetingLinkOrAddress = interview_mode === 'online' ? meeting_link : interview_address;

        const [candidateTz, employerTz] = await Promise.all([
            getUserTimezoneByEmail(candidateData.email),
            getUserTimezoneByEmail(employerData.email),
        ]);

        // Send to candidate
        await sendMISRescheduleNotificationToCandidate(
            candidateData.email,
            candidateData.first_name,
            companyData.company_name,
            updatedInterview.job_designation,
            date,
            time,
            interview_mode,
            meetingLinkOrAddress || '',
            id,
            notes || '',
            candidateTz
        );

        // Send to employer
        await sendMISRescheduleNotificationToEmployer(
            employerData.email,
            employerData.first_name,
            `${candidateData.first_name} ${candidateData.last_name}`,
            updatedInterview.job_designation,
            date,
            time,
            interview_mode,
            meetingLinkOrAddress || '',
            id,
            notes || '',
            employerTz
        );

        // In-app notifications (non-blocking)
        const notificationPayload = {
            invitation_id: id,
            date,
            time,
            interview_mode,
        };

        const inAppPromises: Promise<unknown>[] = [];

        if (candidateData?.user_id) {
            inAppPromises.push(
                Promise.resolve(
                    adminClient.rpc('notify_user', {
                        p_user_id: candidateData.user_id,
                        p_type: 'interview_rescheduled',
                        p_title: 'Interview Rescheduled',
                        p_body: `Your interview for ${updatedInterview.job_designation} at ${companyData.company_name} has been rescheduled by JobGenie.`,
                        p_data: notificationPayload,
                    })
                ).catch((err: unknown) => console.error('Candidate notification error:', err))
            );
        }

        if (employerData?.user_id) {
            inAppPromises.push(
                Promise.resolve(
                    adminClient.rpc('notify_user', {
                        p_user_id: employerData.user_id,
                        p_type: 'interview_rescheduled',
                        p_title: 'Interview Rescheduled',
                        p_body: `The interview with ${candidateData.first_name} ${candidateData.last_name} for ${updatedInterview.job_designation} has been rescheduled by JobGenie.`,
                        p_data: notificationPayload,
                    })
                ).catch((err: unknown) => console.error('Employer notification error:', err))
            );
        }

        await Promise.all(inAppPromises);

        await logAudit("interview_rescheduled_by_mis", user.id, "mis", "job_invitation", id, { date, time, interview_mode });
        return NextResponse.json({
            success: true,
            interview: updatedInterview,
            message: "Interview rescheduled successfully and notifications sent"
        });

    } catch (error) {
        console.error("Error rescheduling interview:", error);
        await logError({ source: "api/mis/interviews/reschedule:POST", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { error: "Failed to reschedule interview" },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { logError } from "@/lib/logger";
import { getUserTimezone } from "@/lib/user-timezone";
import { monthBoundsUTC } from "@/lib/date-utils";
import { formatInTimeZone } from "date-fns-tz";

export async function GET(request: NextRequest) {
    try {
        // Authenticate user
        const supabase = await createClient();
        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json(
                { error: "Unauthorized - Please log in" },
                { status: 401 }
            );
        }

        // Verify user is MIS user
        const adminClient = createAdminClient();
        const { data: userRecord, error: userError } = await adminClient
            .from("users")
            .select("role")
            .eq("id", user.id)
            .single();

        if (userError || !userRecord || userRecord.role !== "mis") {
            return NextResponse.json(
                { error: "Forbidden - MIS access required" },
                { status: 403 }
            );
        }

        // Compute month boundaries in the viewer's timezone (so "this month" matches
        // what the MIS user sees on their calendar, not the server's wall clock).
        const viewerTz = await getUserTimezone(user.id);
        const now = new Date();
        const viewerYearStr = formatInTimeZone(now, viewerTz, "yyyy");
        const viewerMonthStr = formatInTimeZone(now, viewerTz, "M");
        const viewerYear = parseInt(viewerYearStr, 10);
        const viewerMonthIndex = parseInt(viewerMonthStr, 10) - 1;
        const { start: firstDayOfMonth } = monthBoundsUTC(viewerYear, viewerMonthIndex, viewerTz);

        // Fetch all accepted invitations (interviews)
        const { data: allInterviews, error: allError } = await adminClient
            .from("job_invitations")
            .select("id, interview_confirmed, invitation_canceled, canceled_by, interview_mode, sent_at, viewed_at, responded_at, industry");

        if (allError) {
            console.error("Error fetching interview stats:", allError);
            return NextResponse.json(
                { error: "Failed to fetch statistics" },
                { status: 500 }
            );
        }

        const interviews = allInterviews || [];

        // Calculate statistics
        const totalInterviews = interviews.length;
        const confirmedInterviews = interviews.filter(i => i.interview_confirmed && !i.invitation_canceled).length;
        const pendingConfirmation = interviews.filter(i => !i.interview_confirmed && !i.invitation_canceled).length;
        const cancelledInterviews = interviews.filter(i => i.invitation_canceled).length;
        const cancelledByCandidate = interviews.filter(i => i.invitation_canceled && i.canceled_by === "candidate").length;
        const cancelledByEmployer = interviews.filter(i => i.invitation_canceled && i.canceled_by === "employer").length;

        // Interview mode distribution
        const onlineInterviews = interviews.filter(i => i.interview_mode === "online" && !i.invitation_canceled).length;
        const physicalInterviews = interviews.filter(i => i.interview_mode === "physical" && !i.invitation_canceled).length;

        // Current month statistics
        const monthlyInterviews = interviews.filter(i => new Date(i.sent_at) >= firstDayOfMonth).length;

        // Calculate average response time (from sent to responded)
        const respondedInterviews = interviews.filter(i => i.responded_at);
        let avgResponseTime = 0;
        if (respondedInterviews.length > 0) {
            const totalResponseTime = respondedInterviews.reduce((acc, i) => {
                const sent = new Date(i.sent_at).getTime();
                const responded = new Date(i.responded_at).getTime();
                return acc + (responded - sent);
            }, 0);
            avgResponseTime = Math.round(totalResponseTime / respondedInterviews.length / (1000 * 60 * 60)); // Convert to hours
        }

        // Industry breakdown
        const industryBreakdown: Record<string, number> = {};
        interviews.forEach(i => {
            if (i.industry) {
                industryBreakdown[i.industry] = (industryBreakdown[i.industry] || 0) + 1;
            }
        });

        // Monthly trend (last 6 months) — bucketed by the viewer's calendar months.
        const monthlyTrend: Array<{ month: string; count: number }> = [];
        for (let i = 5; i >= 0; i--) {
            const targetMonthIndex = viewerMonthIndex - i;
            const yearOffset = Math.floor(targetMonthIndex / 12);
            const normalizedMonth = ((targetMonthIndex % 12) + 12) % 12;
            const targetYear = viewerYear + yearOffset;
            const { start, end } = monthBoundsUTC(targetYear, normalizedMonth, viewerTz);
            const monthName = formatInTimeZone(start, viewerTz, "MMM yyyy");
            const count = interviews.filter(interview => {
                const sentDate = new Date(interview.sent_at);
                return sentDate >= start && sentDate < end;
            }).length;
            monthlyTrend.push({ month: monthName, count });
        }

        return NextResponse.json({
            success: true,
            stats: {
                overview: {
                    totalInterviews,
                    confirmedInterviews,
                    pendingConfirmation,
                    cancelledInterviews,
                    monthlyInterviews,
                    avgResponseTimeHours: avgResponseTime,
                },
                cancellations: {
                    total: cancelledInterviews,
                    byCandidate: cancelledByCandidate,
                    byEmployer: cancelledByEmployer,
                },
                interviewMode: {
                    online: onlineInterviews,
                    physical: physicalInterviews,
                },
                industryBreakdown,
                monthlyTrend,
            },
        });
    } catch (error) {
        console.error("Error fetching interview statistics:", error);
        await logError({ source: "api/mis/interviews/stats:GET", errorType: "APIError", message: error instanceof Error ? error.message : String(error) });
        return NextResponse.json(
            { error: "Failed to fetch statistics" },
            { status: 500 }
        );
    }
}

