    useEffect(() => {
        fetch("/api/candidate/profile").then(r => r.json()).then(d => {
            if (d.success && d.data) setInfo({ email: d.data.email ?? "—", created_at: d.data.created_at ?? "", approval_status: d.data.approval_status ?? "pending" });
