                                                {proof.status}
                                            </Badge>
                                        </div>
                                        <div className="text-xs text-muted-foreground">Uploaded {fmtDate(proof.uploaded_at)}</div>
                                        {proof.review_notes && (
                                            <div className="text-xs italic text-muted-foreground">Note: {proof.review_notes}</div>
                                        )}
