                                ))}
                            </div>
                        )}
                    </div>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={onClose}>Close</Button>
                    {(payment.status === "pending_payment" || payment.status === "rejected") && (
                        <Button onClick={() => { onClose(); onUpload(); }}>
                            <Upload className="h-4 w-4 mr-1" />Upload Slip
                        </Button>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

