import { createAdminClient } from "@/lib/supabase/admin";
import { EmployerSetupPasswordForm } from "@/components/employer/EmployerSetupPasswordForm";
import { Shield } from "lucide-react";
import { Metadata } from "next";

export const metadata: Metadata = {
    title: "Set Up Password | JobGenie",
    description: "Complete your account setup",
};

interface SetupPasswordPageProps {
    searchParams: Promise<{ token?: string }>;
}

export default async function SetupPasswordPage({ searchParams }: SetupPasswordPageProps) {
    const { token } = await searchParams;

    if (!token) {
        redirect("/employer/login");
    }

    // Verify token exists and get user info
    const adminClient = createAdminClient();
    const { data: user, error } = await adminClient
        .from("users")
        .select("id, email, invitation_token_expires_at, role")
        .eq("invitation_token", token)
        .maybeSingle();

    if (error || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-green-50 to-emerald-100 dark:bg-background">
                <div className="w-full max-w-md">
                    <div className="bg-white dark:bg-card border dark:border-green-800/50 rounded-2xl shadow-xl p-8 text-center">
                        <div className="mb-4">
                            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/20 mb-4">
                                <span className="text-3xl">❌</span>
                            </div>
                        </div>
                        <h1 className="text-2xl font-bold mb-2">Invalid Invitation</h1>
                        <p className="text-muted-foreground mb-6">
                            This invitation link is invalid or has already been used. Please contact your administrator for assistance.
                        </p>
                        <a
                            href="/employer/login"
                            className="inline-flex items-center justify-center rounded-lg bg-primary text-primary-foreground px-6 py-3 text-sm font-medium hover:bg-primary/90 transition-colors"
                        >
                            Go to Login
                        </a>
                    </div>
                </div>
            </div>
        );
    }

    // Check if token is expired
    if (user.invitation_token_expires_at) {
        const expiryDate = new Date(user.invitation_token_expires_at);
        if (expiryDate.getTime() < Date.now()) {
            return (
                <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-green-50 to-emerald-100 dark:bg-background">
                    <div className="w-full max-w-md">
                        <div className="bg-white dark:bg-card border dark:border-green-800/50 rounded-2xl shadow-xl p-8 text-center">
                            <div className="mb-4">
                                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-yellow-100 dark:bg-yellow-900/20 mb-4">
                                    <span className="text-3xl">⏰</span>
                                </div>
                            </div>
                            <h1 className="text-2xl font-bold mb-2">Invitation Expired</h1>
                            <p className="text-muted-foreground mb-6">
                                This invitation has expired. Please contact your company administrator to receive a new invitation.
                            </p>
                            <a
                                href="/employer/login"
                                className="inline-flex items-center justify-center rounded-lg bg-primary text-primary-foreground px-6 py-3 text-sm font-medium hover:bg-primary/90 transition-colors"
                            >
                                Go to Login
                            </a>
                        </div>
                    </div>
                </div>
            );
        }
    }

    // Verify role is employer
    if (user.role !== "employer") {
        redirect("/employer/login");
    }

    // Get employer details
    const { data: employer } = await adminClient
        .from("employers")
        .select("first_name, last_name, email")
        .eq("user_id", user.id)
        .single();

    return (
        <div className="min-h-screen flex items-center justify-center p-4 bg-background dark:bg-background">
            <div className="w-full max-w-md">
                {/* Header */}
                <div className="text-center mb-8">
                    <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-primary/10 mb-4">
                        <Shield className="h-8 w-8 text-primary" />
                    </div>
                    <h1 className="text-3xl font-bold mb-2">Welcome to JobGenie!</h1>
                    <p className="text-muted-foreground">
                        Set up your password to complete your account
                    </p>
                </div>

                {/* User Info Card */}
                {employer && (
                    <div className="bg-green-50 dark:bg-card border border-green-200 dark:border-green-700 rounded-lg p-4 mb-6">
                        <p className="text-sm text-green-700 dark:text-green-400">
                            <strong>Account:</strong> {employer.first_name} {employer.last_name}
                        </p>
                        <p className="text-sm text-green-700 dark:text-green-400">
                            <strong>Email:</strong> {employer.email}
                        </p>
                    </div>
                )}

                {/* Form Card */}
                <div className="bg-white dark:bg-card border dark:border-green-800/50 rounded-2xl shadow-xl p-8">
                    <EmployerSetupPasswordForm token={token} />
                </div>

                {/* Footer */}
                <p className="text-center text-sm text-muted-foreground mt-6">
                    Already have an account?{" "}
                    <a href="/employer/login" className="text-primary hover:underline font-medium">
                        Log in
                    </a>
                </p>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { X, Loader2, User, Briefcase, GraduationCap, Award, FolderGit2, BadgeCheck as CertIcon, CheckCircle2, XCircle, RotateCcw, FileText } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
    Sheet,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetTitle,
} from "@/components/ui/sheet";
import { Separator } from "@/components/ui/separator";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { approveCandidateProfile, rejectCandidateProfile, revokeCandidateApproval } from "@/app/actions/candidate";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { formatIndustry, sortEducations } from "@/lib/utils";
import { formatUTCDate } from "@/lib/date-utils";

interface CandidateData {
    id: string;
    first_name: string;
    last_name: string;
    email: string;
    phone: string;
    alternative_phone?: string;
    address: string;
    country?: string;
    industry: string;
    current_position: string;
    years_of_experience: number;
    experience_level: string;
    expected_monthly_salary?: number;
    availability_status?: string;
    notice_period?: string;
    professional_summary?: string;
    approval_status: string;
    rejection_reason?: string;
    membership_no?: string;
    resume_url?: string;
    profile_image_url?: string;
    work_experiences: Array<{
        job_title: string;
        company: string;
        start_date: string;
        end_date?: string;
        is_current: boolean;
    }>;
    educations: Array<{
        degree_diploma: string;
        institution: string;
        status: string;
    }>;
    awards: Array<{
        nature_of_award: string;
        offered_by: string;
    }>;
    projects: Array<{
        project_name: string;
        description: string;
    }>;
    certificates: Array<{
        certificate_name: string;
        issuing_authority: string;
    }>;
}

interface CandidateProfileViewProps {
    candidateId: string;
    onClose: () => void;
}

export function CandidateProfileView({ candidateId, onClose }: CandidateProfileViewProps) {
    const [candidate, setCandidate] = useState<CandidateData | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [showRejectForm, setShowRejectForm] = useState(false);
    const [rejectionReason, setRejectionReason] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const router = useRouter();

    useEffect(() => {
        async function fetchCandidate() {
            try {
                const response = await fetch(`/api/mis/candidates/${candidateId}`);
                if (response.ok) {
                    const data = await response.json();
                    setCandidate(data);
                }
            } catch (error) {
                console.error("Error fetching candidate:", error);
            } finally {
                setIsLoading(false);
            }
        }

        fetchCandidate();
    }, [candidateId]);

    const handleApprove = async () => {
        setIsSubmitting(true);
        const result = await approveCandidateProfile(candidateId);

        if (result.success) {
            toast.success(result.message);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    const handleReject = async () => {
        if (!rejectionReason.trim()) {
            toast.error("Please provide a reason for rejection.");
            return;
        }

        setIsSubmitting(true);
        const result = await rejectCandidateProfile(candidateId, rejectionReason);

        if (result.success) {
            toast.success(result.message);
            setShowRejectForm(false);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    const handleRevoke = async () => {
        setIsSubmitting(true);
        const result = await revokeCandidateApproval(candidateId);

        if (result.success) {
            toast.success(result.message);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    return (
        <Sheet open={true} onOpenChange={onClose}>
            <SheetContent className="sm:max-w-2xl w-full flex flex-col h-full p-0">
                <SheetHeader className="px-6 pt-6 pb-3 shrink-0">
                    <SheetTitle>Candidate Profile</SheetTitle>
                    <SheetDescription>
                        Review complete profile before approval or rejection
                    </SheetDescription>
                </SheetHeader>

                {isLoading ? (
                    <div className="flex items-center justify-center flex-1">
                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                    </div>
                ) : !candidate ? (
                    <div className="flex items-center justify-center flex-1">
                        <p className="text-muted-foreground">Failed to load candidate profile</p>
                    </div>
                ) : (
                    <>
                        <ScrollArea className="flex-1 overflow-auto">
                            <div className="space-y-6 px-6 pb-4">
                                {/* Basic Information */}
                                <section>
                                    <div className="flex items-center gap-2 mb-3">
                                        <User className="h-5 w-5 text-primary" />
                                        <h3 className="text-lg font-semibold">Basic Information</h3>
                                    </div>

                                    {/* Profile Image */}
                                    <div className="flex items-center gap-4 mb-4">
                                        <Avatar className="h-20 w-20 border-2 border-border">
                                            <AvatarImage src={candidate.profile_image_url || undefined} alt={`${candidate.first_name} ${candidate.last_name}`} />
                                            <AvatarFallback className="text-lg font-semibold bg-primary/10 text-primary">
                                                {candidate.first_name[0]}{candidate.last_name[0]}
                                            </AvatarFallback>
                                        </Avatar>
                                        <div>
                                            <p className="font-semibold text-base">{candidate.first_name} {candidate.last_name}</p>
                                            {candidate.membership_no && (
                                                <p className="text-sm text-muted-foreground font-mono">Member: {candidate.membership_no}</p>
                                            )}
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4 text-sm">
                                        <div>
                                            <p className="text-muted-foreground">Email</p>
                                            <p className="font-medium">{candidate.email}</p>
                                        </div>
                                        <div>
                                            <p className="text-muted-foreground">Phone</p>
                                            <p className="font-medium">{candidate.phone}</p>
                                        </div>
                                        {candidate.alternative_phone && (
                                            <div>
                                                <p className="text-muted-foreground">Alt. Phone</p>
                                                <p className="font-medium">{candidate.alternative_phone}</p>
                                            </div>
                                        )}
                                        <div className="col-span-2">
                                            <p className="text-muted-foreground">Address</p>
                                            <p className="font-medium">{candidate.address}</p>
                                        </div>
                                        {candidate.country && (
                                            <div>
                                                <p className="text-muted-foreground">Country</p>
                                                <p className="font-medium">{candidate.country}</p>
                                            </div>
                                        )}
                                    </div>
                                </section>

                                <Separator />

                                {/* Professional Information */}
                                <section>
                                    <div className="flex items-center gap-2 mb-3">
                                        <Briefcase className="h-5 w-5 text-primary" />
                                        <h3 className="text-lg font-semibold">Professional Details</h3>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4 text-sm">
                                        <div>
                                            <p className="text-muted-foreground">Industry</p>
                                            <p className="font-medium">{formatIndustry(candidate.industry)}</p>
                                        </div>
                                        <div>
                                            <p className="text-muted-foreground">Current Position</p>
                                            <p className="font-medium">{candidate.current_position}</p>
                                        </div>
                                        <div>
                                            <p className="text-muted-foreground">Experience</p>
                                            <p className="font-medium">
                                                {candidate.years_of_experience} years ({candidate.experience_level})
                                            </p>
                                        </div>
                                        {candidate.expected_monthly_salary && (
                                            <div>
                                                <p className="text-muted-foreground">Expected Salary</p>
                                                <p className="font-medium">LKR {candidate.expected_monthly_salary.toLocaleString()}</p>
                                            </div>
                                        )}
                                        {candidate.availability_status && (
                                            <div>
                                                <p className="text-muted-foreground">Availability</p>
                                                <p className="font-medium">{candidate.availability_status}</p>
                                            </div>
                                        )}
                                        {candidate.notice_period && (
                                            <div>
                                                <p className="text-muted-foreground">Notice Period</p>
                                                <p className="font-medium">{candidate.notice_period}</p>
                                            </div>
                                        )}
                                        {candidate.resume_url && (
                                            <div className="col-span-2 my-4">
                                                <p className="text-muted-foreground mb-1">Resume</p>
                                                <Button variant="default" size="sm" asChild className="h-9 bg-green-500">
                                                    <a href={candidate.resume_url} target="_blank" rel="noopener noreferrer">
                                                        <FileText className="mr-2 h-4 w-4" />
                                                        View Candidate Resume
                                                    </a>
                                                </Button>
                                            </div>
                                        )}
                                    </div>

                                    {candidate.professional_summary && (
                                        <div className="mt-3">
                                            <p className="text-muted-foreground text-sm">Professional Summary</p>
                                            <p className="text-sm mt-1">{candidate.professional_summary}</p>
                                        </div>
                                    )}
                                </section>

                                {/* Work Experience */}
                                {candidate.work_experiences.length > 0 && (
                                    <>
                                        <Separator />
                                        <section>
                                            <div className="flex items-center gap-2 mb-3">
                                                <Briefcase className="h-5 w-5 text-primary" />
                                                <h3 className="text-lg font-semibold">Work Experience</h3>
                                            </div>
                                            <div className="space-y-3">
                                                {candidate.work_experiences.map((exp, idx) => (
                                                    <div key={idx} className="text-sm">
                                                        <p className="font-medium">{exp.job_title}</p>
                                                        <p className="text-muted-foreground">{exp.company}</p>
                                                        <p className="text-xs text-muted-foreground">
                                                            {formatUTCDate(exp.start_date, "MMM yyyy")} -{' '}
                                                            {exp.is_current ? 'Present' : formatUTCDate(exp.end_date!, "MMM yyyy")}
                                                        </p>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    </>
                                )}

                                {/* Education */}
                                {candidate.educations.length > 0 && (
                                    <>
                                        <Separator />
                                        <section>
                                            <div className="flex items-center gap-2 mb-3">
                                                <GraduationCap className="h-5 w-5 text-primary" />
                                                <h3 className="text-lg font-semibold">Education</h3>
                                            </div>
                                            <div className="space-y-2">
                                                {sortEducations(candidate.educations).map((edu, idx) => (
                                                    <div key={idx} className="text-sm">
                                                        <p className="font-medium">{edu.degree_diploma}</p>
                                                        <p className="text-muted-foreground">{edu.institution}</p>
                                                        <Badge variant="outline" className="text-xs mt-1">{edu.status}</Badge>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    </>
                                )}

                                {/* Awards */}
                                {candidate.awards.length > 0 && (
                                    <>
                                        <Separator />
                                        <section>
                                            <div className="flex items-center gap-2 mb-3">
                                                <Award className="h-5 w-5 text-primary" />
                                                <h3 className="text-lg font-semibold">Awards & Achievements</h3>
                                            </div>
                                            <div className="space-y-2">
                                                {candidate.awards.map((award, idx) => (
                                                    <div key={idx} className="text-sm">
                                                        <p className="font-medium">{award.nature_of_award}</p>
                                                        <p className="text-muted-foreground">{award.offered_by}</p>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    </>
                                )}

                                {/* Projects */}
                                {candidate.projects.length > 0 && (
                                    <>
                                        <Separator />
                                        <section>
                                            <div className="flex items-center gap-2 mb-3">
                                                <FolderGit2 className="h-5 w-5 text-primary" />
                                                <h3 className="text-lg font-semibold">Projects</h3>
                                            </div>
                                            <div className="space-y-2">
                                                {candidate.projects.map((project, idx) => (
                                                    <div key={idx} className="text-sm">
                                                        <p className="font-medium">{project.project_name}</p>
                                                        <p className="text-muted-foreground text-xs">{project.description}</p>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    </>
                                )}

                                {/* Certificates */}
                                {candidate.certificates.length > 0 && (
                                    <>
                                        <Separator />
                                        <section>
                                            <div className="flex items-center gap-2 mb-3">
                                                <CertIcon className="h-5 w-5 text-primary" />
                                                <h3 className="text-lg font-semibold">Certifications</h3>
                                            </div>
                                            <div className="space-y-2">
                                                {candidate.certificates.map((cert, idx) => (
                                                    <div key={idx} className="text-sm">
                                                        <p className="font-medium">{cert.certificate_name}</p>
                                                        <p className="text-muted-foreground">{cert.issuing_authority}</p>
                                                    </div>
                                                ))}
                                            </div>
                                        </section>
                                    </>
                                )}

                                {/* Rejection Reason (if rejected) */}
                                {candidate.approval_status === 'rejected' && candidate.rejection_reason && (
                                    <>
                                        <Separator />
                                        <section>
                                            <h3 className="text-lg font-semibold mb-2 text-red-600">Previous Rejection Reason</h3>
                                            <p className="text-sm text-muted-foreground">{candidate.rejection_reason}</p>
                                        </section>
                                    </>
                                )}
                            </div>
                        </ScrollArea>

                        {/* Action Buttons - Fixed at bottom */}
                        <div className="border-t px-6 py-4 bg-background shrink-0">
                            {!showRejectForm ? (
                                <div className="space-y-3">
                                    {/* Revoke Button - Only shown for approved/rejected candidates */}
                                    {(candidate.approval_status === 'approved' || candidate.approval_status === 'rejected') && (
                                        <Button
                                            onClick={handleRevoke}
                                            disabled={isSubmitting}
                                            variant="outline"
                                            className="w-full h-11 font-medium border-amber-500 text-amber-600 hover:bg-amber-50 dark:border-amber-600 dark:text-amber-500 dark:hover:bg-amber-950"
                                            size="lg"
                                        >
                                            <RotateCcw className="mr-2 h-4 w-4" />
                                            Revoke & Reset to Pending
                                        </Button>
                                    )}

                                    {/* Approve/Reject Buttons */}
                                    <div className="flex gap-3">
                                        {candidate.approval_status !== 'approved' && (
                                            <Button
                                                onClick={handleApprove}
                                                disabled={isSubmitting}
                                                className="flex-1 h-11 bg-green-600 hover:bg-green-700 dark:bg-green-700 dark:hover:bg-green-800 font-medium"
                                                size="lg"
                                            >
                                                <CheckCircle2 className="mr-2 h-4 w-4" />
                                                Approve Profile
                                            </Button>
                                        )}
                                        {candidate.approval_status !== 'rejected' && (
                                            <Button
                                                onClick={() => setShowRejectForm(true)}
                                                disabled={isSubmitting}
                                                variant="destructive"
                                                className="flex-1 h-11 font-medium"
                                                size="lg"
                                            >
                                                <XCircle className="mr-2 h-4 w-4" />
                                                Reject Profile
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    <div>
                                        <Label htmlFor="reject-reason" className="text-sm font-medium">Rejection Reason</Label>
                                        <Textarea
                                            id="reject-reason"
                                            placeholder="Provide a detailed reason for rejection..."
                                            value={rejectionReason}
                                            onChange={(e) => setRejectionReason(e.target.value)}
                                            rows={3}
                                            className="mt-1.5 resize-none"
                                        />
                                    </div>
                                    <div className="flex gap-3">
                                        <Button
                                            onClick={handleReject}
                                            disabled={isSubmitting || !rejectionReason.trim()}
                                            variant="destructive"
                                            className="flex-1 h-11 font-medium"
                                            size="lg"
                                        >
                                            {isSubmitting ? "Rejecting..." : "Confirm Rejection"}
                                        </Button>
                                        <Button
                                            onClick={() => {
                                                setShowRejectForm(false);
                                                setRejectionReason("");
                                            }}
                                            disabled={isSubmitting}
                                            variant="outline"
                                            className="flex-1 h-11 font-medium"
                                            size="lg"
                                        >
                                            Cancel
                                        </Button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </>
                )
                }
            </SheetContent >
        </Sheet >
    );
}

import { Users, UserSquare, Building2, Briefcase, BarChart3, Shield, FileText, Settings } from "lucide-react";
import { MISLayout } from "@/components/mis";
import { createClient } from "@/lib/supabase/server";
import { StatCardContainer } from "@/components/shared/StatCardContainer";
import { MISDashboardCard } from "@/components/mis/MISDashboardCard";

export default async function MISDashboardPage() {
    const supabase = await createClient();

    // Fetch counts for dashboard stats
    const [candidatesCount, employersCount, jobsCount, interviewsCount] = await Promise.all([
        supabase.from('candidates').select('id', { count: 'exact', head: true }),
        supabase.from('companies').select('id', { count: 'exact', head: true }),
        supabase.from('jobs').select('id', { count: 'exact', head: true }),
        supabase.from('job_invitations').select('id', { count: 'exact', head: true }),
    ]);

    const dashboardCards = [
        {
            title: "MIS User Management",
            description: "Manage MIS administrator accounts",
            href: "/mis/users",
            icon: Users,
            color: "blue",
            count: null,
        },
        {
            title: "Roles & Permissions",
            description: "Manage roles and access control",
            href: "/mis/roles",
            icon: Shield,
            color: "violet",
            count: null,
        },
        {
            title: "Candidate Approvals",
            description: "Review and approve candidate profiles",
            href: "/mis/candidates",
            icon: UserSquare,
            color: "green",
            count: candidatesCount.count || 0,
        },
        {
            title: "Employer Management",
            description: "Manage employer accounts and companies",
            href: "/mis/employers",
            icon: Building2,
            color: "purple",
            count: employersCount.count || 0,
        },
        {
            title: "Job Management",
            description: "Oversee job postings and listings",
            href: "/mis/jobs",
            icon: Briefcase,
            color: "orange",
            count: jobsCount.count || 0,
        },
        {
            title: "Reports & Analytics",
            description: "View system reports and analytics",
            href: "/mis/reports",
            icon: BarChart3,
            color: "indigo",
            count: null,
        },
        {
            title: "Audit Logs",
            description: "View system activity and error logs",
            href: "/mis/audit",
            icon: FileText,
            color: "red",
            count: null,
        },
        {
            title: "Master Data",
            description: "Manage industries and designations",
            href: "/mis/settings",
            icon: Settings,
            color: "gray",
            count: null,
        },
    ];

    const colorClasses: Record<string, { bg: string; text: string; hover: string }> = {
        blue: { bg: "bg-blue-500/10", text: "text-blue-500", hover: "hover:border-blue-500" },
        green: { bg: "bg-green-500/10", text: "text-green-500", hover: "hover:border-green-500" },
        purple: { bg: "bg-purple-500/10", text: "text-purple-500", hover: "hover:border-purple-500" },
        orange: { bg: "bg-orange-500/10", text: "text-orange-500", hover: "hover:border-orange-500" },
        indigo: { bg: "bg-indigo-500/10", text: "text-indigo-500", hover: "hover:border-indigo-500" },
        violet: { bg: "bg-violet-500/10", text: "text-violet-500", hover: "hover:border-violet-500" },
        red: { bg: "bg-red-500/10", text: "text-red-500", hover: "hover:border-red-500" },
        gray: { bg: "bg-gray-500/10", text: "text-gray-500", hover: "hover:border-gray-500" },
    };

    return (
        <MISLayout
            pageTitle="MIS Dashboard"
            pageDescription="Welcome to the Management Information System dashboard."
        >
            <div className="space-y-8">
                <StatCardContainer className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {dashboardCards.map((card) => {
                        const Icon = card.icon;
                        const colors = colorClasses[card.color];

                        return (
                            <MISDashboardCard
                                key={card.href}
                                href={card.href}
                                hoverClass={colors.hover}
                            >
                                <div className="flex items-start justify-between mb-3">
                                    <div className={`p-2 ${colors.bg} rounded-lg`}>
                                        <Icon className={`h-6 w-6 ${colors.text}`} />
                                    </div>
                                    {card.count !== null && (
                                        <div className="text-2xl font-bold">{card.count}</div>
                                    )}
                                </div>
                                <h2 className="text-lg font-semibold mb-2 group-hover:text-primary transition-colors">
                                    {card.title}
                                </h2>
                                <p className="text-sm text-muted-foreground">
                                    {card.description}
                                </p>
                            </MISDashboardCard>
                        );
                    })}
                </StatCardContainer>
            </div>
        </MISLayout>
    );
}

"use client";

import { useEffect, useState } from "react";
import { X, Loader2, Building, Globe, MapPin, Phone, FileText, CheckCircle2, XCircle, RotateCcw, ExternalLink } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
    Sheet,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetTitle,
} from "@/components/ui/sheet";
import { Separator } from "@/components/ui/separator";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { approveCompanyProfile, rejectCompanyProfile, revokeCompanyApproval } from "@/app/actions/employer";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { formatIndustry } from "@/lib/utils";

interface AdminData {
    first_name: string;
    last_name: string;
    email: string;
    phone: string;
    job_title?: string;
}

interface CompanyData {
    id: string;
    company_name: string;
    business_registration_no: string;
    industry: string;
    business_registered_address: string;
    br_certificate_url: string;
    logo_url?: string;
    description?: string;
    phone: string;
    website?: string;
    company_size?: string;
    specialities: string[];
    map_link?: string;
    approval_status: string;
    rejection_reason?: string;
    admin: AdminData;
}

interface EmployerProfileViewProps {
    companyId: string;
    onClose: () => void;
}

export function EmployerProfileView({ companyId, onClose }: EmployerProfileViewProps) {
    const [company, setCompany] = useState<CompanyData | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [showRejectForm, setShowRejectForm] = useState(false);
    const [rejectionReason, setRejectionReason] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const router = useRouter();

    useEffect(() => {
        async function fetchCompany() {
            try {
                const response = await fetch(`/api/mis/companies/${companyId}`);
                if (response.ok) {
                    const data = await response.json();
                    setCompany(data);
                }
            } catch (error) {
                console.error("Error fetching company:", error);
            } finally {
                setIsLoading(false);
            }
        }

        fetchCompany();
    }, [companyId]);

    const handleApprove = async () => {
        setIsSubmitting(true);
        const result = await approveCompanyProfile(companyId);

        if (result.success) {
            toast.success(result.message);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    const handleReject = async () => {
        if (!rejectionReason.trim()) {
            toast.error("Please provide a reason for rejection.");
            return;
        }

        setIsSubmitting(true);
        const result = await rejectCompanyProfile(companyId, rejectionReason);

        if (result.success) {
            toast.success(result.message);
            setShowRejectForm(false);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    const handleRevoke = async () => {
        setIsSubmitting(true);
        const result = await revokeCompanyApproval(companyId);

        if (result.success) {
            toast.success(result.message);
            router.refresh();
            onClose();
        } else {
            toast.error(result.message);
        }
        setIsSubmitting(false);
    };

    return (
        <Sheet open={true} onOpenChange={onClose}>
            <SheetContent className="sm:max-w-2xl w-full flex flex-col h-full p-0">
                <SheetHeader className="px-6 pt-6 pb-3 shrink-0">
                    <SheetTitle>Company Profile</SheetTitle>
                    <SheetDescription>
                        Review company details and business registration before approval
                    </SheetDescription>
                </SheetHeader>

                {isLoading ? (
                    <div className="flex items-center justify-center flex-1">
                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                    </div>
                ) : !company ? (
                    <div className="flex items-center justify-center flex-1">
                        <p className="text-muted-foreground">Failed to load company profile</p>
                    </div>
                ) : (
                    <>
                        <ScrollArea className="flex-1 overflow-auto">
                            <div className="space-y-6 px-6 pb-4">
                                {/* Basic Information */}
                                <section>
                                    <div className="flex items-center gap-2 mb-3">
                                        <Building className="h-5 w-5 text-primary" />
                                        <h3 className="text-lg font-semibold">Company Information</h3>
                                    </div>

                                    {/* Company Logo & Name */}
                                    <div className="flex items-center gap-4 mb-4">
                                        <Avatar className="h-20 w-20 border-2 border-border">
                                            <AvatarImage src={company.logo_url || undefined} alt={company.company_name} />
                                            <AvatarFallback className="text-lg font-semibold bg-primary/10 text-primary">
                                                {company.company_name.substring(0, 2).toUpperCase()}
                                            </AvatarFallback>
                                        </Avatar>
                                        <div>
                                            <p className="font-semibold text-xl">{company.company_name}</p>
                                            <div className="flex items-center gap-2 mt-1">
                                                <Badge variant="secondary" className="font-normal">
                                                    {formatIndustry(company.industry)}
                                                </Badge>
                                                {company.company_size && (
                                                    <span className="text-sm text-muted-foreground">
                                                        • {company.company_size} Employees
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4 text-sm">
                                        <div>
                                            <p className="text-muted-foreground">Business Reg. No</p>
                                            <p className="font-medium font-mono">{company.business_registration_no}</p>
                                        </div>
                                        <div>
                                            <p className="text-muted-foreground">Phone</p>
                                            <p className="font-medium">{company.phone}</p>
                                        </div>
                                        {company.website && (
                                            <div className="col-span-2">
                                                <p className="text-muted-foreground">Website</p>
                                                <a
                                                    href={company.website.startsWith('http') ? company.website : `https://${company.website}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="font-medium text-primary hover:underline flex items-center gap-1"
                                                >
                                                    {company.website} <ExternalLink className="h-3 w-3" />
                                                </a>
                                            </div>
                                        )}
                                        <div className="col-span-2">
                                            <p className="text-muted-foreground">Registered Address</p>
                                            <p className="font-medium">{company.business_registered_address}</p>
                                        </div>

                                        {/* Certificate Download */}
                                        <div className="col-span-2 mt-2">
                                            <p className="text-muted-foreground mb-1">Business Registration Certificate</p>
                                            <Button variant="default" size="sm" asChild className="h-9 w-full sm:w-auto bg-blue-600 hover:bg-blue-700">
                                                <a href={company.br_certificate_url} target="_blank" rel="noopener noreferrer">
                                                    <FileText className="mr-2 h-4 w-4" />
                                                    View Registration Certificate
                                                </a>
                                            </Button>
                                        </div>
                                    </div>

                                    {company.description && (
                                        <div className="mt-4">
                                            <p className="text-muted-foreground text-sm mb-1">Description</p>
                                            <p className="text-sm leading-relaxed">{company.description}</p>
                                        </div>
                                    )}

                                    {company.specialities && company.specialities.length > 0 && (
                                        <div className="mt-4">
                                            <p className="text-muted-foreground text-sm mb-2">Specialties</p>
                                            <div className="flex flex-wrap gap-2">
                                                {company.specialities.map((spec, idx) => (
                                                    <Badge key={idx} variant="outline">{spec}</Badge>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </section>

                                <Separator />

                                {/* Admin Information */}
                                <section>
                                    <div className="flex items-center gap-2 mb-3">
                                        <MapPin className="h-5 w-5 text-primary" />
                                        <h3 className="text-lg font-semibold">Super Admin Contact</h3>
                                    </div>

                                    {company.admin ? (
                                        <div className="bg-muted/30 p-4 rounded-lg text-sm border">
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <p className="text-muted-foreground">Name</p>
                                                    <p className="font-medium">{company.admin.first_name} {company.admin.last_name}</p>
                                                </div>
                                                <div>
                                                    <p className="text-muted-foreground">Job Title</p>
                                                    <p className="font-medium">{company.admin.job_title || "N/A"}</p>
                                                </div>
                                                <div>
                                                    <p className="text-muted-foreground">Email</p>
                                                    <p className="font-medium">{company.admin.email}</p>
                                                </div>
                                                <div>
                                                    <p className="text-muted-foreground">Phone</p>
                                                    <p className="font-medium">{company.admin.phone || "N/A"}</p>
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <p className="text-muted-foreground text-sm italic">Admin information not available</p>
                                    )}
                                </section>

                                {/* Rejection Reason (if rejected) */}
                                {company.approval_status === 'rejected' && company.rejection_reason && (
                                    <>
                                        <Separator />
                                        <section>
                                            <h3 className="text-lg font-semibold mb-2 text-red-600">Previous Rejection Reason</h3>
                                            <div className="bg-red-50 dark:bg-red-950/20 p-3 rounded border border-red-200 dark:border-red-900">
                                                <p className="text-sm">{company.rejection_reason}</p>
                                            </div>
                                        </section>
                                    </>
                                )}
                            </div>
                        </ScrollArea>

                        {/* Action Buttons - Fixed at bottom */}
                        <div className="border-t px-6 py-4 bg-background shrink-0">
                            {!showRejectForm ? (
                                <div className="space-y-3">
                                    {/* Revoke Button - Only shown for approved/rejected companies */}
                                    {(company.approval_status === 'approved' || company.approval_status === 'rejected') && (
                                        <Button
                                            onClick={handleRevoke}
                                            disabled={isSubmitting}
                                            variant="outline"
                                            className="w-full h-11 font-medium border-amber-500 text-amber-600 hover:bg-amber-50 dark:border-amber-600 dark:text-amber-500 dark:hover:bg-amber-950"
                                            size="lg"
                                        >
                                            <RotateCcw className="mr-2 h-4 w-4" />
                                            Revoke & Reset to Pending
                                        </Button>
                                    )}

                                    {/* Approve/Reject Buttons */}
                                    <div className="flex gap-3">
                                        {company.approval_status !== 'approved' && (
                                            <Button
                                                onClick={handleApprove}
                                                disabled={isSubmitting}
                                                className="flex-1 h-11 bg-green-600 hover:bg-green-700 dark:bg-green-700 dark:hover:bg-green-800 font-medium"
                                                size="lg"
                                            >
                                                <CheckCircle2 className="mr-2 h-4 w-4" />
                                                Approve Company
                                            </Button>
                                        )}
                                        {company.approval_status !== 'rejected' && (
                                            <Button
                                                onClick={() => setShowRejectForm(true)}
                                                disabled={isSubmitting}
                                                variant="destructive"
                                                className="flex-1 h-11 font-medium"
                                                size="lg"
                                            >
                                                <XCircle className="mr-2 h-4 w-4" />
                                                Reject Company
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    <div>
                                        <Label htmlFor="reject-reason" className="text-sm font-medium">Rejection Reason</Label>
                                        <Textarea
                                            id="reject-reason"
                                            placeholder="Provide a detailed reason for rejection..."
                                            value={rejectionReason}
                                            onChange={(e) => setRejectionReason(e.target.value)}
                                            rows={3}
                                            className="mt-1.5 resize-none"
                                        />
                                    </div>
                                    <div className="flex gap-3">
                                        <Button
                                            onClick={handleReject}
                                            disabled={isSubmitting || !rejectionReason.trim()}
                                            variant="destructive"
                                            className="flex-1 h-11 font-medium"
                                            size="lg"
                                        >
                                            {isSubmitting ? "Rejecting..." : "Confirm Rejection"}
                                        </Button>
                                        <Button
                                            onClick={() => {
                                                setShowRejectForm(false);
                                                setRejectionReason("");
                                            }}
                                            disabled={isSubmitting}
                                            variant="outline"
                                            className="flex-1 h-11 font-medium"
                                            size="lg"
                                        >
                                            Cancel
                                        </Button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </>
                )
                }
            </SheetContent >
        </Sheet >
    );
}

