"use client";

import { useState, useMemo, useEffect } from "react";
import { formatUTCTime, formatDate } from "@/lib/date-utils";
import { formatIndustry } from "@/lib/utils";
import {
    Table,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Search, Video, MapPin, CheckCircle2, Clock, XCircle, Calendar } from "lucide-react";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";

interface Interview {
    id: string;
    industry: string;
    job_designation: string;
    interview_mode: "online" | "physical" | null;
    interview_confirmed: boolean;
    invitation_canceled: boolean;
    canceled_by: "candidate" | "employer" | null;
    sent_at: string;
    viewed_at: string | null;
    responded_at: string | null;
    selected_time_slot: any;
    mis_rescheduled?: boolean;
    mis_rescheduled_at?: string;
    mis_reschedule_data?: any;
    candidate: {
        first_name: string;
        last_name: string;
        email: string;
        profile_image_url: string | null;
    };
    employer: {
        first_name: string;
        last_name: string;
        company_id: string;
    };
    company: {
        company_name: string;
        logo_url: string | null;
    };
}

interface InterviewTableProps {
    interviews: Interview[];
    onViewDetails: (id: string) => void;
}

export function InterviewTable({ interviews, onViewDetails }: InterviewTableProps) {
    const [mounted, setMounted] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState<string>("all");
    const [modeFilter, setModeFilter] = useState<string>("all");
    const [companyFilter, setCompanyFilter] = useState<string>("all");
    const [jobRoleFilter, setJobRoleFilter] = useState<string>("all");
    const [cancelledByFilter, setCancelledByFilter] = useState<string>("all");

    useEffect(() => {
        setMounted(true);
    }, []);

    const filteredInterviews = useMemo(() => {
        return (interviews || []).filter((interview) => {
            // Search filter
            const searchLower = searchQuery.toLowerCase();
            const matchesSearch =
                interview.candidate.first_name.toLowerCase().includes(searchLower) ||
                interview.candidate.last_name.toLowerCase().includes(searchLower) ||
                interview.company.company_name.toLowerCase().includes(searchLower) ||
                formatIndustry(interview.industry).toLowerCase().includes(searchLower) ||
                interview.job_designation.toLowerCase().includes(searchLower);

            if (!matchesSearch) return false;

            // Status filter
            if (statusFilter !== "all") {
                if (statusFilter === "confirmed" && (!interview.interview_confirmed || interview.invitation_canceled)) {
                    return false;
                }
                if (statusFilter === "pending" && (interview.interview_confirmed || interview.invitation_canceled)) {
                    return false;
                }
                if (statusFilter === "cancelled" && !interview.invitation_canceled) {
                    return false;
                }
            }

            // Mode filter
            if (modeFilter !== "all" && interview.interview_mode !== modeFilter) {
                return false;
            }

            // Company filter
            if (companyFilter !== "all" && interview.company.company_name !== companyFilter) {
                return false;
            }

            // Job role filter
            if (jobRoleFilter !== "all" && interview.job_designation !== jobRoleFilter) {
                return false;
            }

            // Cancelled By filter
            if (cancelledByFilter !== "all") {
                if (cancelledByFilter === "candidate" && interview.canceled_by !== "candidate") {
                    return false;
                }
                if (cancelledByFilter === "employer" && interview.canceled_by !== "employer") {
                    return false;
                }
            }

            return true;
        });
    }, [interviews, searchQuery, statusFilter, modeFilter, companyFilter, jobRoleFilter, cancelledByFilter]);

    // Get unique companies and job roles for filter options
    const uniqueCompanies = useMemo(() => {
        const companies = new Set(interviews.map(i => i.company.company_name));
        return Array.from(companies).sort();
    }, [interviews]);

    const uniqueJobRoles = useMemo(() => {
        const roles = new Set(interviews.map(i => i.job_designation));
        return Array.from(roles).sort();
    }, [interviews]);

    const getStatusBadge = (interview: Interview) => {
        if (interview.mis_rescheduled) {
            return (
                <Badge className="bg-green-600 text-white gap-1">
                    <Calendar className="h-3 w-3" />
                    Rescheduled
                </Badge>
            );
        }
        if (interview.invitation_canceled) {
            return (
                <Badge variant="destructive" className="gap-1">
                    <XCircle className="h-3 w-3" />
                    Cancelled
                </Badge>
            );
        }
        if (interview.interview_confirmed) {
            return (
                <Badge variant="default" className="gap-1 bg-green-600">
                    <CheckCircle2 className="h-3 w-3" />
                    Confirmed
                </Badge>
            );
        }
        return (
            <Badge variant="secondary" className="gap-1">
                <Clock className="h-3 w-3" />
                Pending
            </Badge>
        );
    };

    const getEngagementBadge = (interview: Interview) => {
        if (interview.responded_at) {
            return <Badge variant="outline" className="bg-green-50 text-green-700 border-green-200">Responded</Badge>;
        }
        if (interview.viewed_at) {
            return <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200">Viewed</Badge>;
        }
        return <Badge variant="outline" className="bg-gray-50 text-gray-700 border-gray-200">Sent</Badge>;
    };

    const getInterviewDateTime = (interview: Interview) => {
        // Prioritize MIS reschedule data if available and rescheduled
        if (interview.mis_rescheduled && interview.mis_reschedule_data) {
            return `${formatDate(interview.mis_reschedule_data.date)} at ${formatUTCTime(interview.mis_reschedule_data.date, interview.mis_reschedule_data.time)}`;
        }

        if (interview.selected_time_slot) {
            const slot = interview.selected_time_slot as any;
            return `${formatDate(slot.date)} at ${formatUTCTime(slot.date, slot.time)}`;
        }
        return "Not scheduled";
    };

    return (
        <div className="space-y-4">
            {/* Filters */}
            <div className="flex flex-col gap-3">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Search by candidate, company, industry, or job role..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-9"
                    />
                </div>
                {mounted && (
                    <div className="flex flex-wrap gap-2">
                        <Select value={statusFilter} onValueChange={setStatusFilter}>
                            <SelectTrigger className="w-[140px]">
                                <SelectValue placeholder="Status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Statuses</SelectItem>
                                <SelectItem value="confirmed">Confirmed</SelectItem>
                                <SelectItem value="pending">Pending</SelectItem>
                                <SelectItem value="cancelled">Cancelled</SelectItem>
                            </SelectContent>
                        </Select>
                        <Select value={modeFilter} onValueChange={setModeFilter}>
                            <SelectTrigger className="w-[140px]">
                                <SelectValue placeholder="Mode" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Modes</SelectItem>
                                <SelectItem value="online">Online</SelectItem>
                                <SelectItem value="physical">Physical</SelectItem>
                            </SelectContent>
                        </Select>
                        <Select value={companyFilter} onValueChange={setCompanyFilter}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Company" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Companies</SelectItem>
                                {uniqueCompanies.map(company => (
                                    <SelectItem key={company} value={company}>
                                        {company}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Select value={jobRoleFilter} onValueChange={setJobRoleFilter}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Job Role" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Job Roles</SelectItem>
                                {uniqueJobRoles.map(role => (
                                    <SelectItem key={role} value={role}>
                                        {role}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Select value={cancelledByFilter} onValueChange={setCancelledByFilter}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Cancelled By" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">Cancelled By</SelectItem>
                                <SelectItem value="candidate">Candidate</SelectItem>
                                <SelectItem value="employer">Employer</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                )}
            </div>

            {/* Results count */}
            <div className="text-sm text-muted-foreground">
                Showing {filteredInterviews.length} of {interviews.length} interviews
            </div>

            {/* Table */}
            <div className="rounded-md border">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Candidate</TableHead>
                            <TableHead>Company</TableHead>
                            <TableHead>Position</TableHead>
                            <TableHead>Interview Date/Time</TableHead>
                            <TableHead>Mode</TableHead>
                            <TableHead>Engagement</TableHead>
                            <TableHead>Status</TableHead>
                        </TableRow>
                    </TableHeader>
                    <tbody>
                        {filteredInterviews.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                                    No interviews found
                                </TableCell>
                            </TableRow>
                        ) : (
                            filteredInterviews.map((interview) => (
                                <TableRow
                                    key={interview.id}
                                    className="cursor-pointer border-b transition-colors duration-150 hover:bg-muted/60"
                                    onClick={() => onViewDetails(interview.id)}
                                >
                                    <TableCell>
                                        <div className="flex items-center gap-3">
                                            <Avatar className="h-8 w-8">
                                                <AvatarImage src={interview.candidate.profile_image_url || undefined} />
                                                <AvatarFallback>
                                                    {interview.candidate.first_name[0]}{interview.candidate.last_name[0]}
                                                </AvatarFallback>
                                            </Avatar>
                                            <div>
                                                <div className="font-medium">
                                                    {interview.candidate.first_name} {interview.candidate.last_name}
                                                </div>
                                                <div className="text-xs text-muted-foreground">
                                                    {interview.candidate.email}
                                                </div>
                                            </div>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center gap-2">
                                            {interview.company.logo_url && (
                                                <Avatar className="h-6 w-6">
                                                    <AvatarImage src={interview.company.logo_url} />
                                                    <AvatarFallback>{interview.company.company_name[0]}</AvatarFallback>
                                                </Avatar>
                                            )}
                                            <span className="font-medium">{interview.company.company_name}</span>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div>
                                            <div className="font-medium text-sm">{interview.job_designation}</div>
                                            <div className="text-xs text-muted-foreground">{formatIndustry(interview.industry)}</div>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div className="text-sm">{getInterviewDateTime(interview)}</div>
                                    </TableCell>
                                    <TableCell>
                                        {interview.interview_mode === "online" ? (
                                            <Badge variant="outline" className="gap-1 bg-blue-50 text-blue-700 border-blue-200">
                                                <Video className="h-3 w-3" />
                                                Online
                                            </Badge>
                                        ) : interview.interview_mode === "physical" ? (
                                            <Badge variant="outline" className="gap-1 bg-purple-50 text-purple-700 border-purple-200">
                                                <MapPin className="h-3 w-3" />
                                                Physical
                                            </Badge>
                                        ) : (
                                            <span className="text-xs text-muted-foreground">-</span>
                                        )}
                                    </TableCell>
                                    <TableCell>{getEngagementBadge(interview)}</TableCell>
                                    <TableCell>{getStatusBadge(interview)}</TableCell>
                                    {/* <TableCell className="text-right">
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            onClick={() => onViewDetails(interview.id)}
                                        >
                                            <Eye className="h-4 w-4 mr-1" />
                                            View
                                        </Button>
                                    </TableCell> */}
                                </TableRow>
                            ))
                        )}
                    </tbody>
                </Table>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { InterviewStatsCards } from "./InterviewStatsCards";
import { InterviewTable } from "./InterviewTable";
import { InterviewDetailView } from "./InterviewDetailView";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertCircle } from "lucide-react";

interface InterviewsClientProps {
    initialInterviews: any[];
    initialStats: any;
    error: string | null;
}

export function InterviewsClient({ initialInterviews, initialStats, error }: InterviewsClientProps) {
    const [selectedInterviewId, setSelectedInterviewId] = useState<string | null>(null);
    const [interviews, setInterviews] = useState(initialInterviews);

    const refreshInterviews = async () => {
        try {
            const response = await fetch('/api/mis/interviews');
            const data = await response.json();
            if (data.success) {
                setInterviews(data.interviews);
            }
        } catch (error) {
            console.error('Error refreshing interviews:', error);
        }
    };

    const handleViewDetails = (id: string) => {
        setSelectedInterviewId(id);
    };

    const handleCloseDetails = () => {
        setSelectedInterviewId(null);
    };

    return (
        <div className="space-y-6">
            {error && (
                <Alert variant="destructive">
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>{error}</AlertDescription>
                </Alert>
            )}

            {initialStats && (
                <>
                    {/* Statistics Cards */}
                    <InterviewStatsCards stats={initialStats} />

                    {/* Interviews Table */}
                    <InterviewTable
                        interviews={interviews}
                        onViewDetails={handleViewDetails}
                    />

                    {/* Interview Detail View Dialog */}
                    <InterviewDetailView
                        interviewId={selectedInterviewId}
                        onClose={handleCloseDetails}
                        onInterviewUpdate={refreshInterviews}
                    />
                </>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import {
    CreditCard, Building2, User, Calendar, DollarSign, Eye, CheckCircle2,
    XCircle, Clock, RefreshCw, Plus, Pencil, Trash2, AlertTriangle, FileText,
    ExternalLink, Settings2, Receipt,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import {
    Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
    Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

// ── Types ──────────────────────────────────────────────────────────────────

interface PaymentType {
    id: string; code: string; label: string; description: string | null;
    is_active: boolean; sort_order: number;
}
interface BankDetails {
    id: string; bank_name: string; account_name: string; account_number: string;
    branch: string | null; bank_code: string | null; swift_code: string | null;
    sort_order: number; is_active: boolean;
}
interface PaymentPricing {
    id: string; amount: number; currency: string; is_active: boolean;
    effective_from: string; payment_types: { id: string; code: string; label: string };
}
interface PaymentRequest {
    id: string; company_id: string; employer_id: string | null;
    amount: number; currency: string; description: string; due_date: string | null;
    status: string; bank_transfer_reference: string | null;
    created_at: string; updated_at: string;
    companies: { id: string; company_name: string; industry: string } | null;
    employers: { id: string; first_name: string; last_name: string; email: string; designation: string | null } | null;
    payment_types: { id: string; code: string; label: string } | null;
    payment_proofs: {
        id: string; status: string; uploaded_at: string; file_url: string; file_name: string;
        reviewed_at: string | null; review_notes: string | null;
    }[];
}
interface Stats {
    total_revenue: number; currency: string;
    pending_count: number; pending_amount: number;
    under_review_count: number; rejected_count: number; overdue_count: number;
    by_type: { label: string; count: number; amount: number }[];
}

// ── Helpers ────────────────────────────────────────────────────────────────

const STATUS_VARIANTS: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
    pending_payment: "secondary",
    under_review: "outline",
    verified: "default",
    rejected: "destructive",
    cancelled: "outline",
};
const STATUS_LABELS: Record<string, string> = {
    pending_payment: "Pending Payment",
    under_review: "Under Review",
    verified: "Verified",
    rejected: "Rejected",
    cancelled: "Cancelled",
};

function StatusBadge({ status }: { status: string }) {
    return <Badge variant={STATUS_VARIANTS[status] ?? "outline"}>{STATUS_LABELS[status] ?? status}</Badge>;
}

function TH({ children }: { children: React.ReactNode }) {
    return <th className="py-2 px-3 text-xs font-medium text-muted-foreground whitespace-nowrap text-left">{children}</th>;
}
function TD({ children, className = "" }: { children: React.ReactNode; className?: string }) {
    return <td className={`py-2 px-3 text-sm ${className}`}>{children}</td>;
}

function fmtAmount(amount: number, currency = "LKR") {
    return `${currency} ${amount.toLocaleString("en-LK", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function fmtDate(iso: string) {
    return new Date(iso).toLocaleDateString("en-LK", { day: "2-digit", month: "short", year: "numeric" });
}

// ── Main Component ────────────────────────────────────────────────────────

export function PaymentsClient() {
    const [activeTab, setActiveTab] = useState<"payments" | "configuration">("payments");

    return (
        <div className="space-y-6">
            {/* Tab bar */}
            <div className="flex gap-1 border-b">
                {(["payments", "configuration"] as const).map((t) => (
                    <button
                        key={t}
                        onClick={() => setActiveTab(t)}
                        className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px capitalize transition-colors ${
                            activeTab === t
                                ? "border-primary text-primary"
                                : "border-transparent text-muted-foreground hover:text-foreground"
                        }`}
                    >
                        {t === "payments" ? (
                            <span className="flex items-center gap-2"><Receipt className="h-4 w-4" />Payments</span>
                        ) : (
                            <span className="flex items-center gap-2"><Settings2 className="h-4 w-4" />Configuration</span>
                        )}
                    </button>
                ))}
            </div>

            {activeTab === "payments" ? <PaymentsTab /> : <ConfigurationTab />}
        </div>
    );
}

// ── Payments Tab ──────────────────────────────────────────────────────────

function PaymentsTab() {
    const [stats, setStats] = useState<Stats | null>(null);
    const [payments, setPayments] = useState<PaymentRequest[]>([]);
    const [total, setTotal] = useState(0);
    const [page, setPage] = useState(1);
    const [limit] = useState(25);
    const [loading, setLoading] = useState(true);
    const [statsLoading, setStatsLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");
    const [typeFilter, setTypeFilter] = useState("all");
    const [dateFrom, setDateFrom] = useState("");
    const [dateTo, setDateTo] = useState("");
    const [paymentTypes, setPaymentTypes] = useState<PaymentType[]>([]);
    const [showCreateDialog, setShowCreateDialog] = useState(false);
    const [selectedPayment, setSelectedPayment] = useState<PaymentRequest | null>(null);
    const [showDetailDialog, setShowDetailDialog] = useState(false);
    const [showReviewDialog, setShowReviewDialog] = useState(false);
    const [reviewPayment, setReviewPayment] = useState<PaymentRequest | null>(null);

    const loadStats = useCallback(async () => {
        setStatsLoading(true);
        try {
            const res = await fetch("/api/mis/payments/stats");
            const json = await res.json();
            if (json.success) setStats(json.data);
        } finally {
            setStatsLoading(false);
        }
    }, []);

    const loadPayments = useCallback(async () => {
        setLoading(true);
        try {
            const url = new URL("/api/mis/payments", window.location.origin);
            url.searchParams.set("page", String(page));
            url.searchParams.set("limit", String(limit));
            if (search) url.searchParams.set("search", search);
            if (statusFilter && statusFilter !== "all") url.searchParams.set("status", statusFilter);
            if (typeFilter && typeFilter !== "all") url.searchParams.set("type", typeFilter);
            if (dateFrom) url.searchParams.set("dateFrom", dateFrom);
            if (dateTo) url.searchParams.set("dateTo", dateTo);
            const res = await fetch(url.toString());
            const json = await res.json();
            if (json.success) {
                setPayments(json.data);
                setTotal(json.pagination.total);
            }
        } finally {
            setLoading(false);
        }
    }, [page, limit, search, statusFilter, typeFilter, dateFrom, dateTo]);

    const loadPaymentTypes = useCallback(async () => {
        const res = await fetch("/api/mis/payment-types");
        const json = await res.json();
        if (json.success) setPaymentTypes(json.data);
    }, []);

    useEffect(() => { loadStats(); loadPaymentTypes(); }, [loadStats, loadPaymentTypes]);
    useEffect(() => { loadPayments(); }, [loadPayments]);

    const totalPages = Math.ceil(total / limit);

    const exportCSV = () => {
        const headers = ["ID", "Company", "Employer", "Type", "Amount", "Currency", "Due Date", "Status", "Created"];
        const rows = payments.map((p) => [
            p.id,
            p.companies?.company_name ?? "",
            p.employers ? `${p.employers.first_name} ${p.employers.last_name}` : "",
            p.payment_types?.label ?? "",
            p.amount,
            p.currency,
            p.due_date ?? "",
            p.status,
            p.created_at.slice(0, 10),
        ]);
        const csv = [headers, ...rows].map((r) => r.map(String).map((v) => `"${v.replace(/"/g, '""')}"`).join(",")).join("\n");
        const a = document.createElement("a");
        a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
        a.download = `payments-${new Date().toISOString().slice(0, 10)}.csv`;
        a.click();
    };

    return (
        <div className="space-y-6">
            {/* KPI Cards */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {statsLoading ? (
                    Array.from({ length: 4 }).map((_, i) => (
                        <Card key={i}><CardContent className="pt-6"><Skeleton className="h-12 w-full" /></CardContent></Card>
                    ))
                ) : stats ? (
                    <>
                        <KpiCard title="Total Revenue" value={fmtAmount(stats.total_revenue)} icon={DollarSign} color="text-green-600" bgColor="bg-green-50" />
                        <KpiCard title="Pending Payment" value={`${stats.pending_count} · ${fmtAmount(stats.pending_amount)}`} icon={Clock} color="text-amber-600" bgColor="bg-amber-50" />
                        <KpiCard title="Under Review" value={String(stats.under_review_count)} icon={Eye} color="text-blue-600" bgColor="bg-blue-50" />
                        <KpiCard title="Overdue" value={String(stats.overdue_count)} icon={AlertTriangle} color="text-red-600" bgColor="bg-red-50" />
                    </>
                ) : null}
            </div>

            {/* Header + Filter bar */}
            <div className="flex flex-col gap-4">
                <div className="flex items-center justify-between">
                    <h2 className="text-lg font-semibold">Payment Requests</h2>
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" onClick={exportCSV}>Export CSV</Button>
                        <Button size="sm" onClick={() => setShowCreateDialog(true)}>
                            <Plus className="h-4 w-4 mr-1" />Create Request
                        </Button>
                    </div>
                </div>
                <div className="flex flex-wrap gap-2">
                    <Input
                        placeholder="Search company…"
                        value={search}
                        onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                        className="w-48"
                    />
                    <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v); setPage(1); }}>
                        <SelectTrigger className="w-40"><SelectValue placeholder="Status" /></SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">All Statuses</SelectItem>
                            <SelectItem value="pending_payment">Pending Payment</SelectItem>
                            <SelectItem value="under_review">Under Review</SelectItem>
                            <SelectItem value="verified">Verified</SelectItem>
                            <SelectItem value="rejected">Rejected</SelectItem>
                            <SelectItem value="cancelled">Cancelled</SelectItem>
                        </SelectContent>
                    </Select>
                    <Select value={typeFilter} onValueChange={(v) => { setTypeFilter(v); setPage(1); }}>
                        <SelectTrigger className="w-44"><SelectValue placeholder="Payment Type" /></SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">All Types</SelectItem>
                            {paymentTypes.map((pt) => (
                                <SelectItem key={pt.id} value={pt.code}>{pt.label}</SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <Input type="date" value={dateFrom} onChange={(e) => { setDateFrom(e.target.value); setPage(1); }} className="w-36" />
                    <Input type="date" value={dateTo} onChange={(e) => { setDateTo(e.target.value); setPage(1); }} className="w-36" />
                    <Button variant="ghost" size="sm" onClick={() => { loadPayments(); loadStats(); }}>
                        <RefreshCw className="h-4 w-4" />
                    </Button>
                </div>
            </div>

            {/* Table */}
            <div className="rounded-lg border bg-card overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-muted/50 border-b">
                        <tr>
                            <TH>Company</TH>
                            <TH>Employer</TH>
                            <TH>Type</TH>
                            <TH>Amount</TH>
                            <TH>Due Date</TH>
                            <TH>Status</TH>
                            <TH>Proof</TH>
                            <TH>Actions</TH>
                        </tr>
                    </thead>
                    <tbody>
                        {loading ? (
                            Array.from({ length: 5 }).map((_, i) => (
                                <tr key={i} className="border-b">
                                    {Array.from({ length: 8 }).map((__, j) => (
                                        <TD key={j}><Skeleton className="h-4 w-full" /></TD>
                                    ))}
                                </tr>
                            ))
                        ) : payments.length === 0 ? (
                            <tr><td colSpan={8} className="py-10 text-center text-muted-foreground text-sm">No payment requests found</td></tr>
                        ) : (
                            payments.map((p) => {
                                const latestProof = p.payment_proofs?.slice().sort((a, b) =>
                                    new Date(b.uploaded_at).getTime() - new Date(a.uploaded_at).getTime()
                                )[0];
                                return (
                                    <tr key={p.id} className="border-b hover:bg-muted/30 transition-colors">
                                        <TD>
                                            <div className="font-medium text-sm">{p.companies?.company_name ?? "—"}</div>
                                            <div className="text-xs text-muted-foreground">{p.companies?.industry ?? ""}</div>
                                        </TD>
                                        <TD>
                                            {p.employers ? (
                                                <div>
                                                    <div className="text-sm">{p.employers.first_name} {p.employers.last_name}</div>
                                                    <div className="text-xs text-muted-foreground">{p.employers.designation ?? ""}</div>
                                                </div>
                                            ) : "—"}
                                        </TD>
                                        <TD>
                                            <Badge variant="outline" className="text-xs">{p.payment_types?.label ?? "—"}</Badge>
                                        </TD>
                                        <TD className="font-medium">{fmtAmount(Number(p.amount), p.currency)}</TD>
                                        <TD>
                                            {p.due_date ? (
                                                <span className={new Date(p.due_date) < new Date() && p.status === "pending_payment" ? "text-red-600 font-medium" : ""}>
                                                    {fmtDate(p.due_date)}
                                                </span>
                                            ) : "—"}
                                        </TD>
                                        <TD><StatusBadge status={p.status} /></TD>
                                        <TD>
                                            {latestProof ? (
                                                <a href={latestProof.file_url} target="_blank" rel="noopener noreferrer"
                                                    className="flex items-center gap-1 text-xs text-blue-600 hover:underline">
                                                    <FileText className="h-3 w-3" />{latestProof.file_name.slice(0, 16)}…
                                                </a>
                                            ) : <span className="text-xs text-muted-foreground">None</span>}
                                        </TD>
                                        <TD>
                                            <div className="flex gap-1">
                                                <Button variant="ghost" size="sm" onClick={() => { setSelectedPayment(p); setShowDetailDialog(true); }}>
                                                    <Eye className="h-3.5 w-3.5" />
                                                </Button>
                                                {p.status === "under_review" && (
                                                    <Button variant="ghost" size="sm" onClick={() => { setReviewPayment(p); setShowReviewDialog(true); }}>
                                                        <CheckCircle2 className="h-3.5 w-3.5 text-green-600" />
                                                    </Button>
                                                )}
                                            </div>
                                        </TD>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
                <div className="flex items-center justify-between text-sm text-muted-foreground">
                    <span>{Math.min((page - 1) * limit + 1, total)}–{Math.min(page * limit, total)} of {total}</span>
                    <div className="flex gap-1">
                        <Button variant="outline" size="sm" disabled={page === 1} onClick={() => setPage(1)}>«</Button>
                        <Button variant="outline" size="sm" disabled={page === 1} onClick={() => setPage(p => p - 1)}>‹</Button>
                        <span className="px-3 py-1 border rounded-md bg-muted">{page} / {totalPages}</span>
                        <Button variant="outline" size="sm" disabled={page === totalPages} onClick={() => setPage(p => p + 1)}>›</Button>
                        <Button variant="outline" size="sm" disabled={page === totalPages} onClick={() => setPage(totalPages)}>»</Button>
                    </div>
                </div>
            )}

            {/* Dialogs */}
            <CreatePaymentRequestDialog
                open={showCreateDialog}
                onClose={() => setShowCreateDialog(false)}
                onCreated={() => { loadPayments(); loadStats(); }}
                paymentTypes={paymentTypes.filter(pt => pt.is_active)}
            />
            {selectedPayment && (
                <PaymentDetailDialog
                    open={showDetailDialog}
                    payment={selectedPayment}
                    onClose={() => setShowDetailDialog(false)}
                />
            )}
            {reviewPayment && (
                <ReviewProofDialog
                    open={showReviewDialog}
                    payment={reviewPayment}
                    onClose={() => setShowReviewDialog(false)}
                    onReviewed={() => { loadPayments(); loadStats(); setShowReviewDialog(false); }}
                />
            )}
        </div>
    );
}

