export function ReportsClient() {
    const [filter, setFilter] = useState<FilterDimension>("all");
    const [period, setPeriod] = useState<PeriodPreset>("30d");
    const [dateFrom, setDateFrom] = useState("");
    const [dateTo, setDateTo] = useState("");
    const [data, setData] = useState<ReportData | null>(null);
    const [engagement, setEngagement] = useState<PlatformEngagement | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        if (period === "custom" && (!dateFrom || !dateTo)) return;
        setLoading(true);
        setError(null);
        try {
            const params = new URLSearchParams({ filter, period });
            if (period === "custom") { params.set("dateFrom", dateFrom); params.set("dateTo", dateTo); }
            const res = await fetch(`/api/mis/analytics/reports?${params}`);
            const json = await res.json();
            if (json.success) {
                setData(json.data);
                setEngagement(json.platformEngagement);
            } else {
                setError("Failed to load report data.");
            }
        } catch {
            setError("Network error. Please try again.");
        } finally {
            setLoading(false);
        }
    }, [filter, period, dateFrom, dateTo]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const activeFilterLabel = FILTER_TABS.find(t => t.id === filter)?.label ?? "Overview";
    const periodLabel = period === "custom" ? `${dateFrom} – ${dateTo}` : period === "all_time" ? "All Time" : PERIOD_PRESETS.find(p => p.id === period)?.label ?? period;

    return (
        <div className="space-y-6">
            {/* ── Toolbar (no-print) ──────────────────────────────────────── */}
            <div className="no-print space-y-3">
                <div className="flex flex-wrap gap-1">
                    {FILTER_TABS.map(({ id, label, icon: Icon }) => (
                        <button key={id} onClick={() => setFilter(id)}
                            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors border ${
                                filter === id ? "bg-primary text-primary-foreground border-primary"
                                : "border-border hover:bg-muted text-muted-foreground hover:text-foreground"}`}>
                            <Icon className="h-3.5 w-3.5" />{label}
                        </button>
                    ))}
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    <div className="flex items-center gap-1">
                        {PERIOD_PRESETS.map(({ id, label }) => (
                            <button key={id} onClick={() => setPeriod(id)}
                                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border ${
                                    period === id ? "bg-primary/10 text-primary border-primary"
                                    : "border-border hover:bg-muted text-muted-foreground"}`}>
                                {label}
                            </button>
                        ))}
                    </div>

                    {period === "custom" && (
                        <div className="flex items-center gap-2">
                            <Input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className="h-8 text-xs w-36" />
                            <span className="text-muted-foreground text-xs">to</span>
                            <Input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className="h-8 text-xs w-36" />
                        </div>
                    )}

                    <div className="ml-auto flex gap-2">
                        <Button variant="outline" size="sm" onClick={fetchData} disabled={loading}>
                            <RefreshCw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} />
                            Refresh
                        </Button>
                        <Button size="sm" onClick={() => window.print()}>
                            <Printer className="h-4 w-4 mr-2" />
                            Print
                        </Button>
                    </div>
                </div>
            </div>

            {/* ── Print header ────────────────────────────────────────────── */}
            <div className="hidden print:block mb-6 border-b pb-4">
                <h1 className="text-2xl font-bold">JobGenie — Reports & Analytics</h1>
                <p className="text-sm text-gray-600 mt-1">
                    Section: <strong>{activeFilterLabel}</strong> · Period: <strong>{periodLabel}</strong>
                </p>
                <p className="text-xs text-gray-400 mt-0.5">Generated {new Date().toLocaleString()}</p>
            </div>

            {error && (
                <div className="rounded-lg border border-destructive/40 bg-destructive/10 px-4 py-3 text-sm text-destructive">{error}</div>
            )}

            {loading ? <LoadingSkeleton /> : data ? (
                <div className="space-y-8">
                    <div className="flex items-center gap-2 text-lg font-semibold">
                        {(() => { const tab = FILTER_TABS.find(t => t.id === filter); const Icon = tab?.icon ?? BarChart3; return <><Icon className="h-5 w-5 text-primary" />{tab?.label ?? "Overview"}</>; })()}
                        <Badge variant="secondary" className="ml-2 text-xs">{periodLabel}</Badge>
                    </div>

                    {filter === "all" && <AllView data={data} />}
                    {filter === "candidates" && <CandidatesView data={data} />}
                    {filter === "employers" && <EmployersView data={data} />}
                    {filter === "companies" && <CompaniesView data={data} />}
                    {filter === "jobs" && <JobsView data={data} />}
                    {filter === "applications" && <ApplicationsView data={data} />}

                    <Separator />
                    {engagement && <PlatformEngagementSection engagement={engagement} />}
                </div>
            ) : null}
        </div>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Check, Loader2, Save, Shield } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";

interface Permission {
    id: string;
    name: string;
    resource: string;
    action: string;
    description: string | null;
}

interface PermissionsManagerProps {
    roleId: string;
    roleName: string;
    allPermissions: Permission[];
    assignedPermissionIds: string[];
}

export function PermissionsManager({
    roleId,
    roleName,
    allPermissions,
    assignedPermissionIds,
}: PermissionsManagerProps) {
    const router = useRouter();
    const [selectedPermissions, setSelectedPermissions] = useState<Set<string>>(
        new Set(assignedPermissionIds)
    );
    const [isSaving, setIsSaving] = useState(false);

    // Group permissions by resource
    const groupedPermissions = allPermissions.reduce((acc, permission) => {
        if (!acc[permission.resource]) {
            acc[permission.resource] = [];
        }
        acc[permission.resource].push(permission);
        return acc;
    }, {} as Record<string, Permission[]>);

    const handleTogglePermission = (permissionId: string) => {
        setSelectedPermissions((prev) => {
            const newSet = new Set(prev);
            if (newSet.has(permissionId)) {
                newSet.delete(permissionId);
            } else {
                newSet.add(permissionId);
            }
            return newSet;
        });
    };

    const handleSelectAllForResource = (resource: string, checked: boolean) => {
        setSelectedPermissions((prev) => {
            const newSet = new Set(prev);
            const resourcePermissions = groupedPermissions[resource];
            
            if (checked) {
                resourcePermissions.forEach((p) => newSet.add(p.id));
            } else {
                resourcePermissions.forEach((p) => newSet.delete(p.id));
            }
            
            return newSet;
        });
    };

    const handleGrantAllPermissions = (checked: boolean) => {
        if (checked) {
            // Grant all permissions
            const allPermissionIds = allPermissions.map((p) => p.id);
            setSelectedPermissions(new Set(allPermissionIds));
        } else {
            // Revoke all permissions
            setSelectedPermissions(new Set());
        }
    };

    const handleSave = async () => {
        const originalSet = new Set(assignedPermissionIds);
        const currentSet = selectedPermissions;

        // Calculate what to add and what to remove
        const toAdd = Array.from(currentSet).filter((id) => !originalSet.has(id));
        const toRemove = Array.from(originalSet).filter((id) => !currentSet.has(id));

        if (toAdd.length === 0 && toRemove.length === 0) {
            toast.info("No changes to save");
            return;
        }

        setIsSaving(true);

        try {
            // Add new permissions
            if (toAdd.length > 0) {
                const addResponse = await fetch(`/api/mis/roles/${roleId}/permissions`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ permission_ids: toAdd }),
                });

                const addData = await addResponse.json();
                if (!addData.success) {
                    throw new Error(addData.error || "Failed to add permissions");
                }
            }

            // Remove permissions
            if (toRemove.length > 0) {
                const removeResponse = await fetch(`/api/mis/roles/${roleId}/permissions`, {
                    method: "DELETE",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ permission_ids: toRemove }),
                });

                const removeData = await removeResponse.json();
                if (!removeData.success) {
                    throw new Error(removeData.error || "Failed to remove permissions");
                }
            }

            toast.success("Permissions updated successfully");
            router.refresh();
        } catch (error) {
            console.error("Error updating permissions:", error);
            toast.error(error instanceof Error ? error.message : "Failed to update permissions");
        } finally {
            setIsSaving(false);
        }
    };

    const hasChanges =
        selectedPermissions.size !== assignedPermissionIds.length ||
        !Array.from(selectedPermissions).every((id) => assignedPermissionIds.includes(id));

    const allPermissionsSelected = selectedPermissions.size === allPermissions.length;

    return (
        <div className="space-y-6">
            {/* Action Bar */}
            <div className="flex items-center justify-between">
                <div className="text-sm text-muted-foreground">
                    {selectedPermissions.size} of {allPermissions.length} permissions selected
                </div>
                <Button onClick={handleSave} disabled={!hasChanges || isSaving}>
                    {isSaving ? (
                        <>
                            <Loader2 className="h-4 w-4 animate-spin" />
                            Saving...
                        </>
                    ) : (
                        <>
                            <Save className="h-4 w-4" />
                            Save Changes
                        </>
                    )}
                </Button>
            </div>

            {/* Grant All Permissions Toggle */}
            <Alert className="border-primary/20 bg-primary/5">
                <Shield className="h-4 w-4" />
                <AlertDescription className="flex items-center justify-between">
                    <div className="flex-1">
                        <div className="font-medium mb-1">Grant All Permissions (Super Admin Mode)</div>
                        <div className="text-xs text-muted-foreground">
                            Toggle to grant or revoke all {allPermissions.length} permissions at once
                        </div>
                    </div>
                    <div className="flex items-center gap-3 ml-4">
                        <span className="text-sm font-medium">
                            {allPermissionsSelected ? "All Granted" : "Limited Access"}
                        </span>
                        <Switch
                            checked={allPermissionsSelected}
                            onCheckedChange={handleGrantAllPermissions}
                        />
                    </div>
                </AlertDescription>
            </Alert>

            {/* Permissions by Resource */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {Object.entries(groupedPermissions).map(([resource, permissions]) => {
                    const allSelected = permissions.every((p) => selectedPermissions.has(p.id));
                    const someSelected = permissions.some((p) => selectedPermissions.has(p.id));

                    return (
                        <Card key={resource}>
                            <CardHeader className="pb-3">
                                <div className="flex items-center justify-between">
                                    <CardTitle className="text-base capitalize">
                                        {resource.replace(/_/g, " ")}
                                    </CardTitle>
                                    <div className="flex items-center gap-2">
                                        <Checkbox
                                            id={`${resource}-all`}
                                            checked={allSelected}
                                            onCheckedChange={(checked) =>
                                                handleSelectAllForResource(resource, checked === true)
                                            }
                                        />
                                        <Label
                                            htmlFor={`${resource}-all`}
                                            className="text-xs text-muted-foreground cursor-pointer"
                                        >
                                            Select All
                                        </Label>
                                    </div>
                                </div>
                                <CardDescription className="text-xs">
                                    {someSelected
                                        ? `${permissions.filter((p) => selectedPermissions.has(p.id)).length} of ${permissions.length} selected`
                                        : "No permissions selected"}
                                </CardDescription>
                            </CardHeader>
                            <CardContent className="space-y-2">
                                {permissions.map((permission) => (
                                    <div
                                        key={permission.id}
                                        className="flex items-start gap-3 p-2 rounded-md hover:bg-muted/50 transition-colors"
                                    >
                                        <Checkbox
                                            id={permission.id}
                                            checked={selectedPermissions.has(permission.id)}
                                            onCheckedChange={() => handleTogglePermission(permission.id)}
                                        />
                                        <div className="flex-1 cursor-pointer" onClick={() => handleTogglePermission(permission.id)}>
                                            <Label
                                                htmlFor={permission.id}
                                                className="text-sm font-medium cursor-pointer capitalize"
                                            >
                                                {permission.action.replace(/_/g, " ")}
                                            </Label>
                                            {permission.description && (
                                                <p className="text-xs text-muted-foreground mt-0.5">
                                                    {permission.description}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </CardContent>
                        </Card>
                    );
                })}
            </div>

            {/* Bottom Action Bar */}
            <div className="flex items-center justify-end pt-4 border-t">
                <Button onClick={handleSave} disabled={!hasChanges || isSaving}>
                    {isSaving ? (
                        <>
                            <Loader2 className="h-4 w-4 animate-spin" />
                            Saving...
                        </>
                    ) : (
                        <>
                            <Check className="h-4 w-4" />
                            Save Changes
                        </>
                    )}
                </Button>
            </div>
        </div>
    );
}

import Link from "next/link";
import { notFound } from "next/navigation";
