"use client";

import { useState, useTransition, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Loader2, MailCheck } from "lucide-react";
import { toast } from "sonner";
import { requestPasswordReset, type ActionState } from "@/app/actions/auth";

export function ForgotPasswordForm() {
    const [state, setState] = useState<ActionState | null>(null);
    const [isPending, startTransition] = useTransition();
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (formData: FormData) => {
        startTransition(async () => {
            try {
                const result = await requestPasswordReset(null, formData);
                setState(result);
            } catch {
                toast.error("Something went wrong. Please try again.");
            }
        });
    };

    useEffect(() => {
        if (!state) return;
        if (state.success) {
            setSubmitted(true);
        } else {
            toast.error(state.message);
        }
    }, [state]);

    if (submitted) {
        return (
            <div className="space-y-4 text-center">
                <div className="flex justify-center">
                    <div className="inline-flex items-center justify-center rounded-full bg-primary/10 p-4 text-primary">
                        <MailCheck className="h-10 w-10" />
                    </div>
                </div>
                <h2 className="text-xl font-semibold">Check Your Email</h2>
                <p className="text-sm text-muted-foreground">
                    If an account with that email exists, we&apos;ve sent a password reset link. It expires in <strong>1 hour</strong>.
                </p>
                <p className="text-xs text-muted-foreground">
                    Didn&apos;t receive it? Check your spam folder or try again.
                </p>
                <Button
                    variant="outline"
                    className="w-full"
                    onClick={() => setSubmitted(false)}
                >
                    Try a different email
                </Button>
            </div>
        );
    }

    return (
        <form action={handleSubmit} className="space-y-4">
            <div className="space-y-2">
                <Label htmlFor="email">Email Address</Label>
                <Input
                    id="email"
                    name="email"
                    type="email"
                    placeholder="your.email@example.com"
                    required
                    disabled={isPending}
                    autoComplete="email"
                />
            </div>

            <Button type="submit" variant="gradient" className="w-full" disabled={isPending}>
                {isPending ? (
                    <>
                        <Loader2 className="mr-2 h-4 w-4 shrink-0 animate-spin" />
                        Sending Reset Link...
                    </>
                ) : (
                    "Send Reset Link"
                )}
            </Button>
        </form>
    );
}

"use client";

import { useState } from "react";
import { CheckCircle2, XCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { markApprovalMessageAsSeen } from "@/app/actions/candidate";

interface ApprovalStatusNotificationProps {
    approvalStatus: "approved" | "rejected";
    rejectionReason?: string | null;
}

export function ApprovalStatusNotification({
    approvalStatus,
    rejectionReason,
}: ApprovalStatusNotificationProps) {
    const [open, setOpen] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const isApproved = approvalStatus === "approved";

    const handleClose = async () => {
        setIsSubmitting(true);

        const result = await markApprovalMessageAsSeen();

        if (result.success) {
            setOpen(false);
        } else {
            console.error("Failed to mark message as seen:", result.message);
            // Still close the dialog even if the API call failed
            setOpen(false);
        }

        setIsSubmitting(false);
    };

    return (
        <Dialog open={open} onOpenChange={() => { }}>
            <DialogContent className="sm:max-w-[500px]" showCloseButton={false} onPointerDownOutside={(e) => e.preventDefault()} onEscapeKeyDown={(e) => e.preventDefault()}>
                <DialogHeader>
                    <div className="flex items-center gap-3 mb-2">
                        {isApproved ? (
                            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-green-100 dark:bg-green-900/20">
                                <CheckCircle2 className="h-6 w-6 text-green-600 dark:text-green-500" />
                            </div>
                        ) : (
                            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-red-100 dark:bg-red-900/20">
                                <XCircle className="h-6 w-6 text-red-600 dark:text-red-500" />
                            </div>
                        )}
                        <DialogTitle className="text-2xl">
                            {isApproved ? "Profile Approved!" : "Profile Needs Improvement"}
                        </DialogTitle>
                    </div>
                    <DialogDescription className="text-base pt-2">
                        {isApproved ? (
                            <>
                                🎉 <strong>Congratulations!</strong> Your profile has been approved by our MIS
                                administrator. Welcome to JobGenie! You can now explore job opportunities and submit
                                applications.
                            </>
                        ) : (
                            <>
                                We've reviewed your profile and it needs some improvements before approval. Please
                                update your profile and resubmit it for review.
                            </>
                        )}
                    </DialogDescription>
                </DialogHeader>

                {!isApproved && rejectionReason && (
                    <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 dark:border-amber-900/50 dark:bg-amber-900/10">
                        <p className="text-sm font-medium text-amber-900 dark:text-amber-200">
                            Reason for rejection:
                        </p>
                        <p className="mt-1 text-sm text-amber-800 dark:text-amber-300">{rejectionReason}</p>
                    </div>
                )}

                <DialogFooter className="sm:justify-end">
                    <Button
                        onClick={handleClose}
                        disabled={isSubmitting}
                        className={
                            isApproved
                                ? "bg-green-600 hover:bg-green-700 dark:bg-green-700 dark:hover:bg-green-800"
                                : ""
                        }
                    >
                        {isSubmitting ? "Processing..." : "OK"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import { redirect } from "next/navigation";
import { SidebarProvider, SidebarInset } from "@/components/ui/sidebar";
import { CandidateSidebar } from "./CandidateSidebar";
import { CandidateHeader } from "./CandidateHeader";
import { PageTransitionWrapper } from "@/components/layout/PageTransitionWrapper";
import { PortalMain } from "@/components/layout/PortalMain";
import { Toaster } from "@/components/ui/toaster";
import { createClient } from "@/lib/supabase/server";

interface CandidateLayoutProps {
    children: React.ReactNode;
    pageTitle?: string;
    pageDescription?: string;
}

async function getCurrentUser() {
    const supabase = await createClient();

    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return null;
    }

    // Get additional user data from candidates table
    const { data: candidate } = await supabase
        .from('candidates')
        .select('first_name, last_name, profile_image_url, membership_no')
        .eq('user_id', user.id)
        .single();

    return {
        id: user.id,
        email: user.email || '',
        firstName: candidate?.first_name || user.user_metadata?.first_name || '',
        lastName: candidate?.last_name || user.user_metadata?.last_name || '',
        profileImage: candidate?.profile_image_url || undefined,
        membershipNo: candidate?.membership_no || undefined,
    };
}

export async function CandidateLayout({ children, pageTitle, pageDescription }: CandidateLayoutProps) {
    const user = await getCurrentUser();

    if (!user) {
        redirect('/login');
    }

    return (
        <SidebarProvider className="h-dvh! min-h-0! overflow-hidden">
            <CandidateSidebar />
            <SidebarInset className="flex flex-col min-h-0 overflow-hidden">
                <CandidateHeader
                    user={user}
                    pageTitle={pageTitle}
                    pageDescription={pageDescription}
                />
                <div className="flex-1 overflow-y-auto min-h-0 bg-background">
                    <PageTransitionWrapper>
                        <div className="p-5 md:p-6">
                            {children}
                        </div>
                    </PageTransitionWrapper>
                </div>
            </SidebarInset>
            <Toaster />
        </SidebarProvider>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { 
    CheckCircle2, 
    XCircle, 
    Briefcase,
    Calendar,
    Clock,
    Loader2,
    ArrowRight,
    MessageSquare
} from "lucide-react";
import { formatTimestamp, formatUTCDate, formatUTCTime } from "@/lib/date-utils";
import { toast } from "sonner";

interface InterviewRound {
    id: string;
    round_number: number;
    round_label: string | null;
    status: string;
    outcome: string | null;
    outcome_notes: string | null;
    outcome_at: string | null;
    selected_time_slot: any;
    interview_mode: string | null;
    confirmed_time: any;
    meeting_link: string | null;
    interview_address: string | null;
    map_link: string | null;
    confirmed_at: string | null;
    sent_at: string;
}

interface InterviewOutcomeDisplayProps {
    invitationId: string;
    onOutcomeFound?: (hasOutcome: boolean) => void;
}

export function InterviewOutcomeDisplay({ invitationId, onOutcomeFound }: InterviewOutcomeDisplayProps) {
    const [rounds, setRounds] = useState<InterviewRound[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchRounds();
    }, [invitationId]);

    const fetchRounds = async () => {
        try {
            const response = await fetch(`/api/candidate/invitations/${invitationId}/rounds`);
            const data = await response.json();

            if (data.success) {
                setRounds(data.data);
                
                // Check if any round has an outcome
                const hasOutcome = data.data.some((r: InterviewRound) => r.outcome);
                if (onOutcomeFound) {
                    onOutcomeFound(hasOutcome);
                }
            } else {
                console.error("Failed to load interview rounds");
                if (onOutcomeFound) {
                    onOutcomeFound(false);
                }
            }
        } catch (error) {
            console.error("Error fetching rounds:", error);
            if (onOutcomeFound) {
                onOutcomeFound(false);
            }
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <Card>
                <CardContent className="py-8 flex items-center justify-center">
                    <Loader2 className="h-6 w-6 animate-spin text-primary" />
                </CardContent>
            </Card>
        );
    }

    if (rounds.length === 0) {
        return null;
    }

    // Get the latest round with an outcome
    const latestRoundWithOutcome = [...rounds].reverse().find(r => r.outcome);

    if (!latestRoundWithOutcome || !latestRoundWithOutcome.outcome) {
        return null;
    }

    const getOutcomeConfig = (outcome: string) => {
        switch (outcome) {
            case 'advance':
                return {
                    icon: ArrowRight,
                    color: 'bg-green-500',
                    bgColor: 'bg-green-50 dark:bg-green-950/20',
                    borderColor: 'border-green-200 dark:border-green-800',
                    textColor: 'text-green-900 dark:text-green-100',
                    mutedColor: 'text-green-700 dark:text-green-300',
                    title: '🎉 Great News - You\'ve Advanced!',
                    message: 'Congratulations! You\'ve successfully passed this interview round and are proceeding to the next stage.'
                };
            case 'reject':
                return {
                    icon: XCircle,
                    color: 'bg-red-500',
                    bgColor: 'bg-red-50 dark:bg-red-950/20',
                    borderColor: 'border-red-200 dark:border-red-800',
                    textColor: 'text-red-900 dark:text-red-100',
                    mutedColor: 'text-red-700 dark:text-red-300',
                    title: 'Interview Result',
                    message: 'Unfortunately, you were not selected to move forward at this time. We encourage you to continue pursuing other opportunities.'
                };
            case 'offer':
                return {
                    icon: Briefcase,
                    color: 'bg-blue-500',
                    bgColor: 'bg-blue-50 dark:bg-blue-950/20',
                    borderColor: 'border-blue-200 dark:border-blue-800',
                    textColor: 'text-blue-900 dark:text-blue-100',
                    mutedColor: 'text-blue-700 dark:text-blue-300',
                    title: '🎊 Congratulations - Job Offer!',
                    message: 'Excellent news! You\'ve been selected for the position. A formal job offer will be sent to you shortly.'
                };
            default:
                return null;
        }
    };

    const config = getOutcomeConfig(latestRoundWithOutcome.outcome);
    if (!config) return null;

    const Icon = config.icon;

    // Check if there's a next round (for advance outcome)
    const nextRound = latestRoundWithOutcome.outcome === 'advance' 
        ? rounds.find(r => r.round_number === latestRoundWithOutcome.round_number + 1)
        : null;

    return (
        <Card className={`${config.borderColor} ${config.bgColor} mt-6`}>
            <CardContent className="p-6">
                <div className="flex items-start gap-3 mb-4">
                    <div className={`h-10 w-10 rounded-full ${config.color} flex items-center justify-center flex-shrink-0`}>
                        <Icon className="h-5 w-5 text-white" />
                    </div>
                    <div className="flex-1">
                        <h3 className={`font-semibold text-lg ${config.textColor} mb-1`}>
                            {config.title}
                        </h3>
                        <p className={`text-sm ${config.mutedColor}`}>
                            {config.message}
                        </p>
                    </div>
                </div>

                {/* Round Information */}
                <div className="bg-white dark:bg-gray-900 rounded-lg p-4 border space-y-3">
                    <div className="flex items-center justify-between">
                        <span className="text-sm font-semibold">
                            {latestRoundWithOutcome.round_label || `Round ${latestRoundWithOutcome.round_number}`}
                        </span>
                        <Badge className={config.color + " text-white"}>
                            {latestRoundWithOutcome.outcome === 'advance' ? 'Passed' : 
                             latestRoundWithOutcome.outcome === 'reject' ? 'Not Selected' :
                             'Offer Received'}
                        </Badge>
                    </div>

                    {latestRoundWithOutcome.outcome_at && (
                        <>
                            <Separator />
                            <div className="text-xs text-muted-foreground">
                                Decision made on {formatTimestamp(latestRoundWithOutcome.outcome_at, "MMMM d, yyyy 'at' h:mm a")}
                            </div>
                        </>
                    )}

                    {/* Employer Feedback */}
                    {latestRoundWithOutcome.outcome_notes && (
                        <>
                            <Separator />
                            <div>
                                <div className="flex items-center gap-1.5 mb-2">
                                    <MessageSquare className="h-3.5 w-3.5 text-muted-foreground" />
                                    <span className="text-xs font-medium text-muted-foreground">
                                        Feedback from Employer
                                    </span>
                                </div>
                                <div className="bg-muted/50 rounded p-3 text-sm">
                                    <p className="whitespace-pre-wrap">{latestRoundWithOutcome.outcome_notes}</p>
                                </div>
                            </div>
                        </>
                    )}
                </div>

                {/* Next Round Information */}
                {nextRound && (
                    <>
                        <Separator className="my-4" />
                        <div className="bg-white dark:bg-gray-900 rounded-lg p-4 border space-y-3">
                            <div className="flex items-center gap-2">
                                <ArrowRight className="h-4 w-4 text-green-600" />
                                <span className="text-sm font-semibold text-green-900 dark:text-green-100">
                                    Next Round: {nextRound.round_label || `Round ${nextRound.round_number}`}
                                </span>
                            </div>

                            {nextRound.status === 'confirmed' && nextRound.selected_time_slot && (
                                <>
                                    <Separator />
                                    <div className="grid gap-2 text-sm">
                                        <div className="flex items-center gap-2">
                                            <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                                            <span className="text-muted-foreground">Date:</span>
                                            <span className="font-medium">
                                                {formatUTCDate(nextRound.selected_time_slot.date)}
                                            </span>
                                        </div>
                                        {nextRound.selected_time_slot.time && (
                                            <div className="flex items-center gap-2">
                                                <Clock className="h-3.5 w-3.5 text-muted-foreground" />
                                                <span className="text-muted-foreground">Time:</span>
                                                <span className="font-medium">
                                                    {formatUTCTime(nextRound.selected_time_slot.date, nextRound.selected_time_slot.time)}
                                                </span>
                                            </div>
                                        )}
                                    </div>
                                </>
                            )}

                            {nextRound.status === 'pending' && (
                                <p className="text-sm text-muted-foreground">
                                    The employer will send you the interview details shortly.
                                </p>
                            )}
                        </div>
                    </>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { 
    Briefcase, 
    Calendar, 
    DollarSign, 
    Clock,
    FileText,
    ExternalLink,
    CheckCircle2,
    XCircle
} from "lucide-react";
import { formatTimestamp } from "@/lib/date-utils";
import Link from "next/link";

interface JobOffer {
    id: string;
    job_title: string;
    salary_amount: number | null;
    salary_currency: string | null;
    salary_period: string | null;
    start_date: string | null;
    expiry_date: string | null;
    offer_letter_url: string | null;
    description: string | null;
    status: string;
    created_at: string;
    responded_at: string | null;
}

interface JobOfferCardProps {
    invitationId: string;
    offer: JobOffer;
    companyName: string;
    jobDesignation: string;
    onRefresh?: () => void;
}

export function JobOfferCard({
    invitationId,
    offer,
    companyName,
    jobDesignation,
    onRefresh,
}: JobOfferCardProps) {
    const [responding, setResponding] = useState<"accept" | "decline" | null>(null);

    const respond = async (action: "accept" | "decline") => {
        setResponding(action);
        try {
            const response = await fetch(`/api/candidate/invitations/${invitationId}/offer`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ action }),
            });
            const data = await response.json();
            if (data.success) {
                toast.success(data.message || (action === "accept" ? "Offer accepted" : "Offer declined"));
                onRefresh?.();
            } else {
                toast.error(data.error || "Could not update your response");
            }
        } catch {
            toast.error("Something went wrong. Please try again.");
        } finally {
            setResponding(null);
        }
    };

    const getStatusConfig = () => {
        switch (offer.status) {
            case 'accepted':
                return {
                    color: 'bg-green-500',
                    text: 'Accepted',
                    icon: CheckCircle2,
                    bgClass: 'bg-gradient-to-r from-green-50 to-green-100 dark:from-green-950/60 dark:to-green-900/40',
                    borderClass: 'border-green-300 dark:border-green-700'
                };
            case 'declined':
                return {
                    color: 'bg-red-500',
                    text: 'Declined',
                    icon: XCircle,
                    bgClass: 'bg-gradient-to-r from-red-50 to-red-100 dark:from-red-950/60 dark:to-red-900/40',
                    borderClass: 'border-red-300 dark:border-red-700'
                };
            default:
                return {
                    color: 'bg-blue-500',
                    text: 'Pending Response',
                    icon: Clock,
                    bgClass: 'bg-gradient-to-r from-blue-50 to-blue-100 dark:from-blue-950/60 dark:to-blue-900/40',
                    borderClass: 'border-blue-300 dark:border-blue-700'
