                </p>
            </CardContent>
        </Card>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Calendar, Clock, Check, X, Loader2, Video, MapPin, ExternalLink, Copy, Lock } from "lucide-react";
import { toast } from "sonner";
import { formatUTCDate, formatUTCTime } from "@/lib/date-utils";
import { cn } from "@/lib/utils";

interface TimeSlot {
    date: string;
    time: string;
    order: number;
    is_alternative?: boolean;
}

interface RoundResponseCardProps {
    roundId: string;
    roundNumber: number;
    roundLabel: string | null;
    interviewMode: string | null;
    meetingLink: string | null;
    interviewAddress: string | null;
    mapLink: string | null;
    givenTimeSlots: TimeSlot[];
    onResponse: () => void;
}

export function RoundResponseCard({
    roundId,
    roundNumber,
    roundLabel,
    interviewMode,
    meetingLink,
    interviewAddress,
    mapLink,
    givenTimeSlots,
    onResponse,
}: RoundResponseCardProps) {
    const [selectedSlot, setSelectedSlot] = useState<TimeSlot | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const slots = (givenTimeSlots || []).sort((a, b) => a.order - b.order);

    const handleAccept = async () => {
        if (!selectedSlot) {
            toast.error("Please select a time slot");
            return;
        }
        setIsSubmitting(true);
        try {
            const res = await fetch(`/api/candidate/interview-rounds/${roundId}/respond`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    action: "accept",
                    selected_time_slot: selectedSlot,
                    interview_mode: interviewMode ?? "online",
                }),
            });
            const data = await res.json();
            if (data.success) {
                toast.success("Interview round accepted!");
                onResponse();
            } else {
                toast.error(data.error || "Failed to accept interview round");
            }
        } catch {
            toast.error("An error occurred");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDecline = async () => {
        setIsSubmitting(true);
        try {
            const res = await fetch(`/api/candidate/interview-rounds/${roundId}/respond`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ action: "decline" }),
            });
            const data = await res.json();
            if (data.success) {
                toast.success("Interview round declined");
                onResponse();
            } else {
                toast.error(data.error || "Failed to decline");
            }
        } catch {
            toast.error("An error occurred");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="space-y-4">
            {/* Interview mode + location details */}
            {interviewMode && (
                <div className="rounded-xl border border-border bg-card/60 overflow-hidden">
                    {/* Mode header */}
                    <div className="flex items-center gap-3 px-4 py-3 border-b border-border/60">
                        <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                            {interviewMode === "online"
                                ? <Video className="h-4 w-4 text-primary" />
                                : <MapPin className="h-4 w-4 text-primary" />
                            }
                        </div>
                        <div>
                            <p className="text-sm font-semibold capitalize">{interviewMode} Interview</p>
                        </div>
                    </div>

                    {/* Physical: show address */}
                    {interviewMode === "physical" && interviewAddress && (
                        <div className="px-4 py-3 space-y-2">
                            <p className="text-[11px] uppercase tracking-wide font-medium text-muted-foreground">Location</p>
                            <div className="flex items-start gap-2">
                                <MapPin className="h-4 w-4 text-muted-foreground mt-0.5 shrink-0" />
                                <p className="text-sm text-foreground/90 leading-snug">{interviewAddress}</p>
                            </div>
                            {mapLink && (
                                <Button variant="outline" size="sm" className="h-7 text-xs mt-1" asChild>
                                    <a href={mapLink} target="_blank" rel="noopener noreferrer">
                                        <ExternalLink className="h-3 w-3 mr-1.5" />Open in Maps
                                    </a>
                                </Button>
                            )}
                        </div>
                    )}

                    {/* Physical: no address yet */}
                    {interviewMode === "physical" && !interviewAddress && (
                        <div className="px-4 py-3">
                            <p className="text-xs text-muted-foreground">Location details will be shared after confirmation.</p>
                        </div>
                    )}

                    {/* Online: meeting link locked until accepted */}
                    {interviewMode === "online" && (
                        <div className="px-4 py-3 space-y-1.5">
                            <p className="text-[11px] uppercase tracking-wide font-medium text-muted-foreground">Meeting link</p>
                            {meetingLink ? (
                                <div className="flex gap-2">
                                    <Input value={meetingLink} readOnly className="flex-1 h-8 text-xs" />
                                    <Button size="sm" variant="outline" className="h-8 w-8 p-0 shrink-0"
                                        onClick={() => { navigator.clipboard.writeText(meetingLink); toast.success("Copied!"); }}>
                                        <Copy className="h-3.5 w-3.5" />
                                    </Button>
                                    <Button size="sm" className="h-8 shrink-0" asChild>
                                        <a href={meetingLink} target="_blank" rel="noopener noreferrer">
                                            <ExternalLink className="h-3.5 w-3.5 mr-1" />Join
                                        </a>
                                    </Button>
                                </div>
                            ) : (
                                <div className="flex items-center gap-2 rounded-lg border border-dashed border-border bg-muted/30 px-3 py-2">
                                    <Lock className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                                    <p className="text-xs text-muted-foreground">Meeting link will be visible after you accept the interview.</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Time slot selection */}
            {slots.length === 0 ? (
                <div className="rounded-xl border border-amber-200 bg-amber-50/60 dark:bg-amber-950/20 dark:border-amber-800 px-4 py-3 text-sm text-amber-800 dark:text-amber-200 text-center">
                    No time slots available. Please contact the employer.
                </div>
            ) : (
                <div className="space-y-2">
                    <p className="text-xs uppercase tracking-wide font-medium text-muted-foreground">Select a time slot</p>
                    <div className="grid gap-2">
                        {slots.map((slot, i) => {
                            const sel = selectedSlot?.date === slot.date && selectedSlot?.time === slot.time;
                            return (
                                <button
                                    key={i}
                                    onClick={() => setSelectedSlot(slot)}
                                    className={cn(
                                        "relative w-full rounded-xl border-2 px-4 py-3 text-left transition-all duration-150",
                                        sel
                                            ? "border-primary bg-primary/6 shadow-sm"
                                            : "border-border hover:border-border/80 hover:bg-muted/40",
                                    )}
                                >
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <Calendar className="h-4 w-4 text-muted-foreground shrink-0" />
                                            <div>
                                                <p className="text-sm font-semibold">
                                                    {formatUTCDate(slot.date, "EEEE, MMM d, yyyy")}
                                                </p>
                                                {slot.time && (
                                                    <p className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1">
                                                        <Clock className="h-3 w-3" />
                                                        {formatUTCTime(slot.date, slot.time)}
                                                    </p>
                                                )}
                                            </div>
                                        </div>
                                        <div className={cn(
                                            "w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all shrink-0",
                                            sel ? "border-primary bg-primary" : "border-border",
                                        )}>
                                            {sel && <Check className="h-3 w-3 text-primary-foreground" />}
                                        </div>
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Actions */}
            <div className="flex gap-2 pt-1">
                <Button
                    className="flex-1 h-9"
                    onClick={handleAccept}
                    disabled={!selectedSlot || isSubmitting}
                >
                    {isSubmitting
                        ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />Processing…</>
                        : <><Check className="h-3.5 w-3.5 mr-1.5" />Accept Interview</>
                    }
                </Button>
                <Button
                    variant="outline"
                    className="h-9 border-red-200 text-red-600 hover:bg-red-50 dark:hover:bg-red-950/20 dark:border-red-800 dark:text-red-400"
                    onClick={handleDecline}
                    disabled={isSubmitting}
                >
                    <X className="h-3.5 w-3.5 mr-1.5" />Decline
                </Button>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useTheme } from "next-themes";
import { LogOut, Moon, Settings, Sun, User } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";

interface UserMenuProps {
    user: {
        firstName: string;
        lastName: string;
        email: string;
        profileImage?: string;
        membershipNo?: string;
    };
}

export function UserMenu({ user }: UserMenuProps) {
    const [mounted, setMounted] = useState(false);
    const [isLoggingOut, setIsLoggingOut] = useState(false);
    const { theme, setTheme } = useTheme();
    const router = useRouter();

    const initials = `${user.firstName?.[0] || ''}${user.lastName?.[0] || ''}`.toUpperCase() || 'U';
    const fullName = `${user.firstName || ''} ${user.lastName || ''}`.trim() || 'User';

    // Only render after mounting to avoid hydration mismatch
    useEffect(() => {
        setMounted(true);
    }, []);

    const handleLogout = async () => {
        try {
            setIsLoggingOut(true);
            const response = await fetch('/api/auth/logout', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
            });

            const data = await response.json();

            if (data.success && data.redirectTo) {
                router.push(data.redirectTo);
                router.refresh();
            } else {
                // Fallback redirect
                router.push('/login');
                router.refresh();
            }
        } catch (error) {
            console.error('Logout error:', error);
            // Fallback redirect on error
            router.push('/login');
            router.refresh();
        } finally {
            setIsLoggingOut(false);
        }
    };

    // Show avatar placeholder during SSR
    if (!mounted) {
        return (
            <div className="h-10 w-10 rounded-full bg-muted animate-pulse" />
        );
    }

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" className="relative h-10 w-10 rounded-full">
                    <Avatar className="h-10 w-10 border-2 border-border hover:border-primary transition-colors cursor-pointer">
                        <AvatarImage src={user.profileImage} alt={fullName} />
                        <AvatarFallback className="bg-primary/10 text-primary font-semibold">
                            {initials}
                        </AvatarFallback>
                    </Avatar>
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-56" align="end" forceMount>
                <DropdownMenuLabel className="font-normal">
                    <div className="flex flex-col space-y-1">
                        <p className="text-sm font-medium leading-none">{fullName}</p>
                        <p className="text-xs leading-none text-muted-foreground">
                            {user.email}
                        </p>
                        {user.membershipNo && (
                            <p className="text-xs leading-none font-mono mt-1 text-green-500 font-bold">
                                Membership No: {user.membershipNo}
                            </p>
                        )}
                    </div>
                </DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                    <DropdownMenuItem asChild>
                        <Link href="/candidate/profile" className="cursor-pointer">
                            <User className="mr-2 h-4 w-4" />
                            <span>Profile</span>
                        </Link>
                    </DropdownMenuItem>
                    <DropdownMenuItem asChild>
                        <Link href="/candidate/settings" className="cursor-pointer">
                            <Settings className="mr-2 h-4 w-4" />
                            <span>Settings</span>
                        </Link>
                    </DropdownMenuItem>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>
                    <DropdownMenuItem
                        onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
                        className="cursor-pointer"
                    >
                        {theme === "dark" ? (
                            <>
                                <Sun className="mr-2 h-4 w-4" />
                                <span>Light Mode</span>
                            </>
                        ) : (
                            <>
                                <Moon className="mr-2 h-4 w-4" />
                                <span>Dark Mode</span>
                            </>
                        )}
                    </DropdownMenuItem>
                </DropdownMenuGroup>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                    onClick={handleLogout}
                    className="cursor-pointer text-destructive focus:text-destructive"
                >
                    <LogOut className="mr-2 h-4 w-4" />
                    <span>Log out</span>
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

"use client";

import { useState, useMemo } from "react";
import {
    format, parseISO, isSameDay, isSameMonth,
    startOfMonth, endOfMonth, startOfWeek, endOfWeek,
    addDays, addMonths, subMonths, isToday,
} from "date-fns";
import {
    ChevronLeft, ChevronRight,
    Video, MapPin, X, Calendar, Clock,
    Building2, CheckCircle2, Clock4, ExternalLink, Ban,
} from "lucide-react";
import { cn } from "@/lib/utils";
import Link from "next/link";
import type { InterviewEvent } from "@/app/actions/candidate-dashboard-data";

interface Props { events: InterviewEvent[]; }

function formatTime(rawTime: string): string {
    if (!rawTime) return "";
    const m = rawTime.match(/^(\d{1,2}):(\d{2})/);
    if (!m) return rawTime;
    let h = parseInt(m[1], 10);
    const mins = m[2];
    const ap = h >= 12 ? "PM" : "AM";
    h = h % 12 || 12;
    return `${h}:${mins} ${ap}`;
}

/** Build array of Date objects for the 6-week grid covering the given month */
function buildCalendarGrid(month: Date): Date[] {
    const start = startOfWeek(startOfMonth(month), { weekStartsOn: 0 });
    const end = endOfWeek(endOfMonth(month), { weekStartsOn: 0 });
    const days: Date[] = [];
    let cur = start;
    while (cur <= end) {
        days.push(cur);
        cur = addDays(cur, 1);
    }
    return days;
}

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

export function InterviewCalendarWidget({ events }: Props) {
    const [currentMonth, setCurrentMonth] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);
    const [modalOpen, setModalOpen] = useState(false);

    // Build event lookup map
    const eventsByDate = useMemo(() => {
        const map = new Map<string, InterviewEvent[]>();
        for (const ev of events) {
            if (!map.has(ev.date)) map.set(ev.date, []);
            map.get(ev.date)!.push(ev);
        }
        return map;
    }, [events]);

    const calendarDays = useMemo(() => buildCalendarGrid(currentMonth), [currentMonth]);

    const selectedDayEvents = useMemo(() => {
        if (!selectedDate) return [];
        return eventsByDate.get(format(selectedDate, "yyyy-MM-dd")) ?? [];
    }, [selectedDate, eventsByDate]);

    function openDay(day: Date) {
        setSelectedDate(day);
        setModalOpen(true);
    }

    return (
        <>
            <div className="rounded-2xl border border-border bg-card shadow-sm overflow-hidden">
                {/* ── Header ──────────────────────────────────────── */}
                <div className="px-5 pt-5 pb-3 border-b border-border flex items-center justify-between">
                    <div>
                        <h3 className="text-sm font-semibold text-foreground">Interview Calendar</h3>
                        <p className="text-xs text-muted-foreground mt-0.5">
                            {events.length === 0
                                ? "No interviews scheduled"
                                : `${events.length} interview${events.length === 1 ? "" : "s"} on calendar`}
                        </p>
                    </div>
                    {events.length > 0 && (
                        <div className="flex flex-col gap-1 text-[11px] text-muted-foreground items-end">
                            <span className="flex items-center gap-1.5">
                                <span className="h-2 w-2 rounded-full bg-primary inline-block" /> Confirmed
                            </span>
                            <span className="flex items-center gap-1.5">
                                <span className="h-2 w-2 rounded-full bg-primary/40 inline-block" /> Pending
                            </span>
                        </div>
                    )}
                </div>

                {/* ── Month nav ───────────────────────────────────── */}
                <div className="px-5 pt-4 pb-2 flex items-center justify-between">
                    <button
                        onClick={() => setCurrentMonth(subMonths(currentMonth, 1))}
                        className="h-7 w-7 flex items-center justify-center rounded-lg hover:bg-muted/60 transition-colors text-foreground"
                        aria-label="Previous month"
                    >
                        <ChevronLeft className="h-4 w-4" />
                    </button>
                    <span className="text-sm font-semibold text-foreground">
                        {format(currentMonth, "MMMM yyyy")}
                    </span>
                    <button
                        onClick={() => setCurrentMonth(addMonths(currentMonth, 1))}
                        className="h-7 w-7 flex items-center justify-center rounded-lg hover:bg-muted/60 transition-colors text-foreground"
                        aria-label="Next month"
                    >
                        <ChevronRight className="h-4 w-4" />
                    </button>
                </div>

                {/* ── Calendar grid ───────────────────────────────── */}
                <div className="px-4 pb-3">
                    {/* Weekday headers */}
                    <div className="grid grid-cols-7 mb-1">
                        {WEEKDAYS.map((d) => (
                            <div key={d} className="flex items-center justify-center text-[11px] font-medium text-muted-foreground py-1">
                                {d}
                            </div>
                        ))}
                    </div>

                    {/* Day cells */}
                    <div className="grid grid-cols-7 gap-y-0.5">
                        {calendarDays.map((day) => {
                            const key = format(day, "yyyy-MM-dd");
                            const dayEvts = eventsByDate.get(key) ?? [];
                            const hasEvt = dayEvts.length > 0;
                            const hasConfirmed = dayEvts.some((e) => e.is_confirmed && !e.is_canceled);
                            const allCanceled = hasEvt && dayEvts.every((e) => e.is_canceled);
                            const isCurrentMonth = isSameMonth(day, currentMonth);
                            const isTodayDay = isToday(day);
                            const isSelected = selectedDate ? isSameDay(day, selectedDate) : false;

                            const dotClass = isSelected
                                ? "bg-primary-foreground"
                                : allCanceled
                                    ? "bg-muted-foreground/40"
                                    : hasConfirmed
                                        ? "bg-primary"
                                        : "bg-primary/50";

                            return (
                                <button
                                    key={key}
                                    type="button"
                                    onClick={() => openDay(day)}
                                    className={cn(
                                        "relative flex flex-col items-center justify-center h-9 w-full rounded-lg",
                                        "text-[13px] transition-colors select-none outline-none",
                                        // Outside current month
                                        !isCurrentMonth && "opacity-30",
                                        // Today ring
                                        isTodayDay && !isSelected && "font-bold text-primary ring-1 ring-primary/40",
                                        // Selected
                                        isSelected && "bg-primary text-primary-foreground font-semibold",
                                        // Has event — bolder
                                        hasEvt && !isSelected && "font-semibold",
                                        // Default text
                                        !isSelected && !isTodayDay && "text-foreground/85",
                                        // Hover
                                        !isSelected && "hover:bg-muted/60",
                                        isSelected && "hover:bg-primary/90",
                                    )}
                                >
                                    <span className="leading-none">{format(day, "d")}</span>
                                    {hasEvt && (
                                        <span
                                            className={cn(
                                                "absolute bottom-[3px] h-[5px] w-[5px] rounded-full",
                                                dotClass
                                            )}
                                        />
                                    )}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* ── Legend ──────────────────────────────────────── */}
                <div className="px-5 pb-4 text-[11px] text-muted-foreground">
                    Click any day to see interview details.
                </div>
            </div>

            {/* ── Modal ───────────────────────────────────────────── */}
            {modalOpen && selectedDate && (
                <>
                    <div
                        className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm"
                        onClick={() => setModalOpen(false)}
                    />
                    <div className="fixed left-1/2 top-1/2 z-50 w-full max-w-sm -translate-x-1/2 -translate-y-1/2 px-4 animate-in fade-in zoom-in-95 duration-150">
                        <div className="rounded-2xl border border-border bg-card shadow-2xl overflow-hidden">
                            {/* Modal header */}
                            <div className="flex items-center justify-between px-5 py-4 border-b border-border">
                                <div>
                                    <p className="text-[11px] uppercase tracking-wide text-muted-foreground font-medium">
                                        {format(selectedDate, "EEEE")}
                                    </p>
                                    <h3 className="text-sm font-bold text-foreground">
                                        {format(selectedDate, "MMMM d, yyyy")}
                                    </h3>
                                </div>
                                <button
                                    onClick={() => setModalOpen(false)}
                                    className="flex h-7 w-7 items-center justify-center rounded-lg hover:bg-muted/50 transition-colors"
                                >
                                    <X className="h-4 w-4 text-muted-foreground" />
                                </button>
                            </div>

                            {/* Body */}
                            {selectedDayEvents.length === 0 ? (
                                <div className="px-5 py-8 flex flex-col items-center text-center gap-2">
                                    <div className="h-10 w-10 rounded-xl bg-muted/50 flex items-center justify-center">
                                        <Calendar className="h-5 w-5 text-muted-foreground" />
                                    </div>
                                    <p className="text-sm font-semibold text-foreground mt-1">No interview scheduled</p>
                                    <p className="text-xs text-muted-foreground">
                                        There are no interviews scheduled for this day.
                                    </p>
                                    <Link
                                        href="/candidate/invitations"
                                        className="mt-1 text-xs font-semibold text-primary hover:underline"
                                        onClick={() => setModalOpen(false)}
                                    >
                                        View all invitations →
                                    </Link>
                                </div>
                            ) : (
                                <div className="divide-y divide-border/50 max-h-80 overflow-y-auto">
                                    {selectedDayEvents.map((ev) => (
                                        <div key={ev.id} className="px-5 py-4">
                                            <div className="flex items-center justify-between mb-2.5 flex-wrap gap-1">
                                                {ev.is_canceled ? (
                                                    <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400">
                                                        <Ban className="h-2.5 w-2.5" /> Canceled
                                                    </span>
                                                ) : ev.is_confirmed ? (
                                                    <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-primary/10 text-primary">
                                                        <CheckCircle2 className="h-2.5 w-2.5" /> Confirmed
                                                    </span>
                                                ) : (
                                                    <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400">
                                                        <Clock4 className="h-2.5 w-2.5" /> Awaiting Confirmation
                                                    </span>
                                                )}
                                                {ev.interview_mode && (
                                                    <span className="inline-flex items-center gap-1 rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
                                                        {ev.interview_mode === "online"
                                                            ? <Video className="h-2.5 w-2.5" />
                                                            : <MapPin className="h-2.5 w-2.5" />}
                                                        {ev.interview_mode === "online" ? "Online" : "In-Person"}
                                                    </span>
                                                )}
                                            </div>

                                            <p className={cn(
                                                "text-sm font-semibold leading-snug",
                                                ev.is_canceled ? "text-muted-foreground line-through" : "text-foreground"
                                            )}>
                                                {ev.job_designation}
                                            </p>

                                            {ev.company_name && (
                                                <p className="flex items-center gap-1.5 text-xs text-muted-foreground mt-0.5">
                                                    <Building2 className="h-3 w-3 flex-shrink-0" />
                                                    {ev.company_name}
                                                </p>
                                            )}

                                            {ev.time && (
                                                <p className="flex items-center gap-1.5 text-xs text-muted-foreground mt-1">
                                                    <Clock className="h-3 w-3 flex-shrink-0" />
                                                    {formatTime(ev.time)}
                                                </p>
                                            )}

                                            <Link
                                                href={`/candidate/invitations/${ev.invitation_id}`}
                                                className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline"
                                                onClick={() => setModalOpen(false)}
                                            >
                                                View full details <ExternalLink className="h-3 w-3" />
                                            </Link>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <div className="px-5 py-3 border-t border-border bg-muted/20">
                                <Link
                                    href="/candidate/invitations"
                                    className="text-xs text-muted-foreground hover:text-primary transition-colors"
                                    onClick={() => setModalOpen(false)}
                                >
                                    View all invitations →
                                </Link>
                            </div>
                        </div>
                    </div>
                </>
            )}
        </>
    );
}

"use client";

import Image from "next/image";
import Link from "next/link";
import {
    User,
    MapPin,
    Briefcase,
    Clock,
    BadgeCheck,
    Award,
    ChevronRight,
    Building2,
} from "lucide-react";
import { cn, formatIndustry } from "@/lib/utils";
import type { CandidateDashboardData } from "@/app/actions/candidate-dashboard-data";

interface ProfileHeroWidgetProps {
    data: CandidateDashboardData;
}

const availabilityColors: Record<string, string> = {
    available: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800",
    not_available: "bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400 border-rose-200 dark:border-rose-800",
    open_to_opportunities: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border-blue-200 dark:border-blue-800",
};

const availabilityLabels: Record<string, string> = {
    available: "Available Now",
    not_available: "Not Available",
    open_to_opportunities: "Open to Opportunities",
};

const approvalColors: Record<string, string> = {
    approved: "bg-emerald-500 text-white",
    pending: "bg-amber-500 text-white",
    rejected: "bg-rose-500 text-white",
};

// Circular progress SVG component
function CircularProgress({ percent }: { percent: number }) {
    const radius = 42;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (percent / 100) * circumference;

    const getColor = () => {
        if (percent >= 80) return "#10b981"; // emerald
        if (percent >= 50) return "#3b82f6"; // blue
        return "#f59e0b"; // amber
    };

    return (
        <div className="relative flex h-28 w-28 items-center justify-center">
            <svg className="absolute h-28 w-28 -rotate-90" viewBox="0 0 100 100">
                <circle
                    className="text-muted/40"
                    stroke="currentColor"
                    strokeWidth="8"
                    fill="none"
                    cx="50"
                    cy="50"
                    r={radius}
                />
                <circle
                    stroke={getColor()}
                    strokeWidth="8"
                    strokeLinecap="round"
                    fill="none"
                    cx="50"
                    cy="50"
                    r={radius}
                    strokeDasharray={circumference}
                    strokeDashoffset={offset}
                    style={{ transition: "stroke-dashoffset 0.8s ease" }}
                />
            </svg>
            <div className="flex flex-col items-center">
                <span className="text-2xl font-bold tabular-nums">{percent}%</span>
                <span className="text-[10px] text-muted-foreground font-medium">Complete</span>
            </div>
        </div>
    );
}

export function ProfileHeroWidget({ data }: ProfileHeroWidgetProps) {
    const {
        firstName, lastName, currentPosition, industry, country,
        yearsOfExperience, experienceLevel, availabilityStatus,
        approvalStatus, membershipNo, profileImageUrl,
        profileCompletionPercent, profileCompletionItems,
        expectedMonthlySalary,
    } = data;

    const initials = `${firstName?.[0] || ""}${lastName?.[0] || ""}`.toUpperCase();
    const availKey = availabilityStatus || "not_available";
    const availColor = availabilityColors[availKey] || availabilityColors.not_available;
    const availLabel = availabilityLabels[availKey] || availabilityStatus;

    const expLabel = experienceLevel
        ? experienceLevel.replace(/_/g, " ").replace(/\b\w/g, l => l.toUpperCase())
        : null;

    const incompleteItems = profileCompletionItems
        .filter(i => !i.done)
        .slice(0, 3);

    return (
        <div className="rounded-2xl border border-border bg-card shadow-sm overflow-hidden">
            {/* Header gradient band */}
            <div className="h-24 bg-gradient-to-r from-primary/80 via-primary/60 to-blue-600/40 relative">
                <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-white/10 via-transparent to-transparent" />
                {approvalStatus && (
                    <div className="absolute top-3 right-4">
                        <span className={cn(
                            "inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold capitalize",
                            approvalColors[approvalStatus] || "bg-muted text-muted-foreground"
                        )}>
                            <BadgeCheck className="h-3 w-3" />
                            {approvalStatus}
                        </span>
                    </div>
                )}
            </div>

            <div className="px-6 pb-6">
                {/* Avatar row */}
                <div className="flex items-end gap-4 -mt-12 mb-4">
                    <div className="relative flex-shrink-0">
                        <div className="h-20 w-20 rounded-2xl ring-4 ring-card overflow-hidden bg-muted flex items-center justify-center shadow-md">
                            {profileImageUrl ? (
                                <Image
                                    src={profileImageUrl}
                                    alt={`${firstName} ${lastName}`}
                                    width={80}
                                    height={80}
                                    className="h-full w-full object-cover"
                                />
                            ) : (
                                <span className="text-2xl font-bold text-muted-foreground">{initials}</span>
                            )}
                        </div>
                        {availabilityStatus === 'available' && (
                            <span className="absolute -bottom-1 -right-1 h-4 w-4 rounded-full bg-emerald-500 ring-2 ring-card" />
                        )}
                    </div>

                    <div className="flex-1 pb-1">
                        <h2 className="text-xl font-bold text-foreground leading-tight">
                            {firstName} {lastName}
                        </h2>
                        {currentPosition && (
                            <p className="text-sm text-muted-foreground">{currentPosition}</p>
                        )}
                    </div>
                </div>

                {/* Info chips row */}
                <div className="flex flex-wrap gap-2 mb-5">
                    {availabilityStatus && (
                        <span className={cn("inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-medium", availColor)}>
                            <span className="h-1.5 w-1.5 rounded-full bg-current" />
                            {availLabel}
                        </span>
                    )}
                    {industry && (
                        <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground">
                            <Building2 className="h-3 w-3" />
                            {formatIndustry(industry)}
                        </span>
                    )}
                    {country && (
                        <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground">
                            <MapPin className="h-3 w-3" />
                            {country}
                        </span>
                    )}
                    {yearsOfExperience !== null && yearsOfExperience !== undefined && (
                        <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground">
                            <Briefcase className="h-3 w-3" />
                            {yearsOfExperience} yr{yearsOfExperience !== 1 ? "s" : ""} experience
                        </span>
                    )}
                    {expLabel && (
                        <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground">
                            <Award className="h-3 w-3" />
                            {expLabel}
                        </span>
                    )}
                    {membershipNo && (
                        <span className="inline-flex items-center gap-1.5 rounded-full border border-primary/30 bg-primary/5 px-3 py-1 text-xs font-semibold text-primary">
                            <BadgeCheck className="h-3 w-3" />
                            Member #{membershipNo}
                        </span>
                    )}
                </div>

                {/* Divider */}
                <div className="h-px bg-border mb-5" />

                {/* Profile completion + salary row */}
                <div className="flex items-start gap-6">
                    {/* Circular progress */}
                    <div className="flex-shrink-0 flex flex-col items-center gap-1">
                        <CircularProgress percent={profileCompletionPercent} />
                        <span className="text-xs text-muted-foreground font-medium">Profile Strength</span>
                    </div>

                    {/* Completion checklist + salary */}
                    <div className="flex-1 space-y-3">
                        {expectedMonthlySalary !== null && expectedMonthlySalary !== undefined && (
                            <div className="rounded-xl bg-muted/50 border border-border px-4 py-3">
                                <p className="text-xs text-muted-foreground mb-0.5">Expected Monthly Salary</p>
                                <p className="text-xl font-bold text-foreground">
                                    LKR {Number(expectedMonthlySalary).toLocaleString()}
                                </p>
                            </div>
                        )}

                        {incompleteItems.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold text-muted-foreground mb-2 uppercase tracking-wide">
                                    Complete your profile
                                </p>
                                <div className="space-y-1.5">
                                    {incompleteItems.map((item) => (
                                        <div key={item.label} className="flex items-center gap-2">
                                            <span className="h-1.5 w-1.5 rounded-full bg-amber-400 flex-shrink-0" />
                                            <span className="text-xs text-muted-foreground">{item.label}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        <Link
                            href="/candidate/profile"
                            className="inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline mt-2"
                        >
                            {incompleteItems.length > 0 ? "Complete Profile" : "View Profile"}
                            <ChevronRight className="h-3.5 w-3.5" />
                        </Link>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { CandidateProfile } from "@/types/profile-types";
import { FileText, DollarSign, Clock, Briefcase, TrendingUp, Pencil, GraduationCap } from "lucide-react";
import { AboutDialog } from "./dialogs/AboutDialog";

interface AboutSectionProps {
    profile: CandidateProfile;
}

export function AboutSection({ profile }: AboutSectionProps) {
    const [dialogOpen, setDialogOpen] = useState(false);

    if (!profile.professional_summary &&
        !profile.years_of_experience &&
        !profile.expected_monthly_salary &&
        !profile.notice_period &&
        !profile.employment_type) {
        return (
            <>
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between">
                        <CardTitle className="flex items-center gap-2">
                            <FileText className="h-5 w-5" />
                            About
                        </CardTitle>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setDialogOpen(true)}
                        >
                            <Pencil className="h-4 w-4 mr-2" />
                            Add Information
                        </Button>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-muted-foreground text-center py-8">
                            No about information added yet. Click "Add Information" to get started.
                        </p>
                    </CardContent>
                </Card>

                <AboutDialog
                    open={dialogOpen}
                    onOpenChange={setDialogOpen}
                    profile={profile}
                />
            </>
        );
    }

    const formatEmploymentType = (type: string | null) => {
        if (!type) return null;
        return type.split("_").map(word =>
            word.charAt(0).toUpperCase() + word.slice(1)
        ).join(" ");
    };

    const formatExperienceLevel = (level: string | null) => {
        if (!level) return null;
        return level.charAt(0).toUpperCase() + level.slice(1);
    };

    return (
        <>
            <Card className="group relative">
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                        <FileText className="h-5 w-5" />
                        About
                    </CardTitle>
                    {/* Edit Button - visible on hover on desktop, always visible on mobile */}
                    <div className="md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8"
                            onClick={() => setDialogOpen(true)}
                        >
                            <Pencil className="h-4 w-4" />
                        </Button>
                    </div>
                </CardHeader>
                <CardContent className="space-y-4">
                    {profile.professional_summary && (
                        <p className="text-muted-foreground text-justify leading-relaxed">
                            {profile.professional_summary}
                        </p>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 py-2 gap-4">
                        {profile.highest_qualification && (
                            <div className="flex items-start gap-3">
                                <div className="p-2 rounded-lg bg-primary/10">
                                    <GraduationCap className="h-4 w-4 text-primary" />
                                </div>
                                <div>
                                    <p className="text-sm font-medium">Highest Qualification</p>
                                    <p className="text-sm text-muted-foreground capitalize">
                                        {profile.highest_qualification.replace(/_/g, ' ')}
                                    </p>
                                </div>
                            </div>
                        )}

                        {profile.years_of_experience !== null && (
                            <div className="flex items-start gap-3">
                                <div className="p-2 rounded-lg bg-primary/10">
                                    <TrendingUp className="h-4 w-4 text-primary" />
                                </div>
                                <div>
                                    <p className="text-sm font-medium">Experience</p>
                                    <p className="text-sm text-muted-foreground">
                                        {profile.years_of_experience} years
                                        {profile.experience_level && (
                                            <Badge variant="secondary" className="ml-2">
                                                {formatExperienceLevel(profile.experience_level)}
                                            </Badge>
                                        )}
                                    </p>
                                </div>
                            </div>
                        )}

                        {profile.expected_monthly_salary && (
                            <div className="flex items-start gap-3">
                                <div className="p-2 rounded-lg bg-primary/10">
                                    <DollarSign className="h-4 w-4 text-primary" />
                                </div>
                                <div>
                                    <p className="text-sm font-medium">Expected Salary</p>
                                    <p className="text-sm text-muted-foreground">
                                        LKR {profile.expected_monthly_salary.toLocaleString()}/month
                                    </p>
                                </div>
                            </div>
                        )}

                        {profile.notice_period && (
                            <div className="flex items-start gap-3">
                                <div className="p-2 rounded-lg bg-primary/10">
                                    <Clock className="h-4 w-4 text-primary" />
                                </div>
                                <div>
                                    <p className="text-sm font-medium">Notice Period</p>
                                    <p className="text-sm text-muted-foreground capitalize">
                                        {profile.notice_period}
                                    </p>
                                </div>
                            </div>
                        )}

                        {profile.employment_type && (
                            <div className="flex items-start gap-3">
                                <div className="p-2 rounded-lg bg-primary/10">
                                    <Briefcase className="h-4 w-4 text-primary" />
                                </div>
                                <div>
                                    <p className="text-sm font-medium">Employment Type</p>
                                    <p className="text-sm text-muted-foreground">
                                        {formatEmploymentType(profile.employment_type)}
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>
                </CardContent>
            </Card>

            {/* Edit Dialog */}
            <AboutDialog
                open={dialogOpen}
                onOpenChange={setDialogOpen}
                profile={profile}
            />
        </>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Award } from "@/types/profile-types";
import { Trophy, Pencil, Trash2, Plus } from "lucide-react";
import { AwardDialog } from "./dialogs/AwardDialog";
import { DeleteConfirmDialog } from "./dialogs/DeleteConfirmDialog";
import { deleteAward } from "@/app/actions/profile-mutations";
import { useToast } from "@/hooks/use-toast";

interface AwardsSectionProps {
    awards: Award[];
}

export function AwardsSection({ awards }: AwardsSectionProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [showAll, setShowAll] = useState(false);
    const [expandedDescriptions, setExpandedDescriptions] = useState<Record<string, boolean>>({});

    // Dialog states
    const [dialogOpen, setDialogOpen] = useState(false);
    const [selectedAward, setSelectedAward] = useState<Award | null>(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [awardToDelete, setAwardToDelete] = useState<string | null>(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const sortedAwards = [...(awards || [])].reverse();
    const displayedAwards = showAll ? sortedAwards : sortedAwards.slice(0, 3);
    const hasMore = sortedAwards && sortedAwards.length > 3;
    const isEmpty = !sortedAwards || sortedAwards.length === 0;

    const toggleDescription = (id: string) => {
        setExpandedDescriptions(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const handleEdit = (award: Award) => {
        setSelectedAward(award);
        setDialogOpen(true);
    };

    const handleDeleteClick = (id: string) => {
        setAwardToDelete(id);
        setDeleteDialogOpen(true);
    };

    const handleDeleteConfirm = async () => {
        if (!awardToDelete) return;

        setIsDeleting(true);
        try {
            const result = await deleteAward(awardToDelete);

            if (result.success) {
                toast({
                    title: "Success",
                    description: "Award deleted successfully",
                });
                setDeleteDialogOpen(false);
                setAwardToDelete(null);
                router.refresh();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Failed to delete award",
                    variant: "destructive",
                });
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsDeleting(false);
        }
    };

    return (
        <>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                        <Trophy className="h-5 w-5" />
                        Awards & Achievements
                    </CardTitle>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                            setSelectedAward(null);
                            setDialogOpen(true);
                        }}
                    >
                        <Plus className="h-4 w-4 mr-2" />
                        Add Award
                    </Button>
                </CardHeader>
                <CardContent>
                    {isEmpty ? (
                        <p className="text-sm text-muted-foreground text-center py-8">
                            No awards added yet. Click "Add Award" to get started.
                        </p>
                    ) : (
                        <>
                            <div className="space-y-6">
                                {displayedAwards.map((award, index) => (
                                    <div key={award.id}>
                                        {index > 0 && <Separator className="my-6" />}
                                        <div className="group relative flex gap-4">
                                            {/* Icon - hidden on mobile */}
                                            <div className="flex-shrink-0 hidden md:flex">
                                                <div className="h-12 w-12 rounded-lg bg-amber-500/10 flex items-center justify-center">
                                                    <Trophy className="h-6 w-6 text-amber-600 dark:text-amber-500" />
                                                </div>
                                            </div>

                                            {/* Edit/Delete buttons - Always visible on mobile, hover on desktop */}
                                            <div className="absolute -right-2 -top-2 flex gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-8 w-8"
                                                    onClick={() => handleEdit(award)}
                                                >
                                                    <Pencil className="h-4 w-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-8 w-8 text-destructive hover:text-destructive"
                                                    onClick={() => handleDeleteClick(award.id)}
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>

                                            <div className="flex-1 min-w-0 pr-16 md:pr-0">
                                                <h3 className="font-semibold text-lg">
                                                    {award.nature_of_award || "Award"}
                                                </h3>
                                                {award.offered_by && (
                                                    <p className="text-sm text-muted-foreground mt-1">
                                                        {award.offered_by}
                                                    </p>
                                                )}
                                                {award.description && (
                                                    <div className="mt-2">
                                                        <p
                                                            className={`text-sm text-muted-foreground leading-relaxed ${!expandedDescriptions[award.id] ? 'line-clamp-2' : ''
                                                                }`}
                                                        >
                                                            {award.description}
                                                        </p>
                                                        <Button
                                                            variant="link"
                                                            size="sm"
                                                            onClick={() => toggleDescription(award.id)}
                                                            className="px-0 h-auto mt-1 text-xs"
                                                        >
                                                            {expandedDescriptions[award.id] ? "Read Less" : "Read More"}
                                                        </Button>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* View All Button */}
                            {hasMore && (
                                <div className="mt-6 text-center">
                                    <Button
                                        variant="outline"
                                        onClick={() => setShowAll(!showAll)}
                                        className="w-full md:w-auto"
                                    >
                                        {showAll ? "Show Less" : `View All Awards (${awards.length})`}
                                    </Button>
                                </div>
                            )}
                        </>
                    )}
                </CardContent>
            </Card>

            {/* Dialogs */}
            <AwardDialog
                open={dialogOpen}
                onOpenChange={setDialogOpen}
                award={selectedAward}
            />

            <DeleteConfirmDialog
                open={deleteDialogOpen}
                onOpenChange={setDeleteDialogOpen}
                onConfirm={handleDeleteConfirm}
                title="Delete Award"
                description="Are you sure you want to delete this award? This action cannot be undone."
                isLoading={isDeleting}
            />
        </>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Certificate } from "@/types/profile-types";
import { Award, Calendar, ExternalLink, Hash, Pencil, Trash2, Plus } from "lucide-react";
import { CertificationDialog } from "./dialogs/CertificationDialog";
import { DeleteConfirmDialog } from "./dialogs/DeleteConfirmDialog";
import { deleteCertification } from "@/app/actions/profile-mutations";
import { useToast } from "@/hooks/use-toast";
import { formatUTCDate } from "@/lib/date-utils";

interface CertificationsSectionProps {
    certificates: Certificate[];
}

export function CertificationsSection({ certificates }: CertificationsSectionProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [showAll, setShowAll] = useState(false);
    const [expandedDescriptions, setExpandedDescriptions] = useState<Record<string, boolean>>({});

    // Dialog states
    const [dialogOpen, setDialogOpen] = useState(false);
    const [selectedCertification, setSelectedCertification] = useState<Certificate | null>(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [certToDelete, setCertToDelete] = useState<string | null>(null);
    const [isDeleting, setIsDeleting] = useState(false);

    if (!certificates || certificates.length === 0) {
        return (
            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                        <Award className="h-5 w-5" />
                        Certifications
                    </CardTitle>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                            setSelectedCertification(null);
                            setDialogOpen(true);
                        }}
                    >
                        <Plus className="h-4 w-4 mr-2" />
                        Add Certification
                    </Button>
                </CardHeader>
                <CardContent>
                    <p className="text-sm text-muted-foreground text-center py-8">
                        No certifications added yet. Click "Add Certification" to get started.
                    </p>
                </CardContent>
            </Card>
        );
    }

    const formatDate = (dateString: string | null) => {
        if (!dateString) return null;
        return formatUTCDate(dateString, "MMM yyyy") || null;
    };

    const isExpired = (expiryDate: string | null) => {
        if (!expiryDate) return false;
        const ms = new Date(expiryDate).getTime();
        return Number.isFinite(ms) && ms < Date.now();
    };

    const toggleDescription = (id: string) => {
        setExpandedDescriptions(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const handleEdit = (cert: Certificate) => {
        setSelectedCertification(cert);
        setDialogOpen(true);
    };

    const handleDeleteClick = (id: string) => {
        setCertToDelete(id);
        setDeleteDialogOpen(true);
    };

    const handleDeleteConfirm = async () => {
        if (!certToDelete) return;

        setIsDeleting(true);
        try {
            const result = await deleteCertification(certToDelete);

            if (result.success) {
                toast({
                    title: "Success",
                    description: "Certification deleted successfully",
                });
                setDeleteDialogOpen(false);
                setCertToDelete(null);
                router.refresh();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Failed to delete certification",
                    variant: "destructive",
                });
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsDeleting(false);
        }
    };

    const sortedCertificates = [...(certificates || [])].sort((a, b) => {
        const dateA = a.issue_date ? new Date(a.issue_date).getTime() : 0;
        const dateB = b.issue_date ? new Date(b.issue_date).getTime() : 0;
        return dateB - dateA;
    });

    const displayedCertificates = showAll ? sortedCertificates : sortedCertificates.slice(0, 3);
    const hasMore = sortedCertificates.length > 3;

    return (
        <>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                        <Award className="h-5 w-5" />
                        Certifications
                    </CardTitle>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                            setSelectedCertification(null);
                            setDialogOpen(true);
                        }}
                    >
                        <Plus className="h-4 w-4 mr-2" />
                        Add Certification
                    </Button>
                </CardHeader>
                <CardContent>
                    <div className="space-y-6">
                        {displayedCertificates.map((cert, index) => (
                            <div key={cert.id}>
                                {index > 0 && <Separator className="my-6" />}
                                <div className="group relative flex gap-4">
                                    {/* Icon - hidden on mobile */}
                                    <div className="flex-shrink-0 hidden md:flex">
                                        <div className="h-12 w-12 rounded-lg bg-primary/10 flex items-center justify-center">
                                            <Award className="h-6 w-6 text-primary" />
                                        </div>
                                    </div>

                                    {/* Edit/Delete buttons - Always visible on mobile, hover on desktop */}
                                    <div className="absolute -right-2 -top-2 flex gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="h-8 w-8"
                                            onClick={() => handleEdit(cert)}
                                        >
                                            <Pencil className="h-4 w-4" />
                                        </Button>
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="h-8 w-8 text-destructive hover:text-destructive"
                                            onClick={() => handleDeleteClick(cert.id)}
                                        >
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </div>

                                    <div className="flex-1 min-w-0 space-y-2 pr-16 md:pr-0">
                                        <div>
                                            <h3 className="font-semibold text-lg">
                                                {cert.certificate_name || "Certification"}
                                            </h3>
                                            <p className="text-sm text-muted-foreground">
                                                {cert.issuing_authority || "Issuing Authority"}
                                            </p>
                                        </div>

                                        {/* Date Information */}
                                        <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
                                            {cert.issue_date && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar className="h-3.5 w-3.5" />
                                                    <span>Issued {formatDate(cert.issue_date)}</span>
                                                </div>
                                            )}
                                            {cert.expiry_date && (
                                                <Badge
                                                    variant={isExpired(cert.expiry_date) ? "destructive" : "secondary"}
                                                    className="text-xs"
                                                >
                                                    {isExpired(cert.expiry_date) ? "Expired" : "Expires"} {formatDate(cert.expiry_date)}
                                                </Badge>
                                            )}
                                        </div>

                                        {/* Credential Information */}
                                        {(cert.credential_id || cert.credential_url) && (
                                            <div className="flex flex-wrap items-center gap-3 pt-1">
                                                {cert.credential_id && (
                                                    <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                        <Hash className="h-3 w-3" />
                                                        <span className="font-mono">{cert.credential_id}</span>
                                                    </div>
                                                )}
                                                {cert.credential_url && (
                                                    <Button
                                                        variant="link"
                                                        size="sm"
                                                        className="h-auto p-0 text-xs"
                                                        asChild
                                                    >
                                                        <a
                                                            href={cert.credential_url}
                                                            target="_blank"
                                                            rel="noopener noreferrer"
                                                            className="flex items-center gap-1"
                                                        >
                                                            <ExternalLink className="h-3 w-3" />
                                                            View Credential
                                                        </a>
                                                    </Button>
                                                )}
                                            </div>
                                        )}

                                        {/* Description with Read More */}
                                        {cert.description && (
                                            <div className="pt-1">
                                                <p
                                                    className={`text-sm text-muted-foreground leading-relaxed ${!expandedDescriptions[cert.id] ? 'line-clamp-2' : ''
                                                        }`}
                                                >
                                                    {cert.description}
                                                </p>
                                                <Button
                                                    variant="link"
                                                    size="sm"
                                                    onClick={() => toggleDescription(cert.id)}
                                                    className="px-0 h-auto mt-1 text-xs"
                                                >
                                                    {expandedDescriptions[cert.id] ? "Read Less" : "Read More"}
                                                </Button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* View All Button */}
                    {hasMore && (
                        <div className="mt-6 text-center">
                            <Button
                                variant="outline"
                                onClick={() => setShowAll(!showAll)}
                                className="w-full md:w-auto"
                            >
                                {showAll ? "Show Less" : `View All Certifications (${certificates.length})`}
                            </Button>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Dialogs */}
            <CertificationDialog
                open={dialogOpen}
                onOpenChange={setDialogOpen}
                certification={selectedCertification}
            />

            <DeleteConfirmDialog
                open={deleteDialogOpen}
                onOpenChange={setDeleteDialogOpen}
                onConfirm={handleDeleteConfirm}
                title="Delete Certification"
                description="Are you sure you want to delete this certification? This action cannot be undone."
                isLoading={isDeleting}
            />
        </>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
    Education,
    FinanceAcademicEducation,
    FinanceProfessionalEducation,
    BankingAcademicEducation,
    BankingProfessionalEducation,
    BankingSpecializedTraining
} from "@/types/profile-types";
import { GraduationCap, Award as AwardIcon, Building, Pencil, Trash2, Plus } from "lucide-react";
import { EducationDialog } from "./dialogs/EducationDialog";
import { FinanceEducationDialog } from "./dialogs/FinanceEducationDialog";
import { BankingEducationDialog } from "./dialogs/BankingEducationDialog";
import { DeleteConfirmDialog } from "./dialogs/DeleteConfirmDialog";
import { deleteEducation } from "@/app/actions/profile-mutations";
import {
    deleteFinanceAcademicEducation,
    deleteFinanceProfessionalEducation,
    deleteBankingAcademicEducation,
    deleteBankingProfessionalEducation,
    deleteBankingSpecializedTraining,
} from "@/app/actions/finance-banking-mutations";
import { useToast } from "@/hooks/use-toast";
import { sortEducations } from "@/lib/utils";

interface EducationSectionProps {
    educations: Education[];
    financeAcademic: FinanceAcademicEducation[];
    financeProfessional: FinanceProfessionalEducation[];
    bankingAcademic: BankingAcademicEducation[];
    bankingProfessional: BankingProfessionalEducation[];
    bankingTraining: BankingSpecializedTraining[];
    industry: string;
}

export function EducationSection({
    educations,
    financeAcademic,
    financeProfessional,
    bankingAcademic,
    bankingProfessional,
    bankingTraining,
    industry
}: EducationSectionProps) {
    const router = useRouter();
    const { toast } = useToast();

    // Dialog states for General Education  
    const [dialogOpen, setDialogOpen] = useState(false);
    const [selectedEducation, setSelectedEducation] = useState<Education | null>(null);
    const [educationType, setEducationType] = useState<"academic" | "professional">("academic");
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [eduToDelete, setEduToDelete] = useState<string | null>(null);
    const [deleteType, setDeleteType] = useState<"general" | "finance_academic" | "finance_professional" | "banking_academic" | "banking_professional" | "banking_training">("general");
    const [isDeleting, setIsDeleting] = useState(false);

    // Finance Education dialog states
    const [financeDialogOpen, setFinanceDialogOpen] = useState(false);
    const [selectedFinanceEducation, setSelectedFinanceEducation] = useState<FinanceAcademicEducation | FinanceProfessionalEducation | null>(null);
    const [financeEducationType, setFinanceEducationType] = useState<"academic" | "professional">("academic");

    // Banking Education dialog states
    const [bankingDialogOpen, setBankingDialogOpen] = useState(false);
    const [selectedBankingEducation, setSelectedBankingEducation] = useState<BankingAcademicEducation | BankingProfessionalEducation | BankingSpecializedTraining | null>(null);
    const [bankingEducationType, setBankingEducationType] = useState<"academic" | "professional" | "training">("academic");

    const hasAnyEducation = educations.length > 0 ||
        financeAcademic.length > 0 ||
        financeProfessional.length > 0 ||
        bankingAcademic.length > 0 ||
        bankingProfessional.length > 0 ||
        bankingTraining.length > 0;

    if (!hasAnyEducation) {
        return null;
    }

    const formatStatus = (status: string) => {
        return status.split("_").map(word =>
            word.charAt(0).toUpperCase() + word.slice(1)
        ).join(" ");
    };

    const getStatusColor = (status: string) => {
        if (status === "first_class") {
            return "bg-green-500/10 text-green-700 border-green-200 dark:bg-green-500/20 dark:text-green-400";
        }
        if (status.includes("second_class")) {
            return "bg-blue-500/10 text-blue-700 border-blue-200 dark:bg-blue-500/20 dark:text-blue-400";
        }
        return "bg-gray-500/10 text-gray-700 border-gray-200 dark:bg-gray-500/20 dark:text-gray-400";
    };

    const handleEdit = (edu: Education) => {
        setSelectedEducation(edu);
        setEducationType(edu.education_type as "academic" | "professional");
        setDialogOpen(true);
    };

    const handleAdd = (type: "academic" | "professional") => {
        setSelectedEducation(null);
        setEducationType(type);
        setDialogOpen(true);
    };

    const handleDeleteClick = (id: string, type: "general" | "finance_academic" | "finance_professional" | "banking_academic" | "banking_professional" | "banking_training" = "general") => {
        setEduToDelete(id);
        setDeleteType(type);
        setDeleteDialogOpen(true);
    };

    // Finance Education handlers
    const handleFinanceEdit = (edu: FinanceAcademicEducation | FinanceProfessionalEducation, type: "academic" | "professional") => {
        setSelectedFinanceEducation(edu);
        setFinanceEducationType(type);
        setFinanceDialogOpen(true);
    };

    const handleFinanceAdd = (type: "academic" | "professional") => {
        setSelectedFinanceEducation(null);
        setFinanceEducationType(type);
        setFinanceDialogOpen(true);
    };

    // Banking Education handlers
    const handleBankingEdit = (edu: BankingAcademicEducation | BankingProfessionalEducation | BankingSpecializedTraining, type: "academic" | "professional" | "training") => {
        setSelectedBankingEducation(edu);
        setBankingEducationType(type);
        setBankingDialogOpen(true);
    };

    const handleBankingAdd = (type: "academic" | "professional" | "training") => {
        setSelectedBankingEducation(null);
        setBankingEducationType(type);
        setBankingDialogOpen(true);
    };

    const handleDeleteConfirm = async () => {
        if (!eduToDelete) return;

        setIsDeleting(true);
        try {
            let result;

            // Route to the appropriate delete function based on education type
            switch (deleteType) {
                case "finance_academic":
                    result = await deleteFinanceAcademicEducation(eduToDelete);
                    break;
                case "finance_professional":
                    result = await deleteFinanceProfessionalEducation(eduToDelete);
                    break;
                case "banking_academic":
                    result = await deleteBankingAcademicEducation(eduToDelete);
                    break;
                case "banking_professional":
                    result = await deleteBankingProfessionalEducation(eduToDelete);
                    break;
                case "banking_training":
                    result = await deleteBankingSpecializedTraining(eduToDelete);
                    break;
                default:
                    result = await deleteEducation(eduToDelete);
            }

            if (result.success) {
                toast({
                    title: "Success",
                    description: "Education deleted successfully",
                });
                setDeleteDialogOpen(false);
                setEduToDelete(null);
                setDeleteType("general"); // Reset to default
                router.refresh(); // Refresh to show updated data immediately
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Failed to delete education",
                    variant: "destructive",
                });
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsDeleting(false);
        }
    };

    // General education component
    const renderGeneralEducation = () => {
        if (educations.length === 0) return null;

        const academic = sortEducations(educations.filter(e => e.education_type === "academic"));
        const professional = sortEducations(educations.filter(e => e.education_type === "professional"));

        return (
            <Tabs defaultValue="academic" className="w-full">
                <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="academic">Academic</TabsTrigger>
                    <TabsTrigger value="professional">Professional</TabsTrigger>
                </TabsList>

                <TabsContent value="academic" className="space-y-4 mt-4">
                    <div className="flex justify-end mb-2">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleAdd("academic")}
                        >
                            <Plus className="h-4 w-4 mr-2" />
                            Add Academic Education
                        </Button>
                    </div>
                    {academic.length > 0 ? academic.map((edu, index) => (
                        <div key={edu.id}>
                            {index > 0 && <Separator className="my-4" />}
                            <div className="group relative flex gap-4">
                                <div className="flex-shrink-0 hidden md:flex">
                                    <div className="h-12 w-12 rounded-lg bg-primary/10 flex items-center justify-center">
                                        <GraduationCap className="h-6 w-6 text-primary" />
                                    </div>
                                </div>

                                {/* Edit/Delete buttons */}
                                <div className="absolute -right-2 -top-2 flex gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-8 w-8"
                                        onClick={() => handleEdit(edu)}
                                    >
                                        <Pencil className="h-4 w-4" />
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-8 w-8 text-destructive hover:text-destructive"
                                        onClick={() => handleDeleteClick(edu.id)}
                                    >
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </div>

                                <div className="flex-1 pr-16 md:pr-0">
                                    <h3 className="font-semibold">{edu.degree_diploma}</h3>
                                    <p className="text-sm text-muted-foreground">{edu.institution}</p>
                                    <Badge variant="outline" className={`mt-2 text-xs ${getStatusColor(edu.status)}`}>
                                        {formatStatus(edu.status)}
                                    </Badge>
                                </div>
                            </div>
                        </div>
                    )) : (
                        <p className="text-sm text-muted-foreground text-center py-4">No academic education added</p>
                    )}
                </TabsContent>

                <TabsContent value="professional" className="space-y-4 mt-4">
                    <div className="flex justify-end mb-2">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleAdd("professional")}
                        >
                            <Plus className="h-4 w-4 mr-2" />
                            Add Professional Qualification
                        </Button>
                    </div>
                    {professional.length > 0 ? professional.map((edu, index) => (
                        <div key={edu.id}>
                            {index > 0 && <Separator className="my-4" />}
                            <div className="group relative flex gap-4">
                                <div className="flex-shrink-0 hidden md:flex">
                                    <div className="h-12 w-12 rounded-lg bg-primary/10 flex items-center justify-center">
                                        <AwardIcon className="h-6 w-6 text-primary" />
                                    </div>
                                </div>

                                {/* Edit/Delete buttons */}
                                <div className="absolute -right-2 -top-2 flex gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-8 w-8"
