                                    <h3 className="font-semibold">{edu.professional_qualification}</h3>
                                    <p className="text-sm text-muted-foreground">{edu.institution}</p>
                                    <Badge variant="outline" className={`mt-2 text-xs ${getStatusColor(edu.status)}`}>
