"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { aboutSectionSchema, type AboutSectionFormData } from "@/lib/validations/profile";
import { updateAboutSection } from "@/app/actions/profile-mutations";
import { useToast } from "@/hooks/use-toast";
import { CandidateProfile } from "@/types/profile-types";

interface AboutDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    profile: CandidateProfile;
}

export function AboutDialog({ open, onOpenChange, profile }: AboutDialogProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);

    const form = useForm<AboutSectionFormData>({
        resolver: zodResolver(aboutSectionSchema),
        defaultValues: {
            professional_summary: "",
            years_of_experience: null,
            experience_level: undefined,
            expected_monthly_salary: null,
            notice_period: "",
            employment_type: undefined,
            availability_status: undefined,
        },
    });

    // Reset form when dialog opens with profile data
    useEffect(() => {
        if (open && profile) {
            form.reset({
                professional_summary: profile.professional_summary || "",
                years_of_experience: profile.years_of_experience,
                experience_level: profile.experience_level || undefined,
                expected_monthly_salary: profile.expected_monthly_salary ? Number(profile.expected_monthly_salary) : null,
                notice_period: profile.notice_period || "",
                employment_type: profile.employment_type || undefined,
                availability_status: profile.availability_status || undefined,
            });
        }
    }, [open, profile, form]);

    async function onSubmit(data: AboutSectionFormData) {
        setIsSubmitting(true);
        try {
            // Clean up optional fields
            const formattedData = {
                ...data,
                professional_summary: data.professional_summary && data.professional_summary.trim() !== ""
                    ? data.professional_summary
                    : undefined,
                notice_period: data.notice_period && data.notice_period.trim() !== ""
                    ? data.notice_period
                    : undefined,
            };

            const result = await updateAboutSection(formattedData);

            if (result.success) {
                toast({
                    title: "Success",
                    description: "About section updated successfully",
                });
                onOpenChange(false);
                router.refresh();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Something went wrong",
                    variant: "destructive",
                });
            }
        } catch (error) {
            console.error("Error updating about section:", error);
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Edit About Section</DialogTitle>
                    <DialogDescription>
                        Update your professional summary and career preferences
                    </DialogDescription>
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        <FormField
                            control={form.control}
                            name="professional_summary"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Professional Summary</FormLabel>
                                    <FormControl>
                                        <Textarea
                                            placeholder="Write a brief summary of your professional background and expertise..."
                                            rows={5}
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="years_of_experience"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Years of Experience</FormLabel>
                                        <FormControl>
                                            <Input
                                                type="number"
                                                min="0"
                                                max="100"
                                                placeholder="e.g. 5"
                                                {...field}
                                                value={field.value ?? ""}
                                                onChange={(e) => {
                                                    const value = e.target.value;
                                                    field.onChange(value === "" ? null : parseInt(value));
                                                }}
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                            <FormField
                                control={form.control}
                                name="experience_level"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Experience Level</FormLabel>
                                        <Select
                                            onValueChange={field.onChange}
                                            value={field.value}
                                        >
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue placeholder="Select level" />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                <SelectItem value="entry">Entry</SelectItem>
                                                <SelectItem value="junior">Junior</SelectItem>
                                                <SelectItem value="mid">Mid</SelectItem>
                                                <SelectItem value="senior">Senior</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="expected_monthly_salary"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Expected Monthly Salary (LKR)</FormLabel>
                                        <FormControl>
                                            <Input
                                                type="number"
                                                min="0"
                                                placeholder="e.g. 150000"
                                                {...field}
                                                value={field.value ?? ""}
                                                onChange={(e) => {
                                                    const value = e.target.value;
                                                    field.onChange(value === "" ? null : parseFloat(value));
                                                }}
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                            <FormField
                                control={form.control}
                                name="notice_period"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Notice Period</FormLabel>
                                        <FormControl>
                                            <Input placeholder="e.g. 1 month, Immediate" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="employment_type"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Employment Type</FormLabel>
                                        <Select
                                            onValueChange={field.onChange}
                                            value={field.value}
                                        >
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue placeholder="Select type" />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                <SelectItem value="full_time">Full Time</SelectItem>
                                                <SelectItem value="part_time">Part Time</SelectItem>
                                                <SelectItem value="contract">Contract</SelectItem>
                                                <SelectItem value="internship">Internship</SelectItem>
                                                <SelectItem value="freelance">Freelance</SelectItem>
                                                <SelectItem value="volunteer">Volunteer</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                            <FormField
                                control={form.control}
                                name="availability_status"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Availability Status</FormLabel>
                                        <Select
                                            onValueChange={field.onChange}
                                            value={field.value}
                                        >
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue placeholder="Select status" />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                <SelectItem value="available">Available</SelectItem>
                                                <SelectItem value="open_to_opportunities">Open to Opportunities</SelectItem>
                                                <SelectItem value="not_looking">Not Looking</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <DialogFooter>
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => onOpenChange(false)}
                                disabled={isSubmitting}
                            >
                                Cancel
                            </Button>
                            <Button type="submit" disabled={isSubmitting}>
                                {isSubmitting ? "Saving..." : "Save Changes"}
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}

// @ts-nocheck - Suppress react-hook-form type definition conflicts
"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { awardSchema, type AwardFormData } from "@/lib/validations/profile";
import { addAward, updateAward } from "@/app/actions/profile-mutations";
import { useToast } from "@/hooks/use-toast";
import { Award } from "@/types/profile-types";

interface AwardDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    award?: Award | null;
}

export function AwardDialog({ open, onOpenChange, award }: AwardDialogProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const isEditing = !!award;

    const form = useForm<AwardFormData>({
        resolver: zodResolver(awardSchema),
        defaultValues: {
            nature_of_award: "",
            offered_by: "",
            description: "",
        },
    });

    // Reset form when dialog opens with award data
    useEffect(() => {
        if (open && award) {
            form.reset({
                nature_of_award: award.nature_of_award || "",
                offered_by: award.offered_by || "",
                description: award.description || "",
            });
        } else if (open && !award) {
            form.reset({
                nature_of_award: "",
                offered_by: "",
                description: "",
            });
        }
    }, [open, award, form]);

    async function onSubmit(data: AwardFormData) {
        setIsSubmitting(true);
        try {
            // Clean up optional fields - convert empty strings to undefined
            const formattedData = {
                ...data,
                offered_by: data.offered_by && data.offered_by.trim() !== ""
                    ? data.offered_by
                    : undefined,
                description: data.description && data.description.trim() !== ""
                    ? data.description
                    : undefined,
            };

            const result = isEditing
                ? await updateAward(award.id, formattedData)
                : await addAward(formattedData);

            if (result.success) {
                toast({
                    title: "Success",
                    description: `Award ${isEditing ? "updated" : "added"} successfully`,
                });
                onOpenChange(false);
                form.reset();
                router.refresh();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Something went wrong",
                    variant: "destructive",
                });
            }
        } catch (error) {
            console.error(`Error ${isEditing ? "updating" : "adding"} award:`, error);
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>{isEditing ? "Edit Award" : "Add Award"}</DialogTitle>
                    <DialogDescription>
                        {isEditing ? "Update your award details" : "Add a new award to your profile"}
                    </DialogDescription>
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        <FormField
                            control={form.control}
                            name="nature_of_award"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Award Name *</FormLabel>
                                    <FormControl>
                                        <Input placeholder="e.g. Employee of the Year" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="offered_by"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Offered By</FormLabel>
                                    <FormControl>
                                        <Input placeholder="e.g. Company Name or Organization" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="description"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Description</FormLabel>
                                    <FormControl>
                                        <Textarea
                                            placeholder="Add details about this award and why you received it..."
                                            rows={4}
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <DialogFooter>
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => onOpenChange(false)}
                                disabled={isSubmitting}
                            >
                                Cancel
                            </Button>
                            <Button type="submit" disabled={isSubmitting}>
                                {isSubmitting ? "Saving..." : isEditing ? "Update" : "Add"}
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}

// @ts-nocheck - Suppress react-hook-form type definition conflicts
"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    bankingAcademicEducationSchema,
    bankingProfessionalEducationSchema,
    bankingSpecializedTrainingSchema,
    type BankingAcademicEducationData,
    type BankingProfessionalEducationData,
    type BankingSpecializedTrainingData,
    ACADEMIC_EDUCATION_STATUSES,
    PROFESSIONAL_EDUCATION_STATUSES
} from "@/lib/validations/profile-schema";
import {
    addBankingAcademicEducation,
    updateBankingAcademicEducation,
    addBankingProfessionalEducation,
    updateBankingProfessionalEducation,
    addBankingSpecializedTraining,
    updateBankingSpecializedTraining,
} from "@/app/actions/finance-banking-mutations";
import { useToast } from "@/hooks/use-toast";
import {
    BankingAcademicEducation,
    BankingProfessionalEducation,
    BankingSpecializedTraining
} from "@/types/profile-types";

interface BankingEducationDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    education?: BankingAcademicEducation | BankingProfessionalEducation | BankingSpecializedTraining | null;
    educationType: "academic" | "professional" | "training";
}

export function BankingEducationDialog({
    open,
    onOpenChange,
    education,
    educationType
}: BankingEducationDialogProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const isEditing = !!education;
    const isAcademic = educationType === "academic";
    const isProfessional = educationType === "professional";
    const isTraining = educationType === "training";

    const getSchema = () => {
        if (isAcademic) return bankingAcademicEducationSchema;
        if (isProfessional) return bankingProfessionalEducationSchema;
        return bankingSpecializedTrainingSchema;
    };

    const form = useForm<BankingAcademicEducationData | BankingProfessionalEducationData | BankingSpecializedTrainingData>({
        resolver: zodResolver(getSchema()),
        defaultValues: isAcademic
            ? {
                degreeDiploma: "",
                institution: "",
                status: "incomplete",
            }
            : isProfessional
                ? {
                    professionalQualification: "",
                    institution: "",
                    status: "incomplete",
                }
                : {
                    certificateName: "",
                    issuingAuthority: "",
                    certificateIssueMonth: "",
                    status: "incomplete",
                },
    });

    // Reset form when dialog opens
    useEffect(() => {
        if (open && education) {
            if (isAcademic) {
                const edu = education as BankingAcademicEducation;
                form.reset({
                    degreeDiploma: edu.degree_diploma || "",
                    institution: edu.institution || "",
                    status: edu.status || "incomplete",
                });
            } else if (isProfessional) {
                const edu = education as BankingProfessionalEducation;
                form.reset({
                    professionalQualification: edu.professional_qualification || "",
                    institution: edu.institution || "",
                    status: edu.status || "incomplete",
                });
            } else {
                const edu = education as BankingSpecializedTraining;
                form.reset({
                    certificateName: edu.certificate_name || "",
                    issuingAuthority: edu.issuing_authority || "",
                    certificateIssueMonth: edu.certificate_issue_month || "",
                    status: edu.status || "incomplete",
                });
            }
        } else if (open && !education) {
            if (isAcademic) {
                form.reset({
                    degreeDiploma: "",
                    institution: "",
                    status: "incomplete",
                });
            } else if (isProfessional) {
                form.reset({
                    professionalQualification: "",
                    institution: "",
                    status: "incomplete",
                });
            } else {
                form.reset({
                    certificateName: "",
                    issuingAuthority: "",
                    certificateIssueMonth: "",
                    status: "incomplete",
                });
            }
        }
    }, [open, education, educationType, form, isAcademic, isProfessional]);

    async function onSubmit(data: BankingAcademicEducationData | BankingProfessionalEducationData | BankingSpecializedTrainingData) {
        setIsSubmitting(true);
        try {
            let result;

            if (isAcademic) {
                result = isEditing
                    ? await updateBankingAcademicEducation(education.id, data as BankingAcademicEducationData)
                    : await addBankingAcademicEducation(data as BankingAcademicEducationData);
            } else if (isProfessional) {
                result = isEditing
                    ? await updateBankingProfessionalEducation(education.id, data as BankingProfessionalEducationData)
                    : await addBankingProfessionalEducation(data as BankingProfessionalEducationData);
            } else {
                result = isEditing
                    ? await updateBankingSpecializedTraining(education.id, data as BankingSpecializedTrainingData)
                    : await addBankingSpecializedTraining(data as BankingSpecializedTrainingData);
            }

            if (result.success) {
                toast({
                    title: "Success",
                    description: `Banking ${isAcademic ? "academic" : isProfessional ? "professional" : "training"} education ${isEditing ? "updated" : "added"} successfully`,
                });
                onOpenChange(false);
                form.reset();
                router.refresh();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Something went wrong",
                    variant: "destructive",
                });
            }
        } catch (error) {
            console.error(`Error ${isEditing ? "updating" : "adding"} banking education:`, error);
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsSubmitting(false);
        }
    }

    const getTitle = () => {
        if (isAcademic) return "Academic";
        if (isProfessional) return "Professional";
        return "Specialized Training";
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>
                        {isEditing ? "Edit" : "Add"} {getTitle()} Education
                    </DialogTitle>
                    <DialogDescription>
                        {isEditing
                            ? "Update your banking education details"
                            : `Add ${getTitle().toLowerCase()} education to your banking profile`
                        }
                    </DialogDescription>
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        {isAcademic && (
                            <FormField
                                control={form.control}
                                name="degreeDiploma"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Degree/Diploma *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="e.g. Bachelor of Banking and Finance" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        )}

                        {isProfessional && (
                            <FormField
                                control={form.control}
                                name="professionalQualification"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Professional Qualification *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="e.g. Certified Banking Professional" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        )}

                        {isTraining && (
                            <>
                                <FormField
                                    control={form.control}
                                    name="certificateName"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel>Certificate/Training Name *</FormLabel>
                                            <FormControl>
                                                <Input placeholder="e.g. Risk Management Certificate" {...field} />
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="issuingAuthority"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel>Issuing Authority/Institution *</FormLabel>
                                            <FormControl>
                                                <Input placeholder="e.g. Central Bank" {...field} />
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="certificateIssueMonth"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel>Issue Month</FormLabel>
                                            <FormControl>
                                                <Input
                                                    type="month"
                                                    placeholder="YYYY-MM"
                                                    {...field}
                                                    value={field.value || ""}
                                                />
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                            </>
                        )}

                        {!isTraining && (
                            <FormField
                                control={form.control}
                                name="institution"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Institution *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="e.g. University of Example" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        )}

                        <FormField
                            control={form.control}
                            name="status"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Status *</FormLabel>
                                    <div className="flex gap-2">
                                        <Select
                                            onValueChange={(val) => {
                                                if (val !== "other") {
                                                    field.onChange(val);
                                                } else {
                                                    field.onChange("");
                                                }
                                            }}
                                            value={
                                                isAcademic
                                                    ? ACADEMIC_EDUCATION_STATUSES.some(s => s.value === field.value) ? field.value : "other"
                                                    : PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === field.value) ? field.value : "other"
                                            }
                                        >
                                            <FormControl>
                                                <SelectTrigger className={(isAcademic && !ACADEMIC_EDUCATION_STATUSES.some(s => s.value === field.value)) || (!isAcademic && !PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === field.value)) ? "w-[40%]" : "w-full"}>
                                                    <SelectValue placeholder="Select status" />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                {(isAcademic ? ACADEMIC_EDUCATION_STATUSES : PROFESSIONAL_EDUCATION_STATUSES).map((status) => (
                                                    <SelectItem key={status.value} value={status.value}>
                                                        {status.label}
                                                    </SelectItem>
                                                ))}
                                                <SelectItem value="other">Other (Please specify)</SelectItem>
                                            </SelectContent>
                                        </Select>

                                        {((isAcademic && !ACADEMIC_EDUCATION_STATUSES.some(s => s.value === field.value)) || (!isAcademic && !PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === field.value))) && (
                                            <Input
                                                value={field.value}
                                                onChange={field.onChange}
                                                placeholder="Specify status..."
                                                className="flex-1"
                                            />
                                        )}
                                    </div>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <DialogFooter>
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => onOpenChange(false)}
                                disabled={isSubmitting}
                            >
                                Cancel
                            </Button>
                            <Button type="submit" disabled={isSubmitting}>
                                {isSubmitting ? "Saving..." : isEditing ? "Update" : "Add"}
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}

// @ts-nocheck - Suppress react-hook-form type definition conflicts
"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { basicInfoSchema, type BasicInfoFormData } from "@/lib/validations/profile";
import { updateBasicInfo } from "@/app/actions/profile-mutations";
import { useToast } from "@/hooks/use-toast";
import { CandidateProfile } from "@/types/profile-types";
import { Upload, Loader2, X } from "lucide-react";
import { useJobDesignations, uniqueDesignationsByName } from "@/hooks/useJobDesignations";
import { Combobox } from "@/components/ui/combobox";

interface BasicInfoDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    profile: CandidateProfile;
    onProfileUpdated?: () => void;
}

export function BasicInfoDialog({ open, onOpenChange, profile, onProfileUpdated }: BasicInfoDialogProps) {
    const router = useRouter();
    const { toast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [previewImage, setPreviewImage] = useState<string | null>(null);
    const [expectedPositions, setExpectedPositions] = useState<string[]>([]);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const canLoadDesignations = Boolean(profile?.industry);

    const { jobDesignations, loading: loadingDesignations, error: designationsError } = useJobDesignations(
        profile?.industry
    );
    const designationOptions = uniqueDesignationsByName(jobDesignations);

    const form = useForm<BasicInfoFormData>({
        resolver: zodResolver(basicInfoSchema),
        defaultValues: {
            first_name: "",
            last_name: "",
            nicPassport: "",
            phone: "",
            alternative_phone: "",
            country: "",
            current_position: "",
            highest_qualification: undefined,
            profile_image_url: "",
        },
    });

    // Reset form when dialog opens with profile data
    useEffect(() => {
        if (open && profile) {
            form.reset({
                first_name: profile.first_name || "",
                last_name: profile.last_name || "",
                nicPassport: profile.nicPassport || "",
                phone: profile.phone || "",
                alternative_phone: profile.alternative_phone || "",
                country: profile.country || "",
                current_position: profile.current_position || "",
                highest_qualification: profile.highest_qualification || undefined,
                profile_image_url: profile.profile_image_url || "",
                expected_positions: profile.expected_positions ?? [],
            });
            setExpectedPositions(profile.expected_positions ?? []);
            setPreviewImage(profile.profile_image_url);
        }
    }, [open, profile, form]);

    const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        // Validate file type
        const validTypes = ["image/jpeg", "image/jpg", "image/png", "image/gif", "image/webp"];
        if (!validTypes.includes(file.type)) {
            toast({
                title: "Invalid file type",
                description: "Please upload an image file (JPEG, PNG, GIF, or WebP)",
                variant: "destructive",
            });
            return;
        }

        // Validate file size (5MB)
        if (file.size > 5 * 1024 * 1024) {
            toast({
                title: "File too large",
                description: "Please upload an image smaller than 5MB",
                variant: "destructive",
            });
            return;
        }

        // Show preview
        const reader = new FileReader();
        reader.onloadend = () => {
            setPreviewImage(reader.result as string);
        };
        reader.readAsDataURL(file);

        // Upload file
        setIsUploading(true);
        try {
            const formData = new FormData();
            formData.append("file", file);

            const response = await fetch("/api/candidate/upload-profile-image", {
                method: "POST",
                body: formData,
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.error || "Failed to upload image");
            }

            // Update form with new image URL
            form.setValue("profile_image_url", data.data.url);

            toast({
                title: "Success",
                description: "Profile picture uploaded successfully",
            });
        } catch (error) {
            console.error("Error uploading image:", error);
            toast({
                title: "Error",
                description: error instanceof Error ? error.message : "Failed to upload image",
                variant: "destructive",
            });
            // Revert preview
            setPreviewImage(profile.profile_image_url);
        } finally {
            setIsUploading(false);
        }
    };

    async function onSubmit(data: BasicInfoFormData) {
        setIsSubmitting(true);
        try {
            // Clean up optional fields
            const formattedData = {
                ...data,
                alternative_phone: data.alternative_phone && data.alternative_phone.trim() !== ""
                    ? data.alternative_phone
                    : undefined,
                country: data.country && data.country.trim() !== ""
                    ? data.country
                    : undefined,
                expected_positions: expectedPositions,
            };

            const result = await updateBasicInfo(formattedData);

            if (result.success) {
                toast({
                    title: "Success",
                    description: "Basic information updated successfully",
                });
                onOpenChange(false);
                router.refresh();
                onProfileUpdated?.();
            } else {
                toast({
                    title: "Error",
                    description: result.error || "Something went wrong",
                    variant: "destructive",
                });
            }
        } catch (error) {
            console.error("Error updating basic info:", error);
            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsSubmitting(false);
        }
    }

    const initials = `${profile.first_name[0]}${profile.last_name[0]}`.toUpperCase();

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Edit Basic Information</DialogTitle>
                    <DialogDescription>
                        Update your basic information and profile picture
                    </DialogDescription>
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        {/* Profile Picture Upload */}
                        <div className="flex flex-col items-center gap-4 py-4">
                            <Avatar className="h-32 w-32 border-4 border-background shadow-lg">
                                <AvatarImage src={previewImage || undefined} alt="Profile picture" />
                                <AvatarFallback className="text-2xl font-semibold bg-primary/10 text-primary">
                                    {initials}
                                </AvatarFallback>
                            </Avatar>
                            <div className="flex flex-col items-center gap-2">
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    accept="image/*"
                                    onChange={handleFileChange}
                                    className="hidden"
                                />
                                <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => fileInputRef.current?.click()}
                                    disabled={isUploading || isSubmitting}
                                >
                                    {isUploading ? (
                                        <>
                                            <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                            Uploading...
                                        </>
                                    ) : (
                                        <>
                                            <Upload className="h-4 w-4 mr-2" />
                                            Change Profile Picture
                                        </>
                                    )}
                                </Button>
                                <p className="text-xs text-muted-foreground">
                                    JPG, PNG, GIF or WebP. Max 5MB.
                                </p>
                            </div>
                        </div>

                        {/* Name Fields */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="first_name"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>First Name *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="John" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                            <FormField
                                control={form.control}
                                name="last_name"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Last Name *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="Doe" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        {/* NIC/Passport and Phone Fields */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="nicPassport"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>NIC/Passport *</FormLabel>
                                        <FormControl>
                                            <Input placeholder="e.g. 199012345678 or N1234567" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                            <FormField
                                control={form.control}
                                name="phone"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Phone * <span className="text-xs text-muted-foreground font-normal ml-1">( Format: +94XXXXXXXXX )</span></FormLabel>
                                        <FormControl>
                                            <Input placeholder="+94771234567" maxLength={15} {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <FormField
                            control={form.control}
                            name="alternative_phone"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Alternative Phone <span className="text-xs text-muted-foreground font-normal ml-1">( Format: +94XXXXXXXXX )</span></FormLabel>
                                    <FormControl>
                                        <Input placeholder="+94771234567 (Optional)" maxLength={15} {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="current_position"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Current Position *</FormLabel>
                                    {!canLoadDesignations ? (
                                        <div className="space-y-2">
                                            <p className="text-sm text-muted-foreground">
                                                Set your industry on your profile to see suggested job titles, or type your position below.
                                            </p>
                                            <FormControl>
                                                <Input placeholder="e.g. Senior Software Engineer" {...field} />
                                            </FormControl>
                                        </div>
                                    ) : loadingDesignations ? (
                                        <div className="flex items-center gap-2 p-2 text-sm text-muted-foreground border rounded-md">
                                            <Loader2 className="h-4 w-4 animate-spin" />
                                            Loading job designations...
                                        </div>
                                    ) : designationsError ? (
                                        <div className="space-y-2">
                                            <p className="text-sm text-destructive">
                                                Failed to load job designations. You can enter manually.
                                            </p>
                                            <FormControl>
                                                <Input placeholder="e.g. Senior Software Engineer" {...field} />
                                            </FormControl>
                                        </div>
                                    ) : (
                                        <FormControl>
                                            <Combobox
                                                options={designationOptions.map((designation) => ({
                                                    value: designation.designation_name,
                                                    label: designation.designation_name,
                                                }))}
                                                value={field.value}
                                                onValueChange={field.onChange}
                                                placeholder="Select your current position"
                                                searchPlaceholder="Search job titles..."
                                                emptyMessage="No job title found for your industry."
                                            />
                                        </FormControl>
                                    )}
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        {/* Expected Job Positions */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">
                                Expected Job Positions *
                                <span className="text-xs text-muted-foreground font-normal ml-1">(Up to 3)</span>
                            </label>

                            {/* Selected pills */}
                            {expectedPositions.length > 0 && (
                                <div className="flex flex-wrap gap-2">
                                    {expectedPositions.map((pos, idx) => (
                                        <span
                                            key={idx}
                                            className="inline-flex items-center gap-1 rounded-full border border-primary/30 bg-primary/10 px-3 py-1 text-sm font-medium text-primary"
                                        >
                                            {pos}
                                            <button
                                                type="button"
                                                aria-label={`Remove ${pos}`}
                                                onClick={() => setExpectedPositions(prev => prev.filter((_, i) => i !== idx))}
                                                className="ml-0.5 rounded-full p-0.5 hover:bg-primary/20 transition-colors"
                                            >
                                                <X className="h-3 w-3" />
                                            </button>
                                        </span>
                                    ))}
                                </div>
                            )}

                            {/* Combobox / limit message */}
                            {expectedPositions.length >= 3 ? (
                                <p className="text-xs text-muted-foreground py-1">
                                    Maximum of 3 positions reached. Remove one to add another.
                                </p>
                            ) : !canLoadDesignations ? (
                                <Input
                                    placeholder="Type a position and press Enter"
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter") {
                                            e.preventDefault();
                                            const val = (e.target as HTMLInputElement).value.trim();
                                            if (val && !expectedPositions.includes(val)) {
                                                setExpectedPositions((prev) => [...prev, val]);
                                                (e.target as HTMLInputElement).value = "";
                                            }
                                        }
                                    }}
                                />
                            ) : loadingDesignations ? (
                                <div className="flex items-center gap-2 p-2 text-sm text-muted-foreground border rounded-md">
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Loading job designations...
                                </div>
                            ) : designationsError ? (
                                <Input
                                    placeholder="Type a position and press Enter"
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter") {
                                            e.preventDefault();
                                            const val = (e.target as HTMLInputElement).value.trim();
                                            if (val && !expectedPositions.includes(val)) {
                                                setExpectedPositions((prev) => [...prev, val]);
                                                (e.target as HTMLInputElement).value = "";
                                            }
                                        }
                                    }}
                                />
                            ) : (
                                <Combobox
                                    options={designationOptions
                                        .filter((d) => !expectedPositions.includes(d.designation_name))
                                        .map((d) => ({
                                            value: d.designation_name,
                                            label: d.designation_name,
                                        }))}
                                    value=""
                                    onValueChange={(value) => {
                                        if (value && !expectedPositions.includes(value)) {
                                            setExpectedPositions((prev) => [...prev, value]);
                                        }
                                    }}
                                    placeholder="Search and select a position"
                                    searchPlaceholder="Search job titles..."
                                    emptyMessage="No job title found for your industry."
                                />
                            )}
                            {/* Show validation error if submitted with empty */}
                            {expectedPositions.length === 0 && (
                                <p className="text-xs text-destructive">At least one expected position is required</p>
                            )}
                        </div>

                        <FormField
                            control={form.control}
                            name="highest_qualification"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Highest Qualification</FormLabel>
                                    <Select onValueChange={field.onChange} value={field.value}>
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Select highest qualification" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem value="bachelors_degree">Bachelor's Degree</SelectItem>
                                            <SelectItem value="masters_degree">Master's Degree</SelectItem>
                                            <SelectItem value="doctorate_phd">Doctorate/PhD</SelectItem>
                                            <SelectItem value="undergraduate">Undergraduate</SelectItem>
                                            <SelectItem value="post_graduate">Post Graduate</SelectItem>
                                            <SelectItem value="diploma">Diploma</SelectItem>
                                            <SelectItem value="certificate">Certificate</SelectItem>
                                            <SelectItem value="professional_certification">Professional Certification</SelectItem>
                                            <SelectItem value="vocational_training">Vocational Training</SelectItem>
                                            <SelectItem value="no_formal_education">No Formal Education</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="country"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Country</FormLabel>
                                    <FormControl>
                                        <Input placeholder="e.g. Sri Lanka" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <DialogFooter>
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => onOpenChange(false)}
                                disabled={isSubmitting || isUploading}
                            >
                                Cancel
                            </Button>
                            <Button type="submit" disabled={isSubmitting || isUploading}>
                                {isSubmitting ? "Saving..." : "Save Changes"}
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}

