            toast({
                title: "Error",
                description: "An unexpected error occurred",
                variant: "destructive",
            });
        } finally {
            setIsSubmitting(false);
        }
    }

    const isAcademic = educationType === "academic";

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
