                                    "rounded-full px-4 py-2 text-sm font-medium transition-colors",
                                    selectedQualifications.includes(qual.value)
                                        ? "bg-primary text-primary-foreground"
                                        : "bg-muted hover:bg-muted/80"
                                )}
                            >
                                {qual.label}
                            </button>
                        ))}
                    </div>
                </CardContent>
            </Card>

            {/* Submit Button */}
            <div className="flex justify-end">
                <Button type="submit" size="lg" disabled={isPending} className="min-w-[200px]">
                    {isPending ? (
                        <>
                            <Loader2 className="h-4 w-4 animate-spin" />
                            Saving...
                        </>
                    ) : (
                        "Complete Profile"
                    )}
                </Button>
            </div>
        </form>
    );
}

"use client";

import { useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import { Progress } from "@/components/ui/progress";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { CVUpload } from "./CVUpload";
import { IndustryStep } from "./steps/IndustryStep";
import { BasicInfoStep } from "./steps/BasicInfoStep";
import { ExperienceStep } from "./steps/ExperienceStep";
import { EducationStep } from "./steps/EducationStep";
import { AwardsStep } from "./steps/AwardsStep";
import { ProjectsStep } from "./steps/ProjectsStep";
import { FinanceEducationStep } from "./steps/FinanceEducationStep";
import { BankingEducationStep } from "./steps/BankingEducationStep";
import { SummaryStep } from "./steps/SummaryStep";
import { completeFullProfile, completeFullProfileWithCV } from "@/app/actions/profile";
import { IT_INDUSTRIES, BANKING_FINANCE_INDUSTRIES } from "@/lib/validations/profile-schema";
import type {
    CompleteProfileData,
    WorkExperienceData,
    EducationData,
    AwardData,
    ProjectData,
    CertificateData,
    FinanceAcademicEducationData,
    FinanceProfessionalEducationData,
    BankingAcademicEducationData,
    BankingProfessionalEducationData,
    BankingSpecializedTrainingData,
    CVExtractionResult,
    BasicInfoData,
} from "@/lib/validations/profile-schema";
import { CertificatesStep } from "./steps";

interface CreateProfileWizardProps {
    userId: string;
    initialData: {
        firstName: string;
        lastName: string;
        email: string;
        phone: string;
        address?: string;
        country?: string;
        industry?: string;
    };
}

/** Gemini may return YYYY-MM-DD; <input type="month"> only accepts YYYY-MM. */
function cvExtractedDateToMonthValue(value: string | null | undefined): string {
    if (!value) return "";
    const m = String(value).trim().match(/^(\d{4})-(\d{2})(?:-\d{2})?/);
    return m ? `${m[1]}-${m[2]}` : "";
}

type Step = {
    id: string;
    title: string;
    visible: boolean;
};

export function CreateProfileWizard({ userId, initialData }: CreateProfileWizardProps) {
    const router = useRouter();
    const [currentStep, setCurrentStep] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Form state
    const [industry, setIndustry] = useState<string>(initialData.industry || "");
    const [cvUploaded, setCvUploaded] = useState(false);
    const [cvFile, setCvFile] = useState<File | null>(null);
    const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
    const [basicInfo, setBasicInfo] = useState<BasicInfoData>({
        firstName: initialData.firstName || "",
        lastName: initialData.lastName || "",
        email: initialData.email || "",
        phone: initialData.phone || "",
        alternativePhone: "",
        address: initialData.address || "",
        country: initialData.country || "",
        currentPosition: "",
        yearsOfExperience: 0,
        experienceLevel: "entry",
        expectedMonthlySalary: 0,
        availabilityStatus: "available",
        noticePeriod: "immediate",
        employmentType: "full_time",
        expectedPositions: [],
    });
    const [professionalSummary, setProfessionalSummary] = useState("");
    const [workExperiences, setWorkExperiences] = useState<WorkExperienceData[]>([]);
    const [educations, setEducations] = useState<EducationData[]>([]);
    const [awards, setAwards] = useState<AwardData[]>([]);
    const [projects, setProjects] = useState<ProjectData[]>([]);
    const [certificates, setCertificates] = useState<CertificateData[]>([]);
    // Finance education
    const [financeAcademicEducation, setFinanceAcademicEducation] = useState<FinanceAcademicEducationData[]>([]);
    const [financeProfessionalEducation, setFinanceProfessionalEducation] = useState<FinanceProfessionalEducationData[]>([]);

    // Banking education  
    const [bankingAcademicEducation, setBankingAcademicEducation] = useState<BankingAcademicEducationData[]>([]);
    const [bankingProfessionalEducation, setBankingProfessionalEducation] = useState<BankingProfessionalEducationData[]>([]);
    const [bankingSpecializedTraining, setBankingSpecializedTraining] = useState<BankingSpecializedTrainingData[]>([]);

    // Determine visible steps based on industry
    const isITIndustry = IT_INDUSTRIES.includes(industry as typeof IT_INDUSTRIES[number]);
    const isFinanceIndustry = industry === "finance_investment";
    const isBankingIndustry = industry === "banking";

    const steps: Step[] = [
        { id: "industry", title: "Industry & CV", visible: true },
        { id: "basic", title: "Basic Info", visible: true },
        { id: "experience", title: "Experience", visible: true },
        // Standard education only for IT and other industries (not Finance/Banking)
        { id: "education", title: "Education", visible: !isFinanceIndustry && !isBankingIndustry },
        // Industry-specific education replaces standard education
        { id: "financeEducation", title: "Education", visible: isFinanceIndustry },
        { id: "bankingEducation", title: "Education", visible: isBankingIndustry },
        { id: "projects", title: "Projects", visible: isITIndustry },
        { id: "certificates", title: "Certificates", visible: isITIndustry },
        { id: "awards", title: "Awards", visible: true },
        { id: "summary", title: "Summary", visible: true },
    ].filter((step) => step.visible);

    const totalSteps = steps.length;
    const progress = Math.round(((currentStep + 1) / totalSteps) * 100);

    const handleCVExtracted = useCallback((data: CVExtractionResult) => {
        setCvUploaded(true);

        // Populate form fields from extracted data (excluding name and email as they come from registration)
        if (data.phone) setBasicInfo((prev) => ({ ...prev, phone: data.phone! }));
        if (data.address) setBasicInfo((prev) => ({ ...prev, address: data.address! }));
        if (data.currentPosition) setBasicInfo((prev) => ({ ...prev, currentPosition: data.currentPosition! }));
        if (data.yearsOfExperience) setBasicInfo((prev) => ({ ...prev, yearsOfExperience: data.yearsOfExperience! }));
        if (data.professionalSummary) setProfessionalSummary(data.professionalSummary);

        // Work experiences
        if (data.workExperiences?.length) {
            setWorkExperiences(
                data.workExperiences.map((exp) => ({
                    jobTitle: exp.jobTitle || "",
                    company: exp.company || "",
                    employmentType: "full_time" as const,
                    locationType: "onsite" as const,
                    startDate: cvExtractedDateToMonthValue(exp.startDate),
                    endDate: exp.endDate ? cvExtractedDateToMonthValue(exp.endDate) || null : null,
                    description: exp.description || "",
                    isCurrent: exp.isCurrent || false,
                }))
            );
        }

        // Educations - Map to standard educations AND industry-specific states
        if (data.educations?.length) {
            const academicEdus: FinanceAcademicEducationData[] = [];
            const professionalEdus: FinanceProfessionalEducationData[] = [];
            const standardEdus: EducationData[] = [];

            data.educations.forEach((edu) => {
                const status = (edu.status?.toLowerCase() === "complete" || edu.status?.toLowerCase() === "completed")
                    ? "general" as const
                    : "incomplete" as const;

                const type = (edu.educationType?.toLowerCase() === "professional") ? "professional" as const : "academic" as const;

                // For standard education list (used by IT/Other)
                standardEdus.push({
                    educationType: type,
                    degreeDiploma: type === "professional" ? (edu.professionalQualification || edu.degreeDiploma || "") : (edu.degreeDiploma || ""),
                    institution: edu.institution || "",
                    status
                });

                if (type === "academic") {
                    academicEdus.push({
                        degreeDiploma: edu.degreeDiploma || "",
                        institution: edu.institution || "",
                        status
                    });
                } else {
                    professionalEdus.push({
                        professionalQualification: edu.professionalQualification || edu.degreeDiploma || "",
                        institution: edu.institution || "",
                        status
                    });
                }
            });

            // Standard education (IT and other industries)
            setEducations(standardEdus);

            // Finance industry
            setFinanceAcademicEducation(academicEdus);
            setFinanceProfessionalEducation(professionalEdus);

            // Banking industry
            setBankingAcademicEducation(academicEdus);
            setBankingProfessionalEducation(professionalEdus);
        }

        // Certificates (for IT)
        if (data.certificates?.length) {
            setCertificates(
                data.certificates.map((cert) => ({
                    certificateName: cert.certificateName || "",
                    issuingAuthority: cert.issuingAuthority || "",
                    issueDate: cert.issueDate || "",
                }))
            );
        }

        // Projects (for IT)
        if (data.projects?.length) {
            setProjects(
                data.projects.map((proj) => ({
                    projectName: proj.projectName || "",
                    description: proj.description || "",
                    demoUrl: proj.demoUrl || "",
                    isCurrent: false,
                }))
            );
        }

        // Awards/Achievements
        if (data.awards?.length) {
            setAwards(
                data.awards.map((award) => ({
                    natureOfAward: award.awardName || "",
                    offeredBy: award.offeredBy || "",
                    description: award.description || "",
                }))
            );
        }

        // Move to next step
        setCurrentStep(1);
    }, []);

    const handleNext = useCallback(() => {
        if (currentStep < totalSteps - 1) {
            setCurrentStep((prev) => prev + 1);
            setError(null);
        }
    }, [currentStep, totalSteps]);

    const handlePrevious = useCallback(() => {
        if (currentStep > 0) {
            setCurrentStep((prev) => prev - 1);
            setError(null);
        }
    }, [currentStep]);

    const handleSubmit = useCallback(async () => {
        setIsLoading(true);
        setError(null);

        try {
            // Strip out any incomplete education rows before submission (safety net)
            // They must have BOTH institution and degree/qualification
            const cleanedEducations = educations.filter(
                (edu) => edu.institution.trim() !== "" && edu.degreeDiploma.trim() !== ""
            );

            const cleanedFinanceAcademic = financeAcademicEducation.filter(
                (edu) => edu.institution.trim() !== "" && edu.degreeDiploma.trim() !== ""
            );

            const cleanedFinanceProf = financeProfessionalEducation.filter(
                (edu) => edu.institution.trim() !== "" && edu.professionalQualification.trim() !== ""
            );

            const cleanedBankingAcademic = bankingAcademicEducation.filter(
                (edu) => edu.institution.trim() !== "" && edu.degreeDiploma.trim() !== ""
            );

            const cleanedBankingProf = bankingProfessionalEducation.filter(
                (edu) => edu.institution.trim() !== "" && edu.professionalQualification.trim() !== ""
            );

            const cleanedBankingSpecial = bankingSpecializedTraining.filter(
                (edu) => edu.issuingAuthority.trim() !== "" && edu.certificateName.trim() !== ""
            );

            // If not IT/Other industry, standard educations shouldn't be submitted
            const finalEducations = (isFinanceIndustry || isBankingIndustry) ? [] : cleanedEducations;

            const profileData: CompleteProfileData = {
                industry: industry as CompleteProfileData["industry"],
                basicInfo,
                professionalSummary,
                workExperiences,
                educations: finalEducations,
                awards,
                projects: isITIndustry ? projects : undefined,
                certificates: isITIndustry ? certificates : undefined,
                financeAcademicEducation: isFinanceIndustry ? cleanedFinanceAcademic : undefined,
                financeProfessionalEducation: isFinanceIndustry ? cleanedFinanceProf : undefined,
                bankingAcademicEducation: isBankingIndustry ? cleanedBankingAcademic : undefined,
                bankingProfessionalEducation: isBankingIndustry ? cleanedBankingProf : undefined,
                bankingSpecializedTraining: isBankingIndustry ? cleanedBankingSpecial : undefined,
            };

            const formData = new FormData();
            formData.append("profileData", JSON.stringify(profileData));

            if (cvFile) {
                formData.append("cvFile", cvFile);
            }

            if (profileImageFile) {
                formData.append("profileImageFile", profileImageFile);
            }

            // Show progress toast
            if (cvFile) {
                toast.info("Uploading your CV and generating standardized format...", {
                    duration: 5000,
                });
            } else {
                toast.info("Creating your profile...");
            }

            // Use the new action that handles CV upload and transaction
            const result = await completeFullProfileWithCV(formData);

            if (result.success) {
                toast.success(result.message || "Profile completed successfully!");
                setTimeout(() => {
                    window.location.href = "/candidate/dashboard";
                }, 1000);
            } else {
                // Display field-specific errors
                if (result.errors && Object.keys(result.errors).length > 0) {
                    // Show each field error
                    Object.entries(result.errors).forEach(([field, messages]) => {
                        const errorMessage = Array.isArray(messages) ? messages.join(", ") : messages;
                        toast.error(`${field}: ${errorMessage}`);
                    });
                } else {
                    // Fallback to generic message
                    toast.error(result.message || "Failed to complete profile. Please try again.");
                }
            }
        } catch (err) {
            setError("An unexpected error occurred. Please try again.");
            console.error("Profile submission error:", err);
        } finally {
            setIsLoading(false);
        }
    }, [
        userId, industry, basicInfo, professionalSummary, workExperiences,
        educations, awards, projects, certificates, financeAcademicEducation,
        financeProfessionalEducation, bankingAcademicEducation, bankingProfessionalEducation,
        bankingSpecializedTraining, isITIndustry, isFinanceIndustry, isBankingIndustry,
        bankingSpecializedTraining, isITIndustry, isFinanceIndustry, isBankingIndustry,
        cvFile, profileImageFile, router
    ]);

    const renderStep = () => {
        const stepId = steps[currentStep]?.id;

        switch (stepId) {
            case "industry":
                return (
                    <IndustryStep
                        industry={industry}
                        onIndustryChange={setIndustry}
                        onCVExtracted={handleCVExtracted}
                        onFileSelect={setCvFile}
                        onSkipCV={() => setCurrentStep(1)}
                        onNext={handleNext}
                    />
                );
            case "basic":
                return (
                    <BasicInfoStep
                        data={basicInfo}
                        onChange={setBasicInfo}
                        onImageSelect={setProfileImageFile}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                        industry={industry}
                    />
                );
            case "experience":
                return (
                    <ExperienceStep
                        experiences={workExperiences}
                        onChange={setWorkExperiences}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "education":
                return (
                    <EducationStep
                        educations={educations}
                        onChange={setEducations}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "awards":
                return (
                    <AwardsStep
                        awards={awards}
                        onChange={setAwards}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "projects":
                return (
                    <ProjectsStep
                        projects={projects}
                        onChange={setProjects}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "certificates":
                return (
                    <CertificatesStep
                        certificates={certificates}
                        onChange={setCertificates}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "financeEducation":
                return (
                    <FinanceEducationStep
                        academicEducation={financeAcademicEducation}
                        professionalEducation={financeProfessionalEducation}
                        onAcademicChange={setFinanceAcademicEducation}
                        onProfessionalChange={setFinanceProfessionalEducation}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "bankingEducation":
                return (
                    <BankingEducationStep
                        academicEducation={bankingAcademicEducation}
                        professionalEducation={bankingProfessionalEducation}
                        specializedTraining={bankingSpecializedTraining}
                        onAcademicChange={setBankingAcademicEducation}
                        onProfessionalChange={setBankingProfessionalEducation}
                        onSpecializedChange={setBankingSpecializedTraining}
                        onNext={handleNext}
                        onPrevious={handlePrevious}
                    />
                );
            case "summary":
                return (
                    <SummaryStep
                        industry={industry}
                        basicInfo={basicInfo}
                        professionalSummary={professionalSummary}
                        onSummaryChange={setProfessionalSummary}
                        workExperiences={workExperiences}
                        educations={educations}
                        awards={awards}
                        projects={isITIndustry ? projects : undefined}
                        certificates={isITIndustry ? certificates : undefined}
                        financeAcademicEducation={isFinanceIndustry ? financeAcademicEducation : undefined}
                        financeProfessionalEducation={isFinanceIndustry ? financeProfessionalEducation : undefined}
                        bankingAcademicEducation={isBankingIndustry ? bankingAcademicEducation : undefined}
                        bankingProfessionalEducation={isBankingIndustry ? bankingProfessionalEducation : undefined}
                        bankingSpecializedTraining={isBankingIndustry ? bankingSpecializedTraining : undefined}
                        onSubmit={handleSubmit}
                        onPrevious={handlePrevious}
                        isLoading={isLoading}
                    />
                );
            default:
                return null;
        }
    };

    return (
        <div className="space-y-6">
            {/* Progress Header */}
            <Card>
                <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-base">
                            {steps[currentStep]?.title}
                        </CardTitle>
                        <span className="text-sm text-muted-foreground">
                            Step {currentStep + 1} of {totalSteps}
                        </span>
                    </div>
                </CardHeader>
                <CardContent className="pb-4">
                    <Progress value={progress} className="h-2" />
                    <div className="mt-2 flex justify-between text-xs text-muted-foreground">
                        {steps.map((step, index) => (
                            <span
                                key={step.id}
                                className={index <= currentStep ? "text-primary font-medium" : ""}
                            >
                                {index + 1}
                            </span>
                        ))}
                    </div>
                </CardContent>
            </Card>

            {/* Error Message */}
            {error && (
                <div className="rounded-lg bg-destructive/10 p-4 text-sm text-destructive">
                    {error}
                </div>
            )}

            {/* Current Step Content */}
            {renderStep()}
        </div>
    );
}

"use client";

import { Award } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { FormSection } from "../shared/FormSection";
import { DynamicList } from "../shared/DynamicList";
import { StepNavigation } from "../shared/StepNavigation";
import type { AwardData } from "@/lib/validations/profile-schema";
import { awardSchema } from "@/lib/validations/profile-schema";
import { useState } from "react";
import { z } from "zod";

interface AwardsStepProps {
    awards: AwardData[];
    onChange: (awards: AwardData[]) => void;
    onNext: () => void;
    onPrevious: () => void;
}

const emptyAward: AwardData = {
    natureOfAward: "",
    offeredBy: "",
    description: "",
};

export function AwardsStep({ awards, onChange, onNext, onPrevious }: AwardsStepProps) {
    const handleAdd = () => {
        onChange([...awards, { ...emptyAward }]);
    };

    const handleRemove = (index: number) => {
        onChange(awards.filter((_, i) => i !== index));
    };

    const handleUpdate = (index: number, field: keyof AwardData, value: string) => {
        const updated = [...awards];
        updated[index] = { ...updated[index], [field]: value };

        if (errors[`${index}.${field as string}`]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[`${index}.${field as string}`];
                return newErrors;
            });
        }

        onChange(updated);
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleNextStep = () => {
        const result = z.array(awardSchema).safeParse(awards);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Awards & Achievements"
                description="Highlight your recognitions and accomplishments (optional)"
            >
                <DynamicList
                    items={awards}
                    onAdd={handleAdd}
                    onRemove={handleRemove}
                    addLabel="Add Award"
                    emptyMessage="No awards added yet. This section is optional."
                    maxItems={100}
                    renderItem={(award, index) => (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <Label htmlFor={`natureOfAward-${index}`}>
                                    Award Name <span className="text-destructive">*</span>
                                </Label>
                                <Input
                                    id={`natureOfAward-${index}`}
                                    value={award.natureOfAward}
                                    onChange={(e) => handleUpdate(index, "natureOfAward", e.target.value)}
                                    placeholder="e.g., Employee of the Year"
                                />
                                {errors[`${index}.natureOfAward`] && <p className="text-sm text-destructive">{errors[`${index}.natureOfAward`]}</p>}
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`offeredBy-${index}`}>Offered By</Label>
                                <Input
                                    id={`offeredBy-${index}`}
                                    value={award.offeredBy || ""}
                                    onChange={(e) => handleUpdate(index, "offeredBy", e.target.value)}
                                    placeholder="Organization or institution"
                                />
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`description-${index}`}>Description</Label>
                                <Textarea
                                    id={`description-${index}`}
                                    value={award.description || ""}
                                    onChange={(e) => handleUpdate(index, "description", e.target.value)}
                                    placeholder="Brief description of the achievement"
                                    rows={2}
                                />
                            </div>
                        </div>
                    )}
                />
            </FormSection>

            <StepNavigation
                currentStep={5}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
            />
        </div>
    );
}

"use client";

import { User, Loader2, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Combobox } from "@/components/ui/combobox";
import { FormSection } from "../shared/FormSection";
import { StepNavigation } from "../shared/StepNavigation";
import type { BasicInfoData } from "@/lib/validations/profile-schema";
import { basicInfoSchema } from "@/lib/validations/profile-schema";
import { useJobDesignations, uniqueDesignationsByName } from "@/hooks/useJobDesignations";
import { useState } from "react";

interface BasicInfoStepProps {
    data: BasicInfoData;
    onChange: (data: BasicInfoData) => void;
    onNext: () => void;
    onPrevious: () => void;
    onImageSelect: (file: File | null) => void;
    industry?: string; // Selected industry from previous step
}

const EXPERIENCE_LEVELS = [
    { value: "entry", label: "Entry Level" },
    { value: "junior", label: "Junior" },
    { value: "mid", label: "Mid Level" },
    { value: "senior", label: "Senior" },
    { value: "lead", label: "Lead" },
    { value: "principal", label: "Principal" },
];

const AVAILABILITY_STATUSES = [
    { value: "available", label: "Actively Looking" },
    { value: "open_to_opportunities", label: "Open to Opportunities" },
    { value: "not_looking", label: "Not Currently Looking" },
];

const NOTICE_PERIODS = [
    { value: "immediate", label: "Immediate" },
    { value: "1_week", label: "1 Week" },
    { value: "2_weeks", label: "2 Weeks" },
    { value: "1_month", label: "1 Month" },
    { value: "2_months", label: "2 Months" },
    { value: "3_months", label: "3+ Months" },
];

const EMPLOYMENT_TYPES = [
    { value: "full_time", label: "Full Time" },
    { value: "part_time", label: "Part Time" },
    { value: "contract", label: "Contract" },
    { value: "internship", label: "Internship" },
    { value: "freelance", label: "Freelance" },
];

const COUNTRIES = [
    "Sri Lanka", "United States", "United Kingdom", "Canada",
    "Australia", "India", "Singapore", "United Arab Emirates", "Germany", "Other",
];

const QUALIFICATION_OPTIONS = [
    { value: "bachelors_degree", label: "Bachelor's Degree" },
    { value: "masters_degree", label: "Master's Degree" },
    { value: "doctorate_phd", label: "Doctorate/PhD" },
    { value: "undergraduate", label: "Undergraduate" },
    { value: "post_graduate", label: "Post Graduate" },
    { value: "diploma", label: "Diploma" },
    { value: "certificate", label: "Certificate" },
    { value: "professional_certification", label: "Professional Certification" },
    { value: "vocational_training", label: "Vocational Training" },
    { value: "no_formal_education", label: "No Formal Education" },
];

function FormField({
    label, id, required, children, error,
}: {
    label: React.ReactNode; id: string; required?: boolean; children: React.ReactNode; error?: string;
}) {
    return (
        <div className="space-y-2">
            <Label htmlFor={id}>
                {label}{required && <span className="text-destructive ml-1">*</span>}
            </Label>
            {children}
            {error && <p className="text-sm text-destructive">{error}</p>}
        </div>
    );
}

export function BasicInfoStep({ data, onChange, onNext, onPrevious, onImageSelect, industry }: BasicInfoStepProps) {
    const canLoadDesignations = Boolean(industry);

    // Job titles match the industry chosen on the previous step (resolved server-side from `industries`)
    const { jobDesignations, loading: loadingDesignations, error: designationsError } = useJobDesignations(industry);

    const designationOptions = uniqueDesignationsByName(jobDesignations);

    const [errors, setErrors] = useState<Record<string, string>>({});

    const updateField = <K extends keyof BasicInfoData>(key: K, value: BasicInfoData[K]) => {
        onChange({ ...data, [key]: value });
        // Clear error for this field when user types
        if (errors[key]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[key];
                return newErrors;
            });
        }
    };

    const handleNextStep = () => {
        const result = basicInfoSchema.safeParse(data);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) { // 5MB limit
                alert("File size must be less than 5MB");
                return;
            }
            if (!file.type.startsWith("image/")) {
                alert("Please upload an image file");
                return;
            }

            // Create object URL for preview
            const objectUrl = URL.createObjectURL(file);
            updateField("profileImageUrl", objectUrl);
            onImageSelect(file);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Personal Information"
                description="Your basic contact details"
            >
                <div className="space-y-4">
                    <div className="grid gap-4 md:grid-cols-2">
                        <FormField label="First Name" id="firstName" required error={errors.firstName}>
                            <Input
                                id="firstName"
                                value={data.firstName}
                                onChange={(e) => updateField("firstName", e.target.value)}
                                placeholder="John"
                                readOnly
                                className="bg-muted cursor-not-allowed"
                            />
                        </FormField>
                        <FormField label="Last Name" id="lastName" required error={errors.lastName}>
                            <Input
                                id="lastName"
                                value={data.lastName}
                                onChange={(e) => updateField("lastName", e.target.value)}
                                placeholder="Doe"
                                readOnly
                                className="bg-muted cursor-not-allowed"
                            />
                        </FormField>
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="shrink-0">
                            {data.profileImageUrl ? (
                                <img
                                    src={data.profileImageUrl}
                                    alt="Profile Preview"
                                    className="h-24 w-24 rounded-full object-cover border-2 border-primary/20"
                                />
                            ) : (
                                <div className="flex h-24 w-24 items-center justify-center rounded-full bg-muted border-2 border-dashed border-muted-foreground/25">
                                    <User className="h-8 w-8 text-muted-foreground" />
                                </div>
                            )}
                        </div>
                        <div className="space-y-1">
                            <Label htmlFor="profileImage" className="text-base font-medium">Profile Picture</Label>
                            <p className="text-sm text-muted-foreground pb-2">
                                Upload a professional picture (Max 5MB)
                            </p>
                            <Input
                                id="profileImage"
                                type="file"
                                accept="image/*"
                                onChange={handleImageChange}
                                className="w-full max-w-xs"
                            />
                        </div>
                    </div>

                    <div className="grid gap-4 md:grid-cols-2">
                        <FormField label="Email" id="email" required error={errors.email}>
                            <Input
                                id="email"
                                type="email"
                                value={data.email}
                                onChange={(e) => updateField("email", e.target.value)}
                                placeholder="john@example.com"
                                readOnly
                                className="bg-muted cursor-not-allowed"
                            />
                        </FormField>
                        <FormField label={<>Phone <span className="text-xs text-muted-foreground font-normal ml-1">( Format: +94XXXXXXXXX )</span></>} id="phone" required error={errors.phone}>
                            <Input
                                id="phone"
                                value={data.phone}
                                maxLength={15}
                                onChange={(e) => updateField("phone", e.target.value)}
                                placeholder="+94771234567"
                            />
                        </FormField>
                    </div>

                    <FormField label={<>Alternative Phone <span className="text-xs text-muted-foreground font-normal ml-1">( Format: +94XXXXXXXXX )</span></>} id="alternativePhone" error={errors.alternativePhone}>
                        <Input
                            id="alternativePhone"
                            value={data.alternativePhone}
                            maxLength={15}
                            onChange={(e) => updateField("alternativePhone", e.target.value)}
                            placeholder="+94771234567 (Optional)"
                        />
                    </FormField>

                    <FormField label="Address" id="address" required error={errors.address}>
                        <Textarea
                            id="address"
                            value={data.address}
                            onChange={(e) => updateField("address", e.target.value)}
                            placeholder="Your full address"
                            rows={2}
                        />
                    </FormField>

                    <FormField label="Country" id="country" error={errors.country}>
                        <Select
                            value={data.country}
                            onValueChange={(value) => updateField("country", value)}
                        >
                            <SelectTrigger id="country">
                                <SelectValue placeholder="Select country" />
                            </SelectTrigger>
                            <SelectContent>
                                {COUNTRIES.map((country) => (
                                    <SelectItem key={country} value={country}>
                                        {country}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </FormField>
                </div>
            </FormSection>

            <FormSection
                title="Professional Details"
                description="Your current role and experience"
            >
                <div className="space-y-4">
                    <FormField label="Current Position" id="currentPosition" required error={errors.currentPosition}>
                        {!canLoadDesignations ? (
                            <div className="space-y-2">
                                <p className="text-sm text-muted-foreground">
                                    Select your industry in the previous step (Industry &amp; CV) to see job titles for that sector.
                                </p>
                                <Input
                                    id="currentPosition"
                                    value={data.currentPosition}
                                    onChange={(e) => updateField("currentPosition", e.target.value)}
                                    placeholder="e.g., Software Engineer"
                                />
                            </div>
                        ) : loadingDesignations ? (
                            <div className="flex items-center gap-2 p-2 text-sm text-muted-foreground">
                                <Loader2 className="h-4 w-4 animate-spin" />
                                Loading job designations...
                            </div>
                        ) : designationsError ? (
                            <div className="space-y-2">
                                <p className="text-sm text-destructive">
                                    Failed to load job designations. You can enter manually.
                                </p>
                                <Input
                                    id="currentPosition"
                                    value={data.currentPosition}
                                    onChange={(e) => updateField("currentPosition", e.target.value)}
                                    placeholder="e.g., Software Engineer"
                                />
                            </div>
                        ) : (
                            <Combobox
                                options={designationOptions.map((designation) => ({
                                    value: designation.designation_name,
                                    label: designation.designation_name,
                                }))}
                                value={data.currentPosition}
                                onValueChange={(value) => updateField("currentPosition", value)}
                                placeholder="Select your current position"
                                searchPlaceholder="Search job titles..."
                                emptyMessage="No job title found for your industry."
                            />
                        )}
                    </FormField>

                    <div className="grid gap-4 md:grid-cols-2">
                        <FormField label="Years of Experience" id="yearsOfExperience" error={errors.yearsOfExperience}>
                            <Input
                                id="yearsOfExperience"
                                type="number"
                                min="0"
                                max="50"
                                step="1"
                                value={data.yearsOfExperience || ""}
                                onChange={(e) => {
                                    const value = e.target.value;
                                    // Only accept integers (no decimals)
                                    if (value === "" || /^\d+$/.test(value)) {
                                        updateField("yearsOfExperience", value === "" ? 0 : parseInt(value));
                                    }
                                }}
                                placeholder="Enter years"
                            />
                        </FormField>
                        <FormField label="Current Experience Level" id="experienceLevel" error={errors.experienceLevel}>
                            <Select
                                value={data.experienceLevel}
                                onValueChange={(value) => updateField("experienceLevel", value as BasicInfoData["experienceLevel"])}
                            >
                                <SelectTrigger id="experienceLevel">
                                    <SelectValue placeholder="Select level" />
                                </SelectTrigger>
                                <SelectContent>
                                    {EXPERIENCE_LEVELS.map((level) => (
                                        <SelectItem key={level.value} value={level.value}>
                                            {level.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </FormField>
                    </div>

                    <FormField label="Highest Qualification" id="highestQualification" error={errors.highestQualification}>
                        <Select
                            value={data.highestQualification}
                            onValueChange={(value) => updateField("highestQualification", value as BasicInfoData["highestQualification"])}
                        >
                            <SelectTrigger id="highestQualification">
                                <SelectValue placeholder="Select highest qualification" />
                            </SelectTrigger>
                            <SelectContent>
                                {QUALIFICATION_OPTIONS.map((qualification) => (
                                    <SelectItem key={qualification.value} value={qualification.value}>
                                        {qualification.label}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </FormField>
                </div>
            </FormSection>

            <FormSection
                title="Job Preferences"
                description="Your availability and expectations"
            >
                <div className="space-y-4">
                    <div className="grid gap-4 md:grid-cols-2">
                        <FormField label="Availability Status" id="availabilityStatus" error={errors.availabilityStatus}>
                            <Select
                                value={data.availabilityStatus}
                                onValueChange={(value) => updateField("availabilityStatus", value as BasicInfoData["availabilityStatus"])}
                            >
                                <SelectTrigger id="availabilityStatus">
                                    <SelectValue placeholder="Select status" />
                                </SelectTrigger>
                                <SelectContent>
                                    {AVAILABILITY_STATUSES.map((status) => (
                                        <SelectItem key={status.value} value={status.value}>
                                            {status.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </FormField>
                        <FormField label="Notice Period" id="noticePeriod" error={errors.noticePeriod}>
                            <Select
                                value={data.noticePeriod}
                                onValueChange={(value) => updateField("noticePeriod", value)}
                            >
                                <SelectTrigger id="noticePeriod">
                                    <SelectValue placeholder="Select period" />
                                </SelectTrigger>
                                <SelectContent>
                                    {NOTICE_PERIODS.map((period) => (
                                        <SelectItem key={period.value} value={period.value}>
                                            {period.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </FormField>
                    </div>

                    <div className="grid gap-4 md:grid-cols-2">
                        <FormField label="Employment Type" id="employmentType" error={errors.employmentType}>
                            <Select
                                value={data.employmentType}
                                onValueChange={(value) => updateField("employmentType", value as BasicInfoData["employmentType"])}
                            >
                                <SelectTrigger id="employmentType">
                                    <SelectValue placeholder="Select type" />
                                </SelectTrigger>
                                <SelectContent>
                                    {EMPLOYMENT_TYPES.map((type) => (
                                        <SelectItem key={type.value} value={type.value}>
                                            {type.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </FormField>
                        <FormField label="Expected Monthly Salary (LKR)" id="expectedMonthlySalary" error={errors.expectedMonthlySalary}>
                            <Input
                                id="expectedMonthlySalary"
                                type="number"
                                min="0"
                                value={data.expectedMonthlySalary || ""}
                                onChange={(e) => updateField("expectedMonthlySalary", parseInt(e.target.value) || 0)}
                                placeholder="e.g., 150000"
                            />
                        </FormField>
                    </div>

                    {/* Expected Job Positions */}
                    <FormField
                        label={
                            <>
                                Expected Job Positions
                                <span className="text-xs text-muted-foreground font-normal ml-1">
                                    (Up to 3)
                                </span>
                            </>
                        }
                        id="expectedPositions"
                        required
                        error={errors["expectedPositions"]}
                    >
                        <div className="space-y-2">
                            {/* Selected position tags */}
                            {(data.expectedPositions ?? []).length > 0 && (
                                <div className="flex flex-wrap gap-2">
                                    {(data.expectedPositions ?? []).map((pos, idx) => (
                                        <span
                                            key={idx}
                                            className="inline-flex items-center gap-1 rounded-full border border-primary/30 bg-primary/10 px-3 py-1 text-sm font-medium text-primary"
                                        >
                                            {pos}
                                            <button
                                                type="button"
                                                aria-label={`Remove ${pos}`}
                                                onClick={() => {
                                                    const updated = (data.expectedPositions ?? []).filter((_, i) => i !== idx);
                                                    updateField("expectedPositions", updated);
                                                }}
                                                className="ml-0.5 rounded-full p-0.5 hover:bg-primary/20 transition-colors"
                                            >
                                                <X className="h-3 w-3" />
                                            </button>
                                        </span>
                                    ))}
                                </div>
                            )}

                            {/* Combobox to add positions */}
                            {(data.expectedPositions ?? []).length >= 3 ? (
                                <p className="text-xs text-muted-foreground py-2">
                                    Maximum of 3 positions reached. Remove one to add another.
                                </p>
                            ) : !canLoadDesignations ? (
                                <Input
                                    id="expectedPositions"
                                    placeholder="Type a position and press Enter"
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter") {
                                            e.preventDefault();
                                            const val = (e.target as HTMLInputElement).value.trim();
                                            if (val && !(data.expectedPositions ?? []).includes(val)) {
                                                updateField("expectedPositions", [...(data.expectedPositions ?? []), val]);
                                                (e.target as HTMLInputElement).value = "";
                                            }
                                        }
                                    }}
                                />
                            ) : loadingDesignations ? (
                                <div className="flex items-center gap-2 p-2 text-sm text-muted-foreground">
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Loading job designations...
                                </div>
                            ) : designationsError ? (
                                <Input
                                    id="expectedPositions"
                                    placeholder="Type a position and press Enter"
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter") {
                                            e.preventDefault();
                                            const val = (e.target as HTMLInputElement).value.trim();
                                            if (val && !(data.expectedPositions ?? []).includes(val)) {
                                                updateField("expectedPositions", [...(data.expectedPositions ?? []), val]);
                                                (e.target as HTMLInputElement).value = "";
                                            }
                                        }
                                    }}
                                />
                            ) : (
                                <Combobox
                                    options={designationOptions
                                        .filter((d) => !(data.expectedPositions ?? []).includes(d.designation_name))
                                        .map((designation) => ({
                                            value: designation.designation_name,
                                            label: designation.designation_name,
                                        }))}
                                    value=""
                                    onValueChange={(value) => {
                                        if (value && !(data.expectedPositions ?? []).includes(value)) {
                                            updateField("expectedPositions", [...(data.expectedPositions ?? []), value]);
                                        }
                                    }}
                                    placeholder="Search and select a position"
                                    searchPlaceholder="Search job titles..."
                                    emptyMessage="No job title found for your industry."
                                />
                            )}
                        </div>
                    </FormField>
                </div>
            </FormSection>

            <StepNavigation
                currentStep={2}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
                canProceed={true}
            />
        </div >
    );
}

"use client";

import { Medal } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { FormSection } from "../shared/FormSection";
import { DynamicList } from "../shared/DynamicList";
import { StepNavigation } from "../shared/StepNavigation";
import type { CertificateData } from "@/lib/validations/profile-schema";
import { certificateSchema } from "@/lib/validations/profile-schema";
import { useState } from "react";
import { z } from "zod";

interface CertificatesStepProps {
    certificates: CertificateData[];
    onChange: (certificates: CertificateData[]) => void;
    onNext: () => void;
    onPrevious: () => void;
}

const emptyCertificate: CertificateData = {
    certificateName: "",
    issuingAuthority: "",
    issueDate: "",
    expiryDate: null,
    credentialId: "",
    credentialUrl: "",
    description: "",
};

export function CertificatesStep({ certificates, onChange, onNext, onPrevious }: CertificatesStepProps) {
    const handleAdd = () => {
        onChange([...certificates, { ...emptyCertificate }]);
    };

    const handleRemove = (index: number) => {
        onChange(certificates.filter((_, i) => i !== index));
    };

    const handleUpdate = (index: number, field: keyof CertificateData, value: unknown) => {
        const updated = [...certificates];
        updated[index] = { ...updated[index], [field]: value };

        if (errors[`${index}.${field as string}`]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[`${index}.${field as string}`];
                return newErrors;
            });
        }

        onChange(updated);
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleNextStep = () => {
        const result = z.array(certificateSchema).safeParse(certificates);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Certifications"
                description="Add your professional certifications (AWS, Azure, Google, etc.)"
            >
                <DynamicList
                    items={certificates}
                    onAdd={handleAdd}
                    onRemove={handleRemove}
                    addLabel="Add Certificate"
                    emptyMessage="No certificates added yet. Add your professional certifications."
                    maxItems={100}
                    renderItem={(cert, index) => (
                        <div className="space-y-4">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`certificateName-${index}`}>
                                        Certificate Name <span className="text-destructive">*</span>
                                    </Label>
                                    <Input
                                        id={`certificateName-${index}`}
                                        value={cert.certificateName}
                                        onChange={(e) => handleUpdate(index, "certificateName", e.target.value)}
                                        placeholder="e.g., AWS Solutions Architect"
                                    />
                                    {errors[`${index}.certificateName`] && <p className="text-sm text-destructive">{errors[`${index}.certificateName`]}</p>}
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`issuingAuthority-${index}`}>Issuing Authority</Label>
                                    <Input
                                        id={`issuingAuthority-${index}`}
                                        value={cert.issuingAuthority || ""}
                                        onChange={(e) => handleUpdate(index, "issuingAuthority", e.target.value)}
                                        placeholder="e.g., Amazon Web Services"
                                    />
                                    {errors[`${index}.issuingAuthority`] && <p className="text-sm text-destructive">{errors[`${index}.issuingAuthority`]}</p>}
                                </div>
                            </div>

                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`issueDate-${index}`}>Issue Date</Label>
                                    <Input
                                        id={`issueDate-${index}`}
                                        type="date"
                                        value={cert.issueDate || ""}
                                        onChange={(e) => handleUpdate(index, "issueDate", e.target.value)}
                                    />
                                    {errors[`${index}.issueDate`] && <p className="text-sm text-destructive">{errors[`${index}.issueDate`]}</p>}
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`expiryDate-${index}`}>Expiry Date</Label>
                                    <Input
                                        id={`expiryDate-${index}`}
                                        type="date"
                                        value={cert.expiryDate || ""}
                                        onChange={(e) => handleUpdate(index, "expiryDate", e.target.value)}
                                    />
                                    {errors[`${index}.expiryDate`] && <p className="text-sm text-destructive">{errors[`${index}.expiryDate`]}</p>}
                                </div>
                            </div>

                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`credentialId-${index}`}>Credential ID</Label>
                                    <Input
                                        id={`credentialId-${index}`}
                                        value={cert.credentialId || ""}
                                        onChange={(e) => handleUpdate(index, "credentialId", e.target.value)}
                                        placeholder="Certificate ID"
                                    />
                                    {errors[`${index}.credentialId`] && <p className="text-sm text-destructive">{errors[`${index}.credentialId`]}</p>}
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`credentialUrl-${index}`}>Credential URL</Label>
                                    <Input
                                        id={`credentialUrl-${index}`}
                                        value={cert.credentialUrl || ""}
                                        onChange={(e) => handleUpdate(index, "credentialUrl", e.target.value)}
                                        placeholder="https://verify.example.com/..."
                                    />
                                    {errors[`${index}.credentialUrl`] && <p className="text-sm text-destructive">{errors[`${index}.credentialUrl`]}</p>}
                                </div>
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`description-${index}`}>Description</Label>
                                <Textarea
                                    id={`description-${index}`}
                                    value={cert.description || ""}
                                    onChange={(e) => handleUpdate(index, "description", e.target.value)}
                                    placeholder="Brief description (optional)"
                                    rows={2}
                                />
                            </div>
                        </div>
                    )}
                />
            </FormSection>

            <StepNavigation
                currentStep={7}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
            />
        </div>
    );
}

"use client";

import { GraduationCap } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { FormSection } from "../shared/FormSection";
import { DynamicList } from "../shared/DynamicList";
import { StepNavigation } from "../shared/StepNavigation";
import type { EducationData } from "@/lib/validations/profile-schema";
import { ACADEMIC_EDUCATION_STATUSES, PROFESSIONAL_EDUCATION_STATUSES, educationSchema } from "@/lib/validations/profile-schema";
import { useState } from "react";
import { z } from "zod";

interface EducationStepProps {
    educations: EducationData[];
    onChange: (educations: EducationData[]) => void;
    onNext: () => void;
    onPrevious: () => void;
}

const EDUCATION_TYPES = [
    { value: "academic", label: "Academic" },
    { value: "professional", label: "Professional" },
];



const emptyEducation: EducationData = {
    educationType: "academic",
    degreeDiploma: "",
    institution: "",
    status: "incomplete", // Changed to match schema
};

export function EducationStep({ educations, onChange, onNext, onPrevious }: EducationStepProps) {
    const handleAdd = () => {
        onChange([...educations, { ...emptyEducation }]);
    };

    const handleRemove = (index: number) => {
        onChange(educations.filter((_, i) => i !== index));
    };

    const handleUpdate = (index: number, field: keyof EducationData, value: unknown) => {
        const updated = [...educations];
        updated[index] = { ...updated[index], [field]: value };

        if (errors[`${index}.${field as string}`]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[`${index}.${field as string}`];
                return newErrors;
            });
        }

        onChange(updated);
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleNextStep = () => {
        // Filter out incomplete entries (must have BOTH institution and degreeDiploma)
        const nonEmptyEducations = educations.filter(
            (edu) => edu.institution.trim() !== "" && edu.degreeDiploma.trim() !== ""
        );

        // If items were removed, update the parent state
        if (nonEmptyEducations.length !== educations.length) {
            onChange(nonEmptyEducations);
        }

        const result = z.array(educationSchema).safeParse(nonEmptyEducations);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Education"
                description="Add your academic and professional qualifications"
            >
                <DynamicList
                    items={educations}
                    onAdd={handleAdd}
                    onRemove={handleRemove}
                    addLabel="Add Education"
                    emptyMessage="No education added yet. Click below to add your qualifications."
                    maxItems={100}
                    renderItem={(edu, index) => (
                        <div className="space-y-4">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`educationType-${index}`}>Type</Label>
                                    <Select
                                        value={edu.educationType}
                                        onValueChange={(value) => handleUpdate(index, "educationType", value)}
                                    >
                                        <SelectTrigger id={`educationType-${index}`}>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {EDUCATION_TYPES.map((type) => (
                                                <SelectItem key={type.value} value={type.value}>
                                                    {type.label}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`status-${index}`}>Status</Label>
                                    <div className="flex gap-2">
                                        <Select
                                            value={
                                                edu.educationType === "academic"
                                                    ? ACADEMIC_EDUCATION_STATUSES.some(s => s.value === edu.status)
                                                        ? edu.status
                                                        : "other"
                                                    : PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === edu.status)
                                                        ? edu.status
                                                        : "other"
                                            }
                                            onValueChange={(value) => {
                                                if (value !== "other") {
                                                    handleUpdate(index, "status", value);
                                                } else {
                                                    handleUpdate(index, "status", "");
                                                }
                                            }}
                                        >
                                            <SelectTrigger id={`status-${index}`} className={(edu.educationType === "academic" && !ACADEMIC_EDUCATION_STATUSES.some(s => s.value === edu.status)) || (edu.educationType === "professional" && !PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === edu.status)) ? "w-[40%]" : "w-full"}>
                                                <SelectValue placeholder="Select Status" />
                                            </SelectTrigger>
                                            <SelectContent>
                                                {edu.educationType === "academic"
                                                    ? [
                                                        ...ACADEMIC_EDUCATION_STATUSES,
                                                        { value: "other", label: "Other (Please specify)" }
                                                    ].map((status) => (
                                                        <SelectItem key={status.value} value={status.value}>
                                                            {status.label}
                                                        </SelectItem>
                                                    ))
                                                    : [
                                                        ...PROFESSIONAL_EDUCATION_STATUSES,
                                                        { value: "other", label: "Other (Please specify)" }
                                                    ].map((status) => (
                                                        <SelectItem key={status.value} value={status.value}>
                                                            {status.label}
                                                        </SelectItem>
                                                    ))
                                                }
                                            </SelectContent>
                                        </Select>

                                        {/* Show text input if custom value or 'other' is selected */}
                                        {(
                                            edu.educationType === "academic" && !ACADEMIC_EDUCATION_STATUSES.some(s => s.value === edu.status)
                                            ||
                                            edu.educationType === "professional" && !PROFESSIONAL_EDUCATION_STATUSES.some(s => s.value === edu.status)
                                        ) && (
                                                <Input
                                                    id={`status-custom-${index}`}
                                                    value={edu.status}
                                                    onChange={(e) => handleUpdate(index, "status", e.target.value)}
                                                    placeholder="Specify status..."
                                                    className="flex-1"
                                                />
                                            )}
                                    </div>
                                    {errors[`${index}.status`] && <p className="text-sm text-destructive">{errors[`${index}.status`]}</p>}
                                </div>
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`degreeDiploma-${index}`}>
                                    Degree / Diploma <span className="text-destructive">*</span>
                                </Label>
                                <Input
                                    id={`degreeDiploma-${index}`}
                                    value={edu.degreeDiploma}
                                    onChange={(e) => handleUpdate(index, "degreeDiploma", e.target.value)}
                                    placeholder="e.g., BSc in Computer Science"
                                />
                                {errors[`${index}.degreeDiploma`] && <p className="text-sm text-destructive">{errors[`${index}.degreeDiploma`]}</p>}
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`institution-${index}`}>
                                    Institution <span className="text-destructive">*</span>
                                </Label>
                                <Input
                                    id={`institution-${index}`}
                                    value={edu.institution}
                                    onChange={(e) => handleUpdate(index, "institution", e.target.value)}
                                    placeholder="e.g., University of Colombo"
                                />
                                {errors[`${index}.institution`] && <p className="text-sm text-destructive">{errors[`${index}.institution`]}</p>}
                            </div>
                        </div>
                    )}
                />
            </FormSection>

            <StepNavigation
                currentStep={4}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
            />
        </div>
    );
}

"use client";

import { Briefcase } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { FormSection } from "../shared/FormSection";
import { DynamicList } from "../shared/DynamicList";
import { StepNavigation } from "../shared/StepNavigation";
import type { WorkExperienceData } from "@/lib/validations/profile-schema";
import { workExperienceSchema } from "@/lib/validations/profile-schema";
import { useState } from "react";
import { z } from "zod";

interface ExperienceStepProps {
    experiences: WorkExperienceData[];
    onChange: (experiences: WorkExperienceData[]) => void;
    onNext: () => void;
    onPrevious: () => void;
}

const EMPLOYMENT_TYPES = [
    { value: "full_time", label: "Full Time" },
    { value: "part_time", label: "Part Time" },
    { value: "contract", label: "Contract" },
    { value: "internship", label: "Internship" },
    { value: "freelance", label: "Freelance" },
];

const LOCATION_TYPES = [
    { value: "onsite", label: "On-site" },
    { value: "remote", label: "Remote" },
    { value: "hybrid", label: "Hybrid" },
];

const emptyExperience: WorkExperienceData = {
    jobTitle: "",
    company: "",
    employmentType: "full_time",
    location: "",
    locationType: "onsite",
    startDate: "",
    endDate: null,
    description: "",
    isCurrent: false,
};

export function ExperienceStep({ experiences, onChange, onNext, onPrevious }: ExperienceStepProps) {
    const handleAdd = () => {
        onChange([...experiences, { ...emptyExperience }]);
    };

    const handleRemove = (index: number) => {
        onChange(experiences.filter((_, i) => i !== index));
    };

    const handleUpdate = (index: number, field: keyof WorkExperienceData, value: unknown) => {
        const updated = [...experiences];
        updated[index] = { ...updated[index], [field]: value };

        // Clear error if present
        if (errors[`${index}.${field as string}`]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[`${index}.${field as string}`];
                return newErrors;
            });
        }

        // Clear end date if current is toggled on
        if (field === "isCurrent" && value === true) {
            updated[index].endDate = null;
        }

        onChange(updated);
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleNextStep = () => {
        const result = z.array(workExperienceSchema).safeParse(experiences);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Work Experience"
                description="Add your work history, starting with the most recent position"
            >
                <DynamicList
                    items={experiences}
                    onAdd={handleAdd}
                    onRemove={handleRemove}
                    addLabel="Add Experience"
                    emptyMessage="No work experience added yet. Click below to add your first position."
                    maxItems={100}
                    renderItem={(exp, index) => (
                        <div className="space-y-4">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`jobTitle-${index}`}>
                                        Job Title <span className="text-destructive">*</span>
                                    </Label>
                                    <Input
                                        id={`jobTitle-${index}`}
                                        value={exp.jobTitle}
                                        onChange={(e) => handleUpdate(index, "jobTitle", e.target.value)}
                                        placeholder="e.g., Senior Developer"
                                    />
                                    {errors[`${index}.jobTitle`] && <p className="text-sm text-destructive">{errors[`${index}.jobTitle`]}</p>}
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`company-${index}`}>
                                        Company <span className="text-destructive">*</span>
                                    </Label>
                                    <Input
                                        id={`company-${index}`}
                                        value={exp.company}
                                        onChange={(e) => handleUpdate(index, "company", e.target.value)}
                                        placeholder="Company name"
                                    />
                                    {errors[`${index}.company`] && <p className="text-sm text-destructive">{errors[`${index}.company`]}</p>}
                                </div>
                            </div>

                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`employmentType-${index}`}>Employment Type</Label>
                                    <Select
                                        value={exp.employmentType}
                                        onValueChange={(value) => handleUpdate(index, "employmentType", value)}
                                    >
                                        <SelectTrigger id={`employmentType-${index}`}>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {EMPLOYMENT_TYPES.map((type) => (
                                                <SelectItem key={type.value} value={type.value}>
                                                    {type.label}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`locationType-${index}`}>Location Type</Label>
                                    <Select
                                        value={exp.locationType}
                                        onValueChange={(value) => handleUpdate(index, "locationType", value)}
                                    >
                                        <SelectTrigger id={`locationType-${index}`}>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {LOCATION_TYPES.map((type) => (
                                                <SelectItem key={type.value} value={type.value}>
                                                    {type.label}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`location-${index}`}>Location</Label>
                                <Input
                                    id={`location-${index}`}
                                    value={exp.location || ""}
                                    onChange={(e) => handleUpdate(index, "location", e.target.value)}
                                    placeholder="e.g., Colombo, Sri Lanka"
                                />
                                {errors[`${index}.location`] && <p className="text-sm text-destructive">{errors[`${index}.location`]}</p>}
                            </div>

                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor={`startDate-${index}`}>Start Month</Label>
                                    <Input
                                        id={`startDate-${index}`}
                                        type="month"
                                        value={exp.startDate || ""}
                                        onChange={(e) => handleUpdate(index, "startDate", e.target.value)}
                                    />
                                    {errors[`${index}.startDate`] && <p className="text-sm text-destructive">{errors[`${index}.startDate`]}</p>}
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor={`endDate-${index}`}>End Month</Label>
                                    <Input
                                        id={`endDate-${index}`}
                                        type="month"
                                        value={exp.endDate || ""}
                                        onChange={(e) => handleUpdate(index, "endDate", e.target.value)}
                                        disabled={exp.isCurrent}
                                    />
                                    {errors[`${index}.endDate`] && <p className="text-sm text-destructive">{errors[`${index}.endDate`]}</p>}
                                </div>
                            </div>

                            <div className="flex items-center space-x-2">
                                <Switch
                                    id={`isCurrent-${index}`}
                                    checked={exp.isCurrent}
                                    onCheckedChange={(checked) => handleUpdate(index, "isCurrent", checked)}
                                />
                                <Label htmlFor={`isCurrent-${index}`}>I currently work here</Label>
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`description-${index}`}>Description</Label>
                                <Textarea
                                    id={`description-${index}`}
                                    value={exp.description || ""}
                                    onChange={(e) => handleUpdate(index, "description", e.target.value)}
                                    placeholder="Describe your responsibilities and achievements"
                                    rows={3}
                                />
                            </div>
                        </div>
                    )}
                />
            </FormSection>

            <StepNavigation
                currentStep={3}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
            />
        </div>
    );
}

"use client";

import { useState } from "react";
import { Building2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { CVUpload } from "../CVUpload";
import { INDUSTRY_OPTIONS } from "@/lib/validations/profile-schema";
import type { CVExtractionResult } from "@/lib/validations/profile-schema";
import { cn } from "@/lib/utils";

interface IndustryStepProps {
    industry: string;
    onIndustryChange: (industry: string) => void;
    onCVExtracted: (data: CVExtractionResult) => void;
    onFileSelect: (file: File | null) => void;
    onSkipCV: () => void;
    onNext: () => void;
}

export function IndustryStep({
    industry,
    onIndustryChange,
    onCVExtracted,
    onFileSelect,
    onSkipCV,
    onNext,
}: IndustryStepProps) {
    const [showCVUpload, setShowCVUpload] = useState(false);

    const handleIndustrySelect = (value: string) => {
        onIndustryChange(value);
    };

    const handleContinue = () => {
        if (industry) {
            setShowCVUpload(true);
        }
    };

    if (showCVUpload) {
        return (
            <div className="space-y-6">
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Building2 className="h-5 w-5" />
                            Upload Your CV
                        </CardTitle>
                        <CardDescription>
                            Upload your CV to auto-fill your profile, or skip to enter manually
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <CVUpload
                            onExtracted={onCVExtracted}
                            onFileSelect={onFileSelect}
                            onSkip={onSkipCV}
                        />
                    </CardContent>
                </Card>

                <div className="flex justify-start">
                    <Button
                        variant="ghost"
                        onClick={() => setShowCVUpload(false)}
                    >
                        Back to Industry Selection
                    </Button>
                </div>
            </div>
        );
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle className="flex items-center gap-2">
                    <Building2 className="h-5 w-5" />
                    Select Your Industry
                </CardTitle>
                <CardDescription>
                    Choose the industry that best matches your profession. This will customize your profile sections.
                </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
                <RadioGroup
                    value={industry}
                    onValueChange={handleIndustrySelect}
                    className="grid gap-3 md:grid-cols-2"
                >
                    {INDUSTRY_OPTIONS.map((option) => (
                        <Label
                            key={option.value}
                            htmlFor={option.value}
                            className={cn(
                                "flex cursor-pointer items-center gap-3 rounded-lg border p-4 transition-colors",
                                industry === option.value
                                    ? "border-primary bg-primary/5"
                                    : "border-border hover:bg-muted/50"
                            )}
                        >
                            <RadioGroupItem value={option.value} id={option.value} />
                            <span className="font-medium">{option.label}</span>
                        </Label>
                    ))}
                </RadioGroup>

                <div className="flex justify-end pt-4 border-t">
                    <Button
                        onClick={handleContinue}
                        disabled={!industry}
                    >
                        Continue
                    </Button>
                </div>
            </CardContent>
        </Card>
    );
}

"use client";

import { FolderGit2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { FormSection } from "../shared/FormSection";
import { DynamicList } from "../shared/DynamicList";
import { StepNavigation } from "../shared/StepNavigation";
import type { ProjectData } from "@/lib/validations/profile-schema";
import { projectSchema } from "@/lib/validations/profile-schema";
import { useState } from "react";
import { z } from "zod";

interface ProjectsStepProps {
    projects: ProjectData[];
    onChange: (projects: ProjectData[]) => void;
    onNext: () => void;
    onPrevious: () => void;
}

const emptyProject: ProjectData = {
    projectName: "",
    description: "",
    demoUrl: "",
    isCurrent: false,
};

export function ProjectsStep({ projects, onChange, onNext, onPrevious }: ProjectsStepProps) {
    const handleAdd = () => {
        onChange([...projects, { ...emptyProject }]);
    };

    const handleRemove = (index: number) => {
        onChange(projects.filter((_, i) => i !== index));
    };

    const handleUpdate = (index: number, field: keyof ProjectData, value: unknown) => {
        const updated = [...projects];
        updated[index] = { ...updated[index], [field]: value };

        if (errors[`${index}.${field as string}`]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[`${index}.${field as string}`];
                return newErrors;
            });
        }

        onChange(updated);
    };

    const [errors, setErrors] = useState<Record<string, string>>({});

    const handleNextStep = () => {
        const result = z.array(projectSchema).safeParse(projects);
        if (result.success) {
            setErrors({});
            onNext();
        } else {
            const newErrors: Record<string, string> = {};
            result.error.issues.forEach(issue => {
                const pathKey = issue.path.join('.');
                newErrors[pathKey] = issue.message;
            });
            setErrors(newErrors);
        }
    };

    return (
        <div className="space-y-6">
            <FormSection
                title="Projects"
                description="Showcase your key projects (for IT professionals)"
            >
                <DynamicList
                    items={projects}
                    onAdd={handleAdd}
                    onRemove={handleRemove}
                    addLabel="Add Project"
                    emptyMessage="No projects added yet. Add projects to showcase your work."
                    maxItems={100}
                    renderItem={(project, index) => (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <Label htmlFor={`projectName-${index}`}>
                                    Project Name <span className="text-destructive">*</span>
                                </Label>
                                <Input
                                    id={`projectName-${index}`}
                                    value={project.projectName}
                                    onChange={(e) => handleUpdate(index, "projectName", e.target.value)}
                                    placeholder="e.g., E-commerce Platform"
                                />
                                {errors[`${index}.projectName`] && <p className="text-sm text-destructive">{errors[`${index}.projectName`]}</p>}
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`description-${index}`}>Description</Label>
                                <Textarea
                                    id={`description-${index}`}
                                    value={project.description || ""}
                                    onChange={(e) => handleUpdate(index, "description", e.target.value)}
                                    placeholder="Technologies used, your role, key features..."
                                    rows={3}
                                />
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor={`demoUrl-${index}`}>Demo / GitHub URL</Label>
                                <Input
                                    id={`demoUrl-${index}`}
                                    value={project.demoUrl || ""}
                                    onChange={(e) => handleUpdate(index, "demoUrl", e.target.value)}
                                    placeholder="https://github.com/username/project"
                                />
                                {errors[`${index}.demoUrl`] && <p className="text-sm text-destructive">{errors[`${index}.demoUrl`]}</p>}
                            </div>

                            <div className="flex items-center space-x-2">
                                <Switch
                                    id={`isCurrent-${index}`}
                                    checked={project.isCurrent}
                                    onCheckedChange={(checked) => handleUpdate(index, "isCurrent", checked)}
                                />
                                <Label htmlFor={`isCurrent-${index}`}>Currently working on this</Label>
                            </div>
                        </div>
                    )}
                />
            </FormSection>

            <StepNavigation
                currentStep={6}
                totalSteps={10}
                onPrevious={onPrevious}
                onNext={handleNextStep}
            />
        </div>
    );
}

"use client";

import { useState } from "react";
import { FileCheck2, Loader2, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { FormSection } from "../shared/FormSection";
import { StepNavigation } from "../shared/StepNavigation";
import { generateProfessionalSummary } from "@/app/actions/extract-cv";
import { INDUSTRY_OPTIONS, IT_INDUSTRIES } from "@/lib/validations/profile-schema";
import type {
    BasicInfoData,
    WorkExperienceData,
    EducationData,
    AwardData,
    ProjectData,
    CertificateData,
    FinanceAcademicEducationData,
    FinanceProfessionalEducationData,
    BankingAcademicEducationData,
    BankingProfessionalEducationData,
    BankingSpecializedTrainingData,
} from "@/lib/validations/profile-schema";

interface SummaryStepProps {
    industry: string;
    basicInfo: BasicInfoData;
    professionalSummary: string;
    onSummaryChange: (summary: string) => void;
    workExperiences: WorkExperienceData[];
    educations: EducationData[];
    awards: AwardData[];
    projects?: ProjectData[];
    certificates?: CertificateData[];
    financeAcademicEducation?: FinanceAcademicEducationData[];
    financeProfessionalEducation?: FinanceProfessionalEducationData[];
    bankingAcademicEducation?: BankingAcademicEducationData[];
    bankingProfessionalEducation?: BankingProfessionalEducationData[];
    bankingSpecializedTraining?: BankingSpecializedTrainingData[];
    onSubmit: () => void;
    onPrevious: () => void;
    isLoading: boolean;
}

export function SummaryStep({
    industry,
    basicInfo,
    professionalSummary,
    onSummaryChange,
    workExperiences,
    educations,
    awards,
    projects,
    certificates,
    financeAcademicEducation,
    financeProfessionalEducation,
    bankingAcademicEducation,
    bankingProfessionalEducation,
    bankingSpecializedTraining,
    onSubmit,
    onPrevious,
    isLoading,
}: SummaryStepProps) {
    const [isGenerating, setIsGenerating] = useState(false);
    const [generationError, setGenerationError] = useState<string | null>(null);

    const industryLabel = INDUSTRY_OPTIONS.find((i) => i.value === industry)?.label || industry;

    const experienceLevelLabels: Record<string, string> = {
        entry: "Entry",
        junior: "Junior",
        mid: "Mid",
        senior: "Senior",
        lead: "Lead",
        principal: "Principal",
    };

    const availabilityLabels: Record<string, string> = {
        available: "Available",
        open_to_opportunities: "Open to opportunities",
        not_looking: "Not looking",
    };

    const employmentTypeLabels: Record<string, string> = {
        full_time: "Full time",
        part_time: "Part time",
        contract: "Contract",
        internship: "Internship",
        freelance: "Freelance",
        volunteer: "Volunteer",
    };

    const qualificationLabels: Record<string, string> = {
        bachelors_degree: "Bachelor's Degree",
        masters_degree: "Master's Degree",
        doctorate_phd: "Doctorate / PhD",
        undergraduate: "Undergraduate",
        post_graduate: "Post Graduate",
        diploma: "Diploma",
        certificate: "Certificate",
        professional_certification: "Professional Certification",
        vocational_training: "Vocational Training",
        no_formal_education: "No Formal Education",
    };

    const handleGenerateSummary = async () => {
        setIsGenerating(true);
        setGenerationError(null);

        try {
            // No banking skills anymore - removed

            const result = await generateProfessionalSummary(
                workExperiences.map((exp) => ({
                    jobTitle: exp.jobTitle,
                    company: exp.company,
                    description: exp.description,
                })),
                [], // skills array - empty now
                basicInfo.currentPosition,
                basicInfo.yearsOfExperience,
                industryLabel
            );

            if (result.success && result.summary) {
                onSummaryChange(result.summary);
            } else {
                setGenerationError(result.error || "Failed to generate summary");
            }
        } catch (error) {
            setGenerationError("An error occurred while generating summary");
            console.error("Summary generation error:", error);
        } finally {
            setIsGenerating(false);
        }
    };

    const canSubmit = professionalSummary.length >= 50;

    const validWorkExperiences = [...workExperiences]
        .filter(e => e.jobTitle || e.company)
        .sort((a, b) => {
            const dateA = a.startDate ? new Date(a.startDate).getTime() : 0;
            const dateB = b.startDate ? new Date(b.startDate).getTime() : 0;
            return dateB - dateA;
        });
    const validEducations = [...educations].filter(e => e.degreeDiploma || e.institution).reverse();
    const validAwards = [...awards].filter(a => a.natureOfAward).reverse();
    const validProjects = [...(projects || [])].filter(p => p.projectName).reverse();
    const validCertificates = [...(certificates || [])]
        .filter(c => c.certificateName)
        .sort((a, b) => {
            const dateA = a.issueDate ? new Date(a.issueDate).getTime() : 0;
            const dateB = b.issueDate ? new Date(b.issueDate).getTime() : 0;
            return dateB - dateA;
        });
    const validFinanceAcademic = [...(financeAcademicEducation || [])].filter(e => e.degreeDiploma || e.institution).reverse();
    const validFinanceProfessional = [...(financeProfessionalEducation || [])].filter(e => e.professionalQualification || e.institution).reverse();
    const validBankingAcademic = [...(bankingAcademicEducation || [])].filter(e => e.degreeDiploma || e.institution).reverse();
    const validBankingProfessional = [...(bankingProfessionalEducation || [])].filter(e => e.professionalQualification || e.institution).reverse();
    const validBankingSpecialized = [...(bankingSpecializedTraining || [])].filter(e => e.certificateName || e.issuingAuthority).reverse();

    const totalAcademicEducation = validFinanceAcademic.length + validBankingAcademic.length;
    const totalProfessionalEducation = validFinanceProfessional.length + validBankingProfessional.length;

    return (
        <div className="space-y-6">
            {/* Profile Summary Card */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <FileCheck2 className="h-5 w-5" />
                        Profile Summary
                    </CardTitle>
                    <CardDescription>
                        Review your profile information before submitting
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    {/* Basic Info Summary */}
                    <div>
                        <h4 className="font-medium mb-2">Personal Information</h4>
                        <div className="grid gap-2 text-sm text-muted-foreground">
                            <p><span className="font-medium text-foreground">{basicInfo.firstName} {basicInfo.lastName}</span></p>
                            <p>{basicInfo.email} • {basicInfo.phone}{basicInfo.alternativePhone ? ` • ${basicInfo.alternativePhone}` : ""}</p>
                            <p>{basicInfo.currentPosition} • {basicInfo.yearsOfExperience} years experience</p>
                            {basicInfo.address && <p>{basicInfo.address}</p>}
                            {basicInfo.country && <p>{basicInfo.country}</p>}
                            <p>Industry: <Badge variant="secondary">{industryLabel}</Badge></p>
                            <p>
                                Experience level: {experienceLevelLabels[basicInfo.experienceLevel] || basicInfo.experienceLevel}
                                {basicInfo.employmentType ? ` • ${employmentTypeLabels[basicInfo.employmentType] || basicInfo.employmentType}` : ""}
                            </p>
                            {basicInfo.expectedMonthlySalary != null && (
                                <p>Expected salary: {basicInfo.expectedMonthlySalary.toLocaleString()} / month</p>
                            )}
                            <p>
                                Availability: {availabilityLabels[basicInfo.availabilityStatus] || basicInfo.availabilityStatus}
                                {basicInfo.noticePeriod ? ` • Notice period: ${basicInfo.noticePeriod}` : ""}
                            </p>
                            {basicInfo.highestQualification && (
                                <p>Highest qualification: {qualificationLabels[basicInfo.highestQualification] || basicInfo.highestQualification}</p>
                            )}
                            {(basicInfo.expectedPositions ?? []).length > 0 && (
                                <div className="flex flex-wrap items-center gap-1">
                                    <span className="text-foreground font-medium">Expected Positions:</span>
                                    {(basicInfo.expectedPositions ?? []).map((pos, i) => (
                                        <Badge key={i} variant="outline" className="text-xs">{pos}</Badge>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Experience Summary */}
                    {validWorkExperiences.length > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">Experience ({validWorkExperiences.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-3">
                                {validWorkExperiences.map((exp, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {exp.jobTitle}{exp.company ? ` at ${exp.company}` : ''}</div>
                                        <div>
                                            {exp.startDate ? `${exp.startDate} to ${exp.isCurrent ? 'Present' : exp.endDate || '...'}` : 'Date not specified'}
                                            {exp.location ? ` • ${exp.location}` : ''}
                                            {exp.employmentType ? ` • ${employmentTypeLabels[exp.employmentType] || exp.employmentType}` : ''}
                                        </div>
                                        {exp.description && <div className="text-sm text-muted-foreground">{exp.description}</div>}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Education Summary */}
                    {validEducations.length > 0 && industry !== "finance_investment" && industry !== "banking" && (
                        <div>
                            <h4 className="font-medium mb-2">Education ({validEducations.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-3">
                                {validEducations.map((edu, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {edu.degreeDiploma}</div>
                                        <div>
                                            {edu.institution ? ` ${edu.institution}` : ''}
                                            {edu.status ? ` • ${edu.status}` : ''}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Awards */}
                    {validAwards.length > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">Awards ({validAwards.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-3">
                                {validAwards.map((award, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {award.natureOfAward}</div>
                                        <div>
                                            {award.offeredBy ? `Awarded by ${award.offeredBy}` : ''}
                                        </div>
                                        {award.description && <div className="text-sm text-muted-foreground">{award.description}</div>}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* IT Specific */}
                    {validProjects.length > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">Projects ({validProjects.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-3">
                                {validProjects.map((proj, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {proj.projectName}</div>
                                        {proj.demoUrl && <div>Demo: {proj.demoUrl}</div>}
                                        {proj.description && <div className="text-sm text-muted-foreground">{proj.description}</div>}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {validCertificates.length > 0 && IT_INDUSTRIES.includes(industry as any) && (
                        <div>
                            <h4 className="font-medium mb-2">Certificates ({validCertificates.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-3">
                                {validCertificates.map((cert, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {cert.certificateName}</div>
                                        <div>
                                            {cert.issuingAuthority ? `Issued by ${cert.issuingAuthority}` : ''}
                                            {cert.issueDate ? ` • ${cert.issueDate}` : ''}
                                            {cert.expiryDate ? ` • Expires ${cert.expiryDate}` : ''}
                                        </div>
                                        {cert.credentialUrl && <div className="text-sm text-muted-foreground">Credential: {cert.credentialUrl}</div>}
                                        {cert.description && <div className="text-sm text-muted-foreground">{cert.description}</div>}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Academic Education */}
                    {totalAcademicEducation > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">
                                Academic Education ({totalAcademicEducation})
                            </h4>
                            <ul className="text-sm text-muted-foreground space-y-1">
                                {validFinanceAcademic.map((edu, i) => (
                                    <li key={`fin-acad-${i}`}>• {edu.degreeDiploma} {edu.institution ? `- ${edu.institution}` : ''} {edu.status ? `(${edu.status})` : ''}</li>
                                ))}
                                {validBankingAcademic.map((edu, i) => (
                                    <li key={`bank-acad-${i}`}>• {edu.degreeDiploma} {edu.institution ? `- ${edu.institution}` : ''} {edu.status ? `(${edu.status})` : ''}</li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Professional Education */}
                    {totalProfessionalEducation > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">
                                Professional Education ({totalProfessionalEducation})
                            </h4>
                            <ul className="text-sm text-muted-foreground space-y-1">
                                {validFinanceProfessional.map((edu, i) => (
                                    <li key={`fin-prof-${i}`}>• {edu.professionalQualification} {edu.institution ? `- ${edu.institution}` : ''} {edu.status ? `(${edu.status})` : ''}</li>
                                ))}
                                {validBankingProfessional.map((edu, i) => (
                                    <li key={`bank-prof-${i}`}>• {edu.professionalQualification} {edu.institution ? `- ${edu.institution}` : ''} {edu.status ? `(${edu.status})` : ''}</li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {validBankingSpecialized.length > 0 && (
                        <div>
                            <h4 className="font-medium mb-2">Specialized Training ({validBankingSpecialized.length})</h4>
                            <ul className="text-sm text-muted-foreground space-y-1">
                                {validBankingSpecialized.map((training, i) => (
                                    <li key={i}>
                                        <div className="font-medium text-foreground">• {training.certificateName}</div>
                                        <div>
                                            {training.issuingAuthority ? `Issued by ${training.issuingAuthority}` : ''}
                                            {training.certificateIssueMonth ? ` • ${training.certificateIssueMonth}` : ''}
                                            {training.status ? ` • ${training.status}` : ''}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Professional Summary */}
            <FormSection
                title="Professional Summary"
                description="Write a compelling summary or let AI generate one based on your profile"
            >
                <div className="space-y-4">
                    <div className="space-y-2">
                        <div className="flex items-center justify-between">
                            <Label htmlFor="professionalSummary">
                                Summary <span className="text-destructive">*</span>
                            </Label>
                            <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                onClick={handleGenerateSummary}
                                disabled={isGenerating}
                            >
                                {isGenerating ? (
                                    <>
                                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                        Generating...
                                    </>
                                ) : (
                                    <>
                                        <Sparkles className="mr-2 h-4 w-4" />
                                        Generate with AI
                                    </>
                                )}
                            </Button>
                        </div>
                        <Textarea
                            id="professionalSummary"
                            value={professionalSummary}
                            onChange={(e) => onSummaryChange(e.target.value)}
                            placeholder="Write a compelling professional summary (minimum 50 characters)..."
                            rows={5}
                        />
                        <p className="text-xs text-muted-foreground">
                            {professionalSummary.length}/1000 characters (minimum 50)
                        </p>
                        {generationError && (
                            <p className="text-sm text-destructive">{generationError}</p>
                        )}
                    </div>
                </div>
            </FormSection>

            <StepNavigation
                currentStep={11}
                totalSteps={11}
                onPrevious={onPrevious}
                onNext={onSubmit}
                isLastStep
                isLoading={isLoading}
                canProceed={canSubmit}
            />
        </div>
    );
}

