import * as React from "react"

import type { ToastActionElement, ToastProps } from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
    id: string
    title?: React.ReactNode
    description?: React.ReactNode
    action?: ToastActionElement
}

const actionTypes = {
    ADD_TOAST: "ADD_TOAST",
    UPDATE_TOAST: "UPDATE_TOAST",
    DISMISS_TOAST: "DISMISS_TOAST",
    REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
    count = (count + 1) % Number.MAX_SAFE_INTEGER
    return count.toString()
}

type ActionType = typeof actionTypes

type Action =
    | {
        type: ActionType["ADD_TOAST"]
        toast: ToasterToast
    }
    | {
        type: ActionType["UPDATE_TOAST"]
        toast: Partial<ToasterToast>
    }
    | {
        type: ActionType["DISMISS_TOAST"]
        toastId?: ToasterToast["id"]
    }
    | {
        type: ActionType["REMOVE_TOAST"]
        toastId?: ToasterToast["id"]
    }

interface State {
    toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
    if (toastTimeouts.has(toastId)) {
        return
    }

    const timeout = setTimeout(() => {
        toastTimeouts.delete(toastId)
        dispatch({
            type: "REMOVE_TOAST",
            toastId: toastId,
        })
    }, TOAST_REMOVE_DELAY)

    toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
    switch (action.type) {
        case "ADD_TOAST":
            return {
                ...state,
                toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
            }

        case "UPDATE_TOAST":
            return {
                ...state,
                toasts: state.toasts.map((t) =>
                    t.id === action.toast.id ? { ...t, ...action.toast } : t
                ),
            }

        case "DISMISS_TOAST": {
            const { toastId } = action

            if (toastId) {
                addToRemoveQueue(toastId)
            } else {
                state.toasts.forEach((toast) => {
                    addToRemoveQueue(toast.id)
                })
            }

            return {
                ...state,
                toasts: state.toasts.map((t) =>
                    t.id === toastId || toastId === undefined
                        ? {
                            ...t,
                            open: false,
                        }
                        : t
                ),
            }
        }
        case "REMOVE_TOAST":
            if (action.toastId === undefined) {
                return {
                    ...state,
                    toasts: [],
                }
            }
            return {
                ...state,
                toasts: state.toasts.filter((t) => t.id !== action.toastId),
            }
    }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
    memoryState = reducer(memoryState, action)
    listeners.forEach((listener) => {
        listener(memoryState)
    })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
    const id = genId()

    const update = (props: ToasterToast) =>
        dispatch({
            type: "UPDATE_TOAST",
            toast: { ...props, id },
        })
    const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

    dispatch({
        type: "ADD_TOAST",
        toast: {
            ...props,
            id,
            open: true,
            onOpenChange: (open) => {
                if (!open) dismiss()
            },
        },
    })

    return {
        id: id,
        dismiss,
        update,
    }
}

function useToast() {
    const [state, setState] = React.useState<State>(memoryState)

    React.useEffect(() => {
        listeners.push(setState)
        return () => {
            const index = listeners.indexOf(setState)
            if (index > -1) {
                listeners.splice(index, 1)
            }
        }
    }, [state])

    return {
        ...state,
        toast,
        dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
    }
}

export { useToast, toast }

'use client';

import { useEffect, useState } from 'react';

const HEADER_OFFSET = 88;

function getSectionTop(el: HTMLElement) {
    return el.getBoundingClientRect().top + window.scrollY;
}

/**
 * Highlights the landing nav item for the section currently in view.
 * Sections are resolved in DOM order (not nav label order).
 */
export function useLandingSectionSpy(sectionIds: string[]) {
    const [activeId, setActiveId] = useState('');

    useEffect(() => {
        const resolveSections = () =>
            sectionIds
                .map((id) => document.getElementById(id))
                .filter((el): el is HTMLElement => el !== null)
                .sort((a, b) => getSectionTop(a) - getSectionTop(b));

        const computeActive = () => {
            const sections = resolveSections();
            if (!sections.length) return;

            const marker = window.scrollY + HEADER_OFFSET;
            const firstTop = getSectionTop(sections[0]);

            if (marker < firstTop - 48) {
                setActiveId('');
                return;
            }

            let current = sections[0].id;
            for (const section of sections) {
                if (getSectionTop(section) <= marker) {
                    current = section.id;
                }
            }
            setActiveId(current);
        };

        let raf = 0;
        const onScroll = () => {
            cancelAnimationFrame(raf);
            raf = requestAnimationFrame(computeActive);
        };

        computeActive();
        window.addEventListener('scroll', onScroll, { passive: true });
        window.addEventListener('resize', onScroll);

        return () => {
            cancelAnimationFrame(raf);
            window.removeEventListener('scroll', onScroll);
            window.removeEventListener('resize', onScroll);
        };
    }, [sectionIds.join('|')]);

    return activeId;
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { createClient } from "@/lib/supabase/client";
import { RealtimeChannel } from "@supabase/supabase-js";
import { toast } from "./use-toast";

export interface Notification {
  id: string;
  user_id: string;
  type: string;
  title: string;
  body: string | null;
  data: Record<string, any> | null;
  is_read: boolean;
  created_at: string;
}

export interface NotificationsState {
  notifications: Notification[];
  unreadCount: number;
  loading: boolean;
  error: string | null;
}

export interface UseNotificationsReturn extends NotificationsState {
  markAsRead: (notificationId: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  deleteNotification: (notificationId: string) => Promise<void>;
  refresh: () => Promise<void>;
}

export function useNotifications(): UseNotificationsReturn {
  const [state, setState] = useState<NotificationsState>({
    notifications: [],
    unreadCount: 0,
    loading: true,
    error: null,
  });

  const supabase = createClient();

  // Fetch notifications from the database
  const fetchNotifications = useCallback(async () => {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      // Get current user
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (userError || !user) {
        setState((prev) => ({
          ...prev,
          loading: false,
          error: "User not authenticated",
        }));
        return;
      }

      // Fetch notifications ordered by created_at DESC
      const { data, error } = await supabase
        .from("notifications")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(50);

      if (error) {
        setState((prev) => ({
          ...prev,
          loading: false,
          error: error.message,
        }));
        return;
      }

      const notifications = (data || []) as Notification[];
      const unreadCount = notifications.filter((n) => !n.is_read).length;

      setState({
        notifications,
        unreadCount,
        loading: false,
        error: null,
      });
    } catch (error) {
      setState((prev) => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : "Unknown error",
      }));
    }
  }, [supabase]);

  // Mark a single notification as read
  const markAsRead = useCallback(
    async (notificationId: string) => {
      try {
        const { error } = await supabase
          .from("notifications")
          .update({ is_read: true })
          .eq("id", notificationId);

        if (error) throw error;

        // Update local state
        setState((prev) => ({
          ...prev,
          notifications: prev.notifications.map((n) =>
            n.id === notificationId ? { ...n, is_read: true } : n
          ),
          unreadCount: Math.max(
            0,
            prev.unreadCount -
              (prev.notifications.find((n) => n.id === notificationId)
                ?.is_read
                ? 0
                : 1)
          ),
        }));
      } catch (error) {
        console.error("Error marking notification as read:", error);
      }
    },
    [supabase]
  );

  // Mark all notifications as read
  const markAllAsRead = useCallback(async () => {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      const { error } = await supabase
        .from("notifications")
        .update({ is_read: true })
        .eq("user_id", user.id)
        .eq("is_read", false);

      if (error) throw error;

      // Update local state
      setState((prev) => ({
        ...prev,
        notifications: prev.notifications.map((n) => ({ ...n, is_read: true })),
        unreadCount: 0,
      }));
    } catch (error) {
      console.error("Error marking all as read:", error);
    }
  }, [supabase]);

  // Delete a notification
  const deleteNotification = useCallback(
    async (notificationId: string) => {
      try {
        const { error } = await supabase
          .from("notifications")
          .delete()
          .eq("id", notificationId);

        if (error) throw error;

        // Update local state
        setState((prev) => ({
          ...prev,
          notifications: prev.notifications.filter((n) => n.id !== notificationId),
          unreadCount: Math.max(
            0,
            prev.unreadCount -
              (prev.notifications.find((n) => n.id === notificationId)
                ?.is_read
                ? 0
                : 1)
          ),
        }));
      } catch (error) {
        console.error("Error deleting notification:", error);
      }
    },
    [supabase]
  );

  // Setup Realtime subscription
  useEffect(() => {
    let channel: RealtimeChannel | null = null;

    const setupRealtimeSubscription = async () => {
      // Get current user
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;

      // Create a channel for notifications
      channel = supabase
        .channel(`notifications:${user.id}`)
        .on(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${user.id}`,
          },
          (payload) => {
            const newNotification = payload.new as Notification;

            // Add to local state
            setState((prev) => ({
              ...prev,
              notifications: [newNotification, ...prev.notifications],
              unreadCount: prev.unreadCount + 1,
            }));

            // Show toast notification
            toast({
              title: newNotification.title,
              description: newNotification.body || undefined,
              duration: 5000,
            });
          }
        )
        .on(
          "postgres_changes",
          {
            event: "UPDATE",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${user.id}`,
          },
          (payload) => {
            const updatedNotification = payload.new as Notification;

            // Update local state
            setState((prev) => ({
              ...prev,
              notifications: prev.notifications.map((n) =>
                n.id === updatedNotification.id ? updatedNotification : n
              ),
              unreadCount: prev.notifications.filter(
                (n) =>
                  !n.is_read &&
                  (n.id !== updatedNotification.id || !updatedNotification.is_read)
              ).length,
            }));
          }
        )
        .on(
          "postgres_changes",
          {
            event: "DELETE",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${user.id}`,
          },
          (payload) => {
            const deletedId = payload.old.id as string;

            // Remove from local state
            setState((prev) => {
              const deletedNotification = prev.notifications.find(
                (n) => n.id === deletedId
              );
              return {
                ...prev,
                notifications: prev.notifications.filter(
                  (n) => n.id !== deletedId
                ),
                unreadCount: Math.max(
                  0,
                  prev.unreadCount -
                    (deletedNotification && !deletedNotification.is_read ? 1 : 0)
                ),
              };
            });
          }
        )
        .subscribe();
    };

    // Initial fetch
    fetchNotifications();

    // Setup realtime subscription
    setupRealtimeSubscription();

    // Cleanup
    return () => {
      if (channel) {
        supabase.removeChannel(channel);
      }
    };
  }, [supabase, fetchNotifications]);

  return {
    ...state,
    markAsRead,
    markAllAsRead,
    deleteNotification,
    refresh: fetchNotifications,
  };
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { createClient } from "@/lib/supabase/client";
import type { RealtimeChannel } from "@supabase/supabase-js";

type Filter = { column: string; value: string };

interface CountQuery {
    table: string;
    /** Equality filters applied to the count query, e.g. [{ column: 'candidate_id', value: '...' }] */
    filters: Filter[];
    /** Optional IS NULL checks, e.g. ['viewed_at'] */
    isNullColumns?: string[];
    /** Optional equality checks for string columns, e.g. [{ column: 'invitation_canceled', value: 'false' }] — use for booleans cast as text */
    eqFilters?: Filter[];
    /** Optional .in() filter, e.g. { column: 'status', values: ['pending_payment', 'rejected'] } */
    inFilter?: { column: string; values: string[] };
}

interface UseRealtimeCountReturn {
    count: number;
    isLoading: boolean;
}

/**
 * Fetches a row count from Supabase directly (no HTTP API call after mount)
 * and keeps it live via a Postgres Changes subscription on the same table.
 * One WebSocket connection shared across all realtime subscriptions on the page.
 */
export function useRealtimeCount(
    query: CountQuery,
    /** Realtime filter string, e.g. 'candidate_id=eq.{id}'. Leave empty to watch all rows. */
    realtimeFilter?: string
): UseRealtimeCountReturn {
    const [count, setCount] = useState(0);
    const [isLoading, setIsLoading] = useState(true);
    const supabase = createClient();

    const fetchCount = useCallback(async () => {
        let q = supabase
            .from(query.table)
            .select("*", { count: "exact", head: true });

        for (const f of query.filters) {
            q = q.eq(f.column, f.value);
        }
        for (const col of query.isNullColumns ?? []) {
            q = q.is(col, null);
        }
        for (const f of query.eqFilters ?? []) {
            q = q.eq(f.column, f.value);
        }
        if (query.inFilter) {
            q = q.in(query.inFilter.column, query.inFilter.values);
        }

        const { count: result, error } = await q;
        if (!error) setCount(result ?? 0);
        setIsLoading(false);
    }, [supabase, query.table]); // eslint-disable-line react-hooks/exhaustive-deps

    useEffect(() => {
        let channel: RealtimeChannel | null = null;
        let cancelled = false;

        fetchCount();

        const channelName = `realtime-count-${query.table}-${realtimeFilter ?? "all"}`;
        channel = supabase
            .channel(channelName)
            .on(
                "postgres_changes",
                {
                    event: "*",
                    schema: "public",
                    table: query.table,
                    ...(realtimeFilter ? { filter: realtimeFilter } : {}),
                },
                () => {
                    if (!cancelled) fetchCount();
                }
            )
            .subscribe();

        return () => {
            cancelled = true;
            if (channel) supabase.removeChannel(channel);
        };
