        const baseUrl = getBaseUrl();
        const resetUrl = `${baseUrl}/reset-password?token=${token}`;

        // Check if Resend is configured
        if (!process.env.RESEND_API_KEY) {
            console.log(`\n====================================`);
            console.log(`[DEV] Password Reset Email`);
            console.log(`====================================`);
            console.log(`To: ${email}`);
            console.log(`Name: ${firstName}`);
            console.log(`Reset URL: ${resetUrl}`);
            console.log(`Token: ${token}`);
            console.log(`Expires: 1 hour from now`);
            console.log(`====================================\n`);
            console.log("[DEV] Resend not configured. Set RESEND_API_KEY in .env to send actual emails.");
            return { success: true };
        }

        console.log(`[DEBUG] Attempting to send password reset email...`);
        console.log(`[DEBUG] From: JobGenie <${EMAIL_FROM}>`);
        console.log(`[DEBUG] To: ${email}`);
        console.log(`[DEBUG] Resend API Key present: ${!!process.env.RESEND_API_KEY}`);

        const result = await resend.emails.send({
            from: `JobGenie <${EMAIL_FROM}>`,
            to: email,
            subject: "🔑 Reset Your Password - JobGenie",
            html: getPasswordResetEmailTemplate(firstName, resetUrl),
        });

        console.log(`[DEBUG] Resend API response:`, JSON.stringify(result, null, 2));

        if (result.error) {
            console.error("Password reset email error:", result.error);
            return {
                success: false,
                error: "Failed to send password reset email",
            };
        }

        console.log(`[EMAIL] ✅ Password reset email sent successfully to ${email}`);
        console.log(`[EMAIL] Email ID: ${result.data?.id}`);
        return { success: true };
    } catch (error) {
        console.error("Password reset email error:", error);
        return {
            success: false,
            error: "Failed to send password reset email",
        };
    }
}

import { PDFDocument, rgb, StandardFonts } from "pdf-lib";
import type { CompleteProfileData } from "@/lib/validations/profile-schema";

export interface CandidateBasicInfo {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  currentPosition: string;
  industry: string;
  yearsOfExperience?: number;
  professionalSummary?: string;
}

// Color palette for professional CV
const COLORS = {
  primary: rgb(0.125, 0.251, 0.376), // #204060 - Dark blue
  secondary: rgb(0.282, 0.518, 0.741), // #4884BD - Medium blue
  text: rgb(0.2, 0.2, 0.2), // Dark gray for text
  lightText: rgb(0.4, 0.4, 0.4), // Light gray for secondary text
  accent: rgb(0.125, 0.251, 0.376), // Accent color
  border: rgb(0.8, 0.8, 0.8), // Light border
};

const LAYOUT = {
  margin: 50,
  lineHeight: 14,
  sectionSpacing: 20,
  itemSpacing: 12,
  headerHeight: 80,
};

/**
 * Generates a professional, standardized Common CV PDF from candidate profile data
 */
export async function generateCommonCV(
  profileData: CompleteProfileData,
  candidateInfo: CandidateBasicInfo
): Promise<Uint8Array> {
  const pdfDoc = await PDFDocument.create();
  const timesRoman = await pdfDoc.embedFont(StandardFonts.TimesRoman);
  const timesRomanBold = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
  const helvetica = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let page = pdfDoc.addPage([595, 842]); // A4 size
  const { width, height } = page.getSize();
  let yPosition = height - LAYOUT.margin;

  // Helper function to check if we need a new page
  const checkPageBreak = (requiredSpace: number) => {
    if (yPosition - requiredSpace < LAYOUT.margin) {
      page = pdfDoc.addPage([595, 842]);
      yPosition = height - LAYOUT.margin;
      return true;
    }
    return false;
  };

  // Helper function to sanitize text for PDF (remove newlines and control characters)
  const sanitizeText = (text: string): string => {
    if (!text) return "";
    // Replace newlines, carriage returns, and tabs with spaces
    // Remove other control characters
    return text
      .replace(/[\r\n\t]/g, " ")
      .replace(/[\x00-\x1F\x7F]/g, "")
      .trim();
  };

  // Safe wrapper for page.drawText that auto-sanitizes
  const safeDrawText = (text: string, options: Parameters<typeof page.drawText>[1]) => {
    page.drawText(sanitizeText(text), options);
  };

  // Helper function to draw text with wrapping
  const drawWrappedText = (
    text: string,
    x: number,
    maxWidth: number,
    font: any,
    size: number,
    color: any
  ) => {
    // Sanitize the text first
    const sanitizedText = sanitizeText(text);
    if (!sanitizedText) return;

    const words = sanitizedText.split(" ");
    let line = "";
    const lines: string[] = [];

    words.forEach((word) => {
      const testLine = line + word + " ";
      const testWidth = font.widthOfTextAtSize(testLine, size);

      if (testWidth > maxWidth && line !== "") {
        lines.push(line.trim());
        line = word + " ";
      } else {
        line = testLine;
      }
    });
    if (line.trim() !== "") {
      lines.push(line.trim());
    }

    lines.forEach((line) => {
      checkPageBreak(LAYOUT.lineHeight + 5);
      safeDrawText(line, {
        x,
        y: yPosition,
        size,
        font,
        color,
      });
      yPosition -= LAYOUT.lineHeight;
    });
  };

  // Helper function to draw section header
  const drawSectionHeader = (title: string) => {
    checkPageBreak(30);
    yPosition -= LAYOUT.sectionSpacing;

    safeDrawText(title.toUpperCase(), {
      x: LAYOUT.margin,
      y: yPosition,
      size: 14,
      font: helveticaBold,
      color: COLORS.primary,
    });

    yPosition -= 5;
    page.drawLine({
      start: { x: LAYOUT.margin, y: yPosition },
      end: { x: width - LAYOUT.margin, y: yPosition },
      thickness: 2,
      color: COLORS.secondary,
    });
    yPosition -= 10;
  };

  // ============ HEADER SECTION ============
  const fullName = `${candidateInfo.firstName} ${candidateInfo.lastName}`;

  safeDrawText(fullName, {
    x: LAYOUT.margin,
    y: yPosition,
    size: 24,
    font: helveticaBold,
    color: COLORS.primary,
  });
  yPosition -= 30;

  safeDrawText(candidateInfo.currentPosition, {
    x: LAYOUT.margin,
    y: yPosition,
    size: 12,
    font: helveticaBold,
